/* 德语「🗣 口语」的内容（speak.js 学德语时用，结构和 speak-data.js 完全一样，"en" 字段里放德语）：情景对话 dialogs、常用表达 functions、口语 / 语气词 slang、句型操练 drills、
   重音 stress、绕口令 twisters、发音 pron（最小对立词 pairs、发音规则和口语缩读 connected、跟读句 shadow）、话题卡 topics、快问快答 quick、新手入门 starter。
   由 Claude 生成，另一轮独立校对；改内容直接改这个文件里的 JSON。 */
window.SPEAK_DATA = {"dialogs":[{"id":"baeckerei_fruehstueck","title":"在面包店买早餐","en_title":"In der Bäckerei","level":"入门","scene":"周六早上你在汉堡街角的面包店买小面包，顺便尝一个当地特色的肉桂卷，再带一杯咖啡走。","roles":{"A":"面包店店员","B":"顾客"},"lines":[{"who":"A","en":"Guten Morgen! Was darf's sein?","zh":"早上好！要点什么？"},{"who":"B","en":"Guten Morgen! Ich hätte gern zwei Brötchen, bitte.","zh":"早上好！我想要两个小面包，谢谢。"},{"who":"A","en":"Normale Brötchen oder Körnerbrötchen?","zh":"普通的还是杂粮的？"},{"who":"B","en":"Ein normales und ein Körnerbrötchen, bitte.","zh":"一个普通的，一个杂粮的。"},{"who":"A","en":"Gern. Sonst noch etwas?","zh":"好的。还要别的吗？"},{"who":"B","en":"Ja, was ist das hier?","zh":"要，这个是什么？"},{"who":"A","en":"Das ist ein Franzbrötchen, mit Zimt und Zucker. Eine Hamburger Spezialität.","zh":"这是 Franzbrötchen，里面有肉桂和糖，是汉堡的特产。"},{"who":"B","en":"Klingt lecker. Dann nehme ich auch eins.","zh":"听起来很好吃。那我也要一个。"},{"who":"A","en":"Möchten Sie noch einen Kaffee dazu?","zh":"还要配一杯咖啡吗？"},{"who":"B","en":"Ja, einen Kaffee zum Mitnehmen, bitte. Mit Milch, ohne Zucker.","zh":"要，一杯咖啡外带。加奶，不加糖。"},{"who":"A","en":"Das macht dann 6,40 Euro.","zh":"一共 6.40 欧元。"},{"who":"B","en":"Kann ich mit Karte zahlen?","zh":"可以刷卡吗？"},{"who":"A","en":"Ja, klar. Halten Sie die Karte einfach ans Gerät.","zh":"当然。把卡贴到机器上就行。"},{"who":"B","en":"Danke schön! Schönes Wochenende!","zh":"谢谢！周末愉快！"}],"phrases":[["Was darf's sein?","店员常用开场：“要点什么？”，darf's = darf es"],["Ich hätte gern …","点东西最礼貌自然的说法，比 Ich will … 客气得多"],["Sonst noch etwas?","还要别的吗？不要了就答 Nein, danke, das war's."],["Dann nehme ich auch eins.","那我也要一个；eins 指代中性名词 das Franzbrötchen"],["zum Mitnehmen / zum Hieressen","外带 / 在这儿吃"],["Das macht … Euro.","一共……欧元（结账时店员说）"]],"tip":"Brötchen 是中性名词 das Brötchen，复数不变（zwei Brötchen）。说“一个普通的”要跟着词性变：ein normales（Brötchen）。ö 要撮圆嘴唇发，别读成 o。"},{"id":"team_call_vorstellung","title":"团队视频会议上自我介绍","en_title":"Vorstellungsrunde im Team-Call","level":"入门","scene":"你刚加入一个德国团队，第一次参加视频会议，组长 Katrin 请你简单介绍一下自己。","roles":{"A":"组长 Katrin","B":"你（新同事）"},"lines":[{"who":"A","en":"Guten Morgen zusammen! Heute ist Ray zum ersten Mal dabei. Ray, möchten Sie sich kurz vorstellen?","zh":"大家早上好！今天 Ray 第一次参加。Ray，您想简单介绍一下自己吗？"},{"who":"B","en":"Ja, gern. Guten Morgen! Ich heiße Ray und komme aus China.","zh":"好的。早上好！我叫 Ray，来自中国。"},{"who":"A","en":"Und wo wohnen Sie jetzt?","zh":"您现在住在哪儿？"},{"who":"B","en":"Ich wohne in Kuala Lumpur, in Malaysia.","zh":"我住在马来西亚的吉隆坡。"},{"who":"A","en":"Was machen Sie bei uns im Team?","zh":"您在我们团队负责什么？"},{"who":"B","en":"Ich bin Softwareentwickler und arbeite vor allem im Backend.","zh":"我是软件开发人员，主要做后端。"},{"who":"A","en":"Super. Sprechen Sie schon ein bisschen Deutsch?","zh":"很好。您已经会说一点德语了吗？"},{"who":"B","en":"Ja, ein bisschen. Ich lerne seit ein paar Monaten Deutsch. Bitte sprechen Sie langsam!","zh":"会一点。我学德语几个月了，请大家说慢一点！"},{"who":"A","en":"Kein Problem! Übrigens duzen sich bei uns im Team alle. Ist das okay für dich?","zh":"没问题！顺便说一下，我们团队大家都用 du 互相称呼。你觉得可以吗？"},{"who":"B","en":"Ja, sehr gern! Ich freue mich auf die Zusammenarbeit.","zh":"当然好！我很期待和大家合作。"},{"who":"A","en":"Wir uns auch. Herzlich willkommen im Team, Ray!","zh":"我们也是。热烈欢迎你加入团队，Ray！"},{"who":"B","en":"Danke schön!","zh":"谢谢！"}],"phrases":[["sich vorstellen","自我介绍；Darf ich mich kurz vorstellen? 我简单介绍一下自己"],["Ich heiße … und komme aus …","我叫……，来自……（最基本的自我介绍句型）"],["Ich bin Softwareentwickler.","说职业不加冠词，不说 ein Softwareentwickler"],["Ich lerne seit … Deutsch.","我学德语……了；持续到现在的事用现在时 + seit"],["Bitte sprechen Sie langsam!","请说慢一点！初学者必备"],["sich duzen","互相用 du 称呼；对应 sich siezen 用 Sie"],["Ich freue mich auf die Zusammenarbeit.","我期待合作；sich freuen auf + 第四格 = 期待将来的事"]],"tip":"德国很多科技公司内部都用 du，但第一次见面先用 Sie，等对方提出 duzen 再改。注意本段中 Katrin 提出后就从 Sie 换成了 dich。Softwareentwickler 里的 w 读 [v]。"},{"id":"cafe_bestellen","title":"在咖啡馆点单","en_title":"Im Café","level":"入门","scene":"你在慕尼黑一家咖啡馆坐下，服务员来点单，你点咖啡和蛋糕，最后结账并给小费。","roles":{"A":"服务员","B":"客人"},"lines":[{"who":"A","en":"Hallo! Was möchten Sie trinken?","zh":"您好！您想喝点什么？"},{"who":"B","en":"Ich nehme einen Cappuccino, bitte.","zh":"我要一杯卡布奇诺。"},{"who":"A","en":"Mit Hafermilch oder mit normaler Milch?","zh":"用燕麦奶还是普通牛奶？"},{"who":"B","en":"Mit Hafermilch, bitte. Haben Sie auch Kuchen?","zh":"燕麦奶，谢谢。你们也有蛋糕吗？"},{"who":"A","en":"Ja, heute haben wir Apfelstrudel und Käsekuchen.","zh":"有，今天有苹果卷和奶酪蛋糕。"},{"who":"B","en":"Dann hätte ich gern ein Stück Käsekuchen.","zh":"那我要一块奶酪蛋糕。"},{"who":"A","en":"Mit Sahne?","zh":"要加奶油吗？"},{"who":"B","en":"Nein, danke. Ohne Sahne.","zh":"不用了，谢谢。不加奶油。"},{"who":"B","en":"Entschuldigung, ich möchte bitte zahlen.","zh":"（过了一会儿）不好意思，我想买单。"},{"who":"A","en":"Gern. Das sind 8,90 Euro.","zh":"好的。一共 8.90 欧元。"},{"who":"B","en":"Machen Sie zehn, bitte.","zh":"算 10 欧吧（多的是小费）。"},{"who":"A","en":"Vielen Dank! Einen schönen Tag noch!","zh":"非常感谢！祝您今天愉快！"},{"who":"B","en":"Danke, Ihnen auch!","zh":"谢谢，您也是！"}],"phrases":[["Ich nehme …","我要……；点单时和 Ich hätte gern … 一样常用"],["Mit … oder mit …?","要……还是……？服务员确认选项的问法"],["ein Stück Kuchen","一块蛋糕；das Stück 是“块、份”"],["Ich möchte bitte zahlen.","我想买单；更简短的说法是 Zahlen, bitte!"],["Machen Sie zehn.","凑整到 10 欧，差额当小费；不用找零也可说 Stimmt so."],["Ihnen auch!","您也是！别说 Sie auch，这里要用第三格 Ihnen"]],"tip":"德国小费一般凑整或加 5–10%，付钱时直接告诉服务员总数（Machen Sie zehn），一般不会把钱留在桌上就走。叫服务员说 Entschuldigung! 或举手示意就行，不要拍手或隔着老远大声喊。"},{"id":"daily_standup","title":"每日站会汇报","en_title":"Im Daily Stand-up","level":"基础","scene":"团队每天早上开 15 分钟站会，大家互相用 du。轮到你汇报：昨天做了什么、今天做什么、有没有阻碍。","roles":{"A":"Scrum Master Tobias","B":"你"},"lines":[{"who":"A","en":"Ray, du bist dran. Was hast du gestern gemacht?","zh":"Ray，轮到你了。你昨天做了什么？"},{"who":"B","en":"Gestern habe ich das neue Login-Formular fertiggestellt und einen Pull Request erstellt.","zh":"昨天我把新的登录表单做完了，并提了一个 Pull Request。"},{"who":"A","en":"Sehr gut. Hat schon jemand den Pull Request reviewt?","zh":"很好。已经有人 review 过了吗？"},{"who":"B","en":"Noch nicht. Es wäre super, wenn ihn heute jemand anschauen könnte.","zh":"还没有。要是今天有人能看一下就太好了。"},{"who":"A","en":"Ich kann das nach dem Mittagessen machen. Und was steht heute bei dir an?","zh":"我午饭后可以看。那你今天要做什么？"},{"who":"B","en":"Heute arbeite ich an der Funktion zum Zurücksetzen des Passworts. Ich denke, bis morgen bin ich damit fertig.","zh":"今天我做重置密码的功能。我觉得明天前能做完。"},{"who":"A","en":"Gibt es irgendwelche Blocker?","zh":"有什么阻碍吗？"},{"who":"B","en":"Ja, ein kleines Problem: Ich habe noch keinen Zugang zum Testserver.","zh":"有一个小问题：我还没有测试服务器的权限。"},{"who":"A","en":"Okay, darum kümmere ich mich direkt nach dem Meeting.","zh":"好，开完会我马上处理这个。"},{"who":"B","en":"Danke! Ach, und morgen Nachmittag bin ich nicht da. Ich habe einen Arzttermin.","zh":"谢谢！哦对了，我明天下午不在，要去看医生。"},{"who":"A","en":"Kein Problem. Trag das bitte in den Teamkalender ein.","zh":"没问题。请把它写进团队日历。"},{"who":"B","en":"Mache ich. Das war's von mir.","zh":"好的。我就说这些。"},{"who":"A","en":"Danke, Ray. Dann ist Lisa als Nächste dran.","zh":"谢谢 Ray。下一个是 Lisa。"}],"phrases":[["Du bist dran.","轮到你了；Wer ist als Nächstes dran? 下一个是谁？"],["einen Pull Request erstellen","提一个 PR；技术词直接用英文，动词用德语"],["Was steht heute bei dir an?","你今天有什么要做的？anstehen = 待办、即将要做"],["Ich bin bis morgen damit fertig.","我明天之前能做完；damit 指代前面说的任务"],["keinen Zugang zu … haben","没有……的权限/访问权；zu + 第三格：zum Testserver"],["sich um etwas kümmern","负责处理某事；darum kümmere ich mich 这事我来处理"],["Das war's von mir.","我说完了（汇报结束时说）"]],"tip":"站会最实用的两种时态：昨天的事用现在完成时（Ich habe … erstellt），今天和计划用现在时（Heute arbeite ich an …）。英文动词德语化后按德语变位：reviewen 的过去分词是 reviewt。"},{"id":"supermarkt_kasse","title":"超市结账","en_title":"An der Supermarktkasse","level":"入门","scene":"你在德国超市排队结账，收银员问你有没有会员卡、要不要袋子，你还要交一张退瓶押金的单子。","roles":{"A":"收银员","B":"顾客"},"lines":[{"who":"A","en":"Hallo! Haben Sie eine Kundenkarte?","zh":"您好！您有会员卡吗？"},{"who":"B","en":"Nein, leider nicht.","zh":"没有，可惜。"},{"who":"A","en":"Kein Problem. Brauchen Sie eine Tüte?","zh":"没关系。需要袋子吗？"},{"who":"B","en":"Ja, bitte. Eine große.","zh":"要，一个大的。"},{"who":"A","en":"Die Tüte kostet 20 Cent.","zh":"袋子要 20 欧分。"},{"who":"B","en":"Okay. Ach, und ich habe noch einen Pfandbon.","zh":"好的。哦对了，我还有一张瓶子押金单。"},{"who":"A","en":"Danke. Das sind 2,25 Euro Pfand. Dann macht das zusammen 17,35 Euro.","zh":"谢谢。押金退 2.25 欧。那一共是 17.35 欧。"},{"who":"B","en":"Ich zahle bar. Hier sind 20 Euro.","zh":"我付现金。这是 20 欧。"},{"who":"A","en":"Und 2,65 Euro zurück. Möchten Sie den Kassenbon?","zh":"找您 2.65 欧。要小票吗？"},{"who":"B","en":"Nein, danke. Schönen Tag noch!","zh":"不用，谢谢。祝您今天愉快！"},{"who":"A","en":"Danke, gleichfalls!","zh":"谢谢，您也是！"}],"phrases":[["Haben Sie eine Kundenkarte?","您有会员卡吗？很多超市的收银员都会问"],["Brauchen Sie eine Tüte?","需要袋子吗？德国超市袋子要付钱"],["der Pfandbon / das Pfand","退瓶机打出的押金单 / 押金"],["Ich zahle bar. / Ich zahle mit Karte.","我付现金 / 我刷卡"],["Möchten Sie den Kassenbon?","要小票吗？der Bon 也常单独用"],["Gleichfalls!","您也是！同样祝您！回应祝福的万能词"]],"tip":"德国大部分塑料瓶和易拉罐有押金（Pfand），用超市里的退瓶机退瓶会打出 Pfandbon，结账时交给收银员抵钱。德国收银速度很快，最好提前准备好袋子和付款方式。"},{"id":"ueber_malaysia_erzaehlen","title":"和德国同事聊马来西亚","en_title":"Über Malaysia erzählen","level":"基础","scene":"视频会议开始前几分钟，一位还不太熟的德国同事 Frau Schulz 好奇地问你在吉隆坡的生活。","roles":{"A":"德国同事 Frau Schulz","B":"你"},"lines":[{"who":"A","en":"Sagen Sie mal, Ray, wie ist eigentlich das Leben in Kuala Lumpur?","zh":"对了 Ray，吉隆坡的生活到底是什么样的？"},{"who":"B","en":"Ehrlich gesagt sehr angenehm. Die Stadt ist modern und das Essen ist fantastisch.","zh":"说实话很舒服。城市很现代，吃的特别棒。"},{"who":"A","en":"Ist es dort nicht immer sehr heiß?","zh":"那里不是一直很热吗？"},{"who":"B","en":"Doch, es ist das ganze Jahr über warm, ungefähr 30 Grad. Und am Nachmittag regnet es oft.","zh":"是的，一年到头都很暖和，大约 30 度。下午经常下雨。"},{"who":"A","en":"Welche Sprachen spricht man dort?","zh":"那里说什么语言？"},{"who":"B","en":"Die Amtssprache ist Malaiisch, aber viele Leute sprechen auch Englisch, Chinesisch oder Tamil.","zh":"官方语言是马来语，不过很多人也说英语、华语或泰米尔语。"},{"who":"A","en":"Interessant! Und was sollte man dort unbedingt essen?","zh":"有意思！那在那儿一定要吃什么？"},{"who":"B","en":"Auf jeden Fall Nasi Lemak. Das ist Reis mit Kokosmilch, dazu gibt es Erdnüsse, ein Ei und Sambal.","zh":"一定要吃椰浆饭。就是用椰奶煮的米饭，配花生、鸡蛋和参巴辣酱。"},{"who":"A","en":"Klingt lecker! Ist das sehr scharf?","zh":"听起来很好吃！很辣吗？"},{"who":"B","en":"Ein bisschen. Aber man kann das Sambal auch weglassen. Wenn Sie mal nach KL kommen, zeige ich Ihnen die besten Restaurants.","zh":"有点辣。不过参巴酱也可以不要。您要是来吉隆坡，我带您去最好的餐馆。"},{"who":"A","en":"Das Angebot nehme ich gern an!","zh":"这个邀请我很乐意接受！"},{"who":"B","en":"Sehr gern. Sagen Sie einfach Bescheid!","zh":"非常欢迎。到时候跟我说一声就行！"}],"phrases":[["Ehrlich gesagt …","说实话……；放句首后面直接接内容或动词"],["das ganze Jahr über","一年到头、整年"],["Doch!","回答否定问句时表示肯定：Ist es nicht heiß? – Doch!"],["die Amtssprache","官方语言"],["Das ist … mit …","这是……配/加……；介绍食物的万能句型"],["etwas weglassen","省掉、不放某物（可分动词）"],["Sagen Sie einfach Bescheid.","跟我说一声就行；Bescheid sagen = 通知、打招呼"]],"tip":"回答否定问句（Ist es nicht heiß?）时，要表示“不，其实很热”应该用 Doch；用 Ja 意思含糊，容易让人误会——这是中国人最常犯的错之一。不太熟的同事先用 Sie，即使称呼名字（Ray）也一样。"},{"id":"fahrkarte_kaufen","title":"在火车站买票","en_title":"Eine Fahrkarte kaufen","level":"入门","scene":"你在法兰克福中央车站的售票中心买去海德堡的往返火车票。","roles":{"A":"售票员","B":"旅客"},"lines":[{"who":"A","en":"Guten Tag! Wohin möchten Sie fahren?","zh":"您好！您要去哪儿？"},{"who":"B","en":"Guten Tag! Ich möchte nach Heidelberg fahren.","zh":"您好！我想去海德堡。"},{"who":"A","en":"Wann möchten Sie fahren?","zh":"您想什么时候走？"},{"who":"B","en":"Heute, so bald wie möglich.","zh":"今天，越快越好。"},{"who":"A","en":"Der nächste Zug fährt um 14:10 Uhr. Sie müssen in Mannheim umsteigen.","zh":"下一班 14:10 开。您要在曼海姆换车。"},{"who":"B","en":"Das ist okay. Was kostet die Fahrkarte?","zh":"可以。票多少钱？"},{"who":"A","en":"Einfach oder hin und zurück?","zh":"单程还是往返？"},{"who":"B","en":"Hin und zurück, bitte. Ich komme morgen Abend zurück.","zh":"往返，谢谢。我明天晚上回来。"},{"who":"A","en":"Zweite Klasse? Das macht dann 46 Euro.","zh":"二等座吗？那一共 46 欧。"},{"who":"B","en":"Ja, zweite Klasse. Von welchem Gleis fährt der Zug?","zh":"对，二等座。火车从哪个站台开？"},{"who":"A","en":"Von Gleis 9. Gute Reise!","zh":"9 号站台。旅途愉快！"},{"who":"B","en":"Vielen Dank! Tschüss!","zh":"非常感谢！再见！"}],"phrases":[["Ich möchte nach … fahren.","我想去……；去城市、国家用 nach"],["so bald wie möglich","越快越好、尽快"],["umsteigen","换车（可分动词）：Ich steige in Mannheim um."],["einfach / hin und zurück","单程 / 往返"],["Von welchem Gleis fährt der Zug?","火车从哪个站台开？das Gleis = 站台、轨道"],["Gute Reise!","旅途愉快！"]],"tip":"去城市用 nach（nach Heidelberg），去具体地点用 zu（zum Bahnhof）。umsteigen 是可分动词，变位时 um 跑到句末：Ich steige in Mannheim um。现在很多人用 DB Navigator 买票，窗口买票正好练口语。"},{"id":"zug_verspaetet","title":"火车晚点了","en_title":"Der Zug hat Verspätung","level":"基础","scene":"你在汉诺威站等去柏林的 ICE，广播说晚点了。你担心赶不上在柏林换乘去德累斯顿的车，去问站台上的工作人员。","roles":{"A":"德铁工作人员","B":"旅客"},"lines":[{"who":"B","en":"Entschuldigung, hat der ICE nach Berlin Verspätung?","zh":"不好意思，去柏林的 ICE 晚点了吗？"},{"who":"A","en":"Ja, leider. Er hat ungefähr 40 Minuten Verspätung.","zh":"是的，很遗憾。大约晚点 40 分钟。"},{"who":"B","en":"Oh nein. In Berlin muss ich meinen Anschlusszug nach Dresden erreichen.","zh":"哦不。我要在柏林赶去德累斯顿的接续列车。"},{"who":"A","en":"Wann fährt Ihr Anschlusszug?","zh":"您的接续列车几点开？"},{"who":"B","en":"Um 16:20 Uhr. Schaffe ich das noch?","zh":"16:20。我还赶得上吗？"},{"who":"A","en":"Das wird knapp. Sie können aber auch einen späteren Zug nehmen. Ihre Fahrkarte gilt trotzdem.","zh":"会很紧。不过您也可以坐晚一点的车，您的票照样有效。"},{"who":"B","en":"Muss ich dafür etwas machen?","zh":"我需要为此办什么手续吗？"},{"who":"A","en":"Nein, steigen Sie einfach in den nächsten Zug.","zh":"不用，直接上下一班车就行。"},{"who":"B","en":"Und bekomme ich Geld zurück?","zh":"那我能退一部分钱吗？"},{"who":"A","en":"Ab 60 Minuten Verspätung am Ziel bekommen Sie 25 Prozent zurück. Das können Sie online beantragen.","zh":"到达目的地晚点 60 分钟以上可以退 25%，可以在网上申请。"},{"who":"B","en":"Gut zu wissen. Wo kann ich in der Zwischenzeit warten?","zh":"好的，知道了。这段时间我可以在哪儿等？"},{"who":"A","en":"Unten in der Halle gibt es ein paar Cafés.","zh":"楼下大厅里有几家咖啡馆。"},{"who":"B","en":"Super, vielen Dank für Ihre Hilfe!","zh":"太好了，非常感谢您的帮助！"}],"phrases":[["… Minuten Verspätung haben","晚点……分钟；die Verspätung 是阴性名词"],["der Anschlusszug / den Anschluss verpassen","接续列车 / 错过换乘"],["Schaffe ich das noch?","我还赶得上吗？schaffen = 做到、来得及"],["Das wird knapp.","会很紧、很悬"],["Die Fahrkarte gilt trotzdem.","票照样有效；gelten → es gilt"],["in der Zwischenzeit","在这期间、这段时间里"]],"tip":"德国火车晚点很常见，听广播时注意三个词：Verspätung（晚点）、Gleiswechsel（换站台）、fällt aus（取消）。Schaffe ich das noch? 是问“来不来得及”最地道的说法。"},{"id":"hotel_einchecken","title":"酒店入住","en_title":"Im Hotel einchecken","level":"入门","scene":"你晚上到了德累斯顿的一家酒店，在前台办理入住，顺便问早餐、Wi-Fi 和退房时间。","roles":{"A":"前台","B":"客人"},"lines":[{"who":"A","en":"Guten Abend und herzlich willkommen!","zh":"晚上好，欢迎光临！"},{"who":"B","en":"Guten Abend! Ich habe ein Zimmer reserviert. Mein Name ist Ray.","zh":"晚上好！我订了一个房间，我叫 Ray。"},{"who":"A","en":"Einen Moment, bitte … Ja, ein Einzelzimmer für zwei Nächte. Darf ich bitte Ihren Ausweis sehen?","zh":"请稍等……对，单人间住两晚。可以看一下您的证件吗？"},{"who":"B","en":"Hier ist mein Reisepass.","zh":"这是我的护照。"},{"who":"A","en":"Danke. Bitte füllen Sie noch dieses Formular aus.","zh":"谢谢。请再填一下这张表。"},{"who":"B","en":"Gern. Ab wann gibt es Frühstück?","zh":"好的。早餐几点开始？"},{"who":"A","en":"Von halb sieben bis zehn Uhr, im Erdgeschoss.","zh":"六点半到十点，在一楼（地面层）。"},{"who":"B","en":"Und gibt es WLAN im Zimmer?","zh":"房间里有 Wi-Fi 吗？"},{"who":"A","en":"Ja, das Passwort steht auf der Karte. Hier ist Ihr Schlüssel: Zimmer 304 im dritten Stock.","zh":"有，密码写在卡上。这是您的钥匙：304 房，在四楼（德国叫 dritter Stock）。"},{"who":"B","en":"Danke. Bis wann muss ich auschecken?","zh":"谢谢。最晚几点退房？"},{"who":"A","en":"Bis elf Uhr. Einen schönen Aufenthalt!","zh":"十一点前。祝您入住愉快！"},{"who":"B","en":"Danke, gute Nacht!","zh":"谢谢，晚安！"}],"phrases":[["Ich habe ein Zimmer reserviert.","我订了房间（入住时第一句）"],["Darf ich Ihren Ausweis sehen?","可以看一下您的证件吗？der Ausweis = 证件"],["ein Formular ausfüllen","填表（可分动词）：Füllen Sie das Formular aus."],["Ab wann gibt es Frühstück?","早餐几点开始？ab wann = 从什么时候起"],["das Erdgeschoss / der dritte Stock","地面层（中国的一楼）/ 德国的三层（中国的四楼）"],["Bis wann muss ich auschecken?","最晚几点退房？bis wann = 到什么时候为止"]],"tip":"德国楼层从 Erdgeschoss（地面层）开始算，erster Stock 是中国的二楼，所以 dritter Stock 等于四楼。WLAN 读作 [ˈveːlaːn]，德国人日常更常说 WLAN，而不是 Wi-Fi。halb sieben 是 6:30，不是 7:30！"},{"id":"kollegen_in_kl_abholen","title":"去机场接德国同事","en_title":"Einen Kollegen in KL abholen","level":"基础","scene":"合作已久的德国同事 Markus 第一次来吉隆坡出差，你去吉隆坡国际机场接他，并请他晚上去吃饭。你们平时就用 du。","roles":{"A":"同事 Markus","B":"你"},"lines":[{"who":"A","en":"Ray! Schön, dich endlich mal persönlich zu sehen!","zh":"Ray！终于见到你本人了，真好！"},{"who":"B","en":"Hallo Markus! Herzlich willkommen in Kuala Lumpur! Wie war der Flug?","zh":"你好 Markus！欢迎来到吉隆坡！路上怎么样？"},{"who":"A","en":"Lang, aber okay. Ich habe ein bisschen geschlafen. Puh, ist das warm hier!","zh":"很长，不过还行，睡了一会儿。呼，这里好热！"},{"who":"B","en":"Ja, daran gewöhnst du dich schnell. Soll ich dir mit dem Koffer helfen?","zh":"是啊，你很快就会习惯的。要我帮你拿箱子吗？"},{"who":"A","en":"Danke, das geht schon. Wie weit ist es bis zum Hotel?","zh":"谢谢，我自己可以。到酒店多远？"},{"who":"B","en":"Ungefähr eine Stunde, je nach Verkehr. Hast du Hunger?","zh":"大概一个小时，看路况。你饿吗？"},{"who":"A","en":"Ehrlich gesagt, ja. Das Essen im Flugzeug war nicht so toll.","zh":"说实话，饿了。飞机餐不怎么样。"},{"who":"B","en":"Dann lade ich dich heute Abend zum Essen ein. Magst du scharfes Essen?","zh":"那今晚我请你吃饭。你喜欢吃辣吗？"},{"who":"A","en":"Ein bisschen scharf ist okay, aber nicht zu sehr.","zh":"一点辣可以，但别太辣。"},{"who":"B","en":"Dann gehen wir zur Jalan Alor. Das ist eine Straße mit vielen Essensständen, da kannst du alles Mögliche probieren.","zh":"那我们去亚罗街。那是一条有很多小吃摊的街，你可以尝各种东西。"},{"who":"A","en":"Klingt super! Aber das nächste Mal bezahle ich.","zh":"听起来太棒了！不过下次我请。"},{"who":"B","en":"Abgemacht! Aber erst bringen wir deine Sachen ins Hotel.","zh":"说定了！不过我们先把你的东西送到酒店。"},{"who":"A","en":"Perfekt. Danke, dass du mich abholst!","zh":"太好了。谢谢你来接我！"},{"who":"B","en":"Gern geschehen!","zh":"不客气！"}],"phrases":[["Schön, dich endlich mal persönlich zu sehen!","终于见到你本人了！线上合作后第一次见面的好开场"],["Wie war der Flug?","飞行怎么样？接机必问"],["Daran gewöhnst du dich schnell.","你很快会习惯的；sich an etwas gewöhnen"],["je nach Verkehr","看路况而定；je nach + 第三格"],["jemanden zum Essen einladen","请某人吃饭（我买单）"],["Abgemacht!","说定了！一言为定！"],["Gern geschehen!","不客气！回应 Danke 的常用语"]],"tip":"einladen 在德语里就是“请客”，说 Ich lade dich ein 就表示我买单，德国人通常会说“下次我请”。daran 指代前面说的“热”（sich an etwas gewöhnen），da + 介词的结构要多练。"},{"id":"nach_dem_weg_fragen","title":"问路","en_title":"Nach dem Weg fragen","level":"入门","scene":"你在纽伦堡老城找不到日耳曼国家博物馆，向一位路人问路，第一遍没听清，请对方再说一遍。","roles":{"A":"路人","B":"游客"},"lines":[{"who":"B","en":"Entschuldigung, können Sie mir helfen?","zh":"不好意思，您能帮我一下吗？"},{"who":"A","en":"Ja, gern. Was suchen Sie?","zh":"可以。您找什么？"},{"who":"B","en":"Ich suche das Germanische Nationalmuseum. Ist das weit von hier?","zh":"我在找日耳曼国家博物馆。离这儿远吗？"},{"who":"A","en":"Nein, ungefähr zehn Minuten zu Fuß.","zh":"不远，走路大概十分钟。"},{"who":"B","en":"Wie komme ich dahin?","zh":"我怎么过去？"},{"who":"A","en":"Gehen Sie hier geradeaus bis zur Ampel. Dann biegen Sie links ab.","zh":"从这儿一直走到红绿灯，然后左转。"},{"who":"B","en":"Geradeaus bis zur Ampel und dann links?","zh":"一直走到红绿灯，然后左转？"},{"who":"A","en":"Genau. Danach nehmen Sie die zweite Straße rechts. Das Museum ist auf der linken Seite.","zh":"对。然后第二个路口右转，博物馆在左手边。"},{"who":"B","en":"Entschuldigung, können Sie das bitte langsamer wiederholen?","zh":"不好意思，您能慢一点再说一遍吗？"},{"who":"A","en":"Klar: an der Ampel links, dann die zweite Straße rechts.","zh":"好的：红绿灯左转，然后第二个路口右转。"},{"who":"B","en":"Jetzt habe ich es verstanden. Vielen Dank!","zh":"这下我听懂了。非常感谢！"},{"who":"A","en":"Bitte schön. Viel Spaß im Museum!","zh":"不客气。在博物馆玩得开心！"}],"phrases":[["Können Sie mir helfen?","您能帮我一下吗？问路前先说 Entschuldigung"],["Ist das weit von hier?","离这儿远吗？"],["Wie komme ich dahin?","我怎么过去？也可说 Wie komme ich zum Museum?"],["geradeaus / links / rechts abbiegen","直走 / 左转 / 右转；abbiegen 是可分动词"],["bis zur Ampel","一直到红绿灯；zur = zu der，die Ampel 是阴性"],["Können Sie das bitte langsamer wiederholen?","能慢一点再说一遍吗？听不懂时的救命句"]],"tip":"把对方的指路复述一遍（Geradeaus bis zur Ampel und dann links?）是确认理解的好办法，德国人会很耐心地纠正你。命令式 Sie 形式动词放句首：Gehen Sie …, Biegen Sie … ab。"},{"id":"sprachtandem","title":"第一次语言交换","en_title":"Das erste Sprachtandem","level":"入门","scene":"你在语伴 app 上找到一位想学中文的德国人 Sophie，第一次视频聊天，各自介绍并约定怎么练习。","roles":{"A":"语伴 Sophie","B":"你"},"lines":[{"who":"A","en":"Hallo! Kannst du mich hören?","zh":"你好！你能听到我说话吗？"},{"who":"B","en":"Ja, ich höre dich gut. Hallo Sophie! Ich bin Ray.","zh":"能，听得很清楚。你好 Sophie！我是 Ray。"},{"who":"A","en":"Schön, dich kennenzulernen! Wo bist du gerade?","zh":"很高兴认识你！你现在在哪儿？"},{"who":"B","en":"Ich bin in Kuala Lumpur. Hier ist es schon acht Uhr abends.","zh":"我在吉隆坡。这里已经晚上八点了。"},{"who":"A","en":"Und bei mir in Köln ist es erst eins. Warum lernst du Deutsch?","zh":"我在科隆这边才一点。你为什么学德语？"},{"who":"B","en":"Ich arbeite mit deutschen Kollegen und möchte mit ihnen Deutsch sprechen. Und du? Warum lernst du Chinesisch?","zh":"我和德国同事一起工作，想和他们说德语。你呢？你为什么学中文？"},{"who":"A","en":"Ich war ein Jahr in Shanghai und finde die Sprache toll. Aber die Töne sind so schwer!","zh":"我在上海待过一年，觉得中文很棒。但是声调好难！"},{"who":"B","en":"Und für mich sind die Artikel schwer: der, die, das!","zh":"对我来说冠词很难：der、die、das！"},{"who":"A","en":"Haha, das verstehe ich. Wollen wir eine halbe Stunde Deutsch und eine halbe Stunde Chinesisch sprechen?","zh":"哈哈，我理解。我们半小时说德语、半小时说中文，好吗？"},{"who":"B","en":"Gute Idee! Und bitte korrigier mich, wenn ich Fehler mache.","zh":"好主意！我说错的时候请纠正我。"},{"who":"A","en":"Klar, mache ich. Du mich aber auch!","zh":"当然，我会的。你也要纠正我哦！"},{"who":"B","en":"Abgemacht! Fangen wir mit Deutsch an?","zh":"说定了！我们先从德语开始？"},{"who":"A","en":"Ja, gern. Also: Was hast du heute gemacht?","zh":"好啊。那么：你今天做了什么？"}],"phrases":[["Kannst du mich hören?","你能听到我吗？视频通话第一句"],["Schön, dich kennenzulernen!","很高兴认识你！对 Sie 说 Schön, Sie kennenzulernen!"],["Warum lernst du …?","你为什么学……？"],["Korrigier mich bitte!","请纠正我！du 的命令式去掉 -st"],["Fehler machen","犯错；德语说“做错误”，不说 Fehler haben"],["Abgemacht!","说定了！"],["Fangen wir mit … an?","我们先从……开始？anfangen 是可分动词"]],"tip":"du 的命令式是把 du korrigierst 的 -st 去掉：Korrigier mich!。冬天德国比吉隆坡晚 7 小时，约时间前先算好时差。和语伴约好固定时长、两种语言各一半，比随便聊效果好。"},{"id":"restaurant_bestellen_bezahlen","title":"在餐厅点菜和结账","en_title":"Im Restaurant bestellen und bezahlen","level":"基础","scene":"你和同事在科隆一家德国餐馆吃晚饭，向服务员要推荐、问清楚是什么肉、点菜，最后分开付钱。","roles":{"A":"服务员","B":"客人（你）"},"lines":[{"who":"A","en":"Guten Abend! Haben Sie schon gewählt?","zh":"晚上好！两位选好了吗？"},{"who":"B","en":"Noch nicht ganz. Was können Sie empfehlen?","zh":"还没完全选好。您能推荐点什么？"},{"who":"A","en":"Das Schnitzel ist sehr beliebt. Heute gibt es auch Rinderrouladen mit Rotkohl.","zh":"炸肉排很受欢迎。今天还有牛肉卷配紫甘蓝。"},{"who":"B","en":"Ist das Schnitzel aus Schweinefleisch?","zh":"炸肉排是猪肉做的吗？"},{"who":"A","en":"Ja, aber wir haben auch Hähnchenschnitzel.","zh":"是的，不过我们也有鸡肉排。"},{"who":"B","en":"Gut, dann nehme ich ein Hähnchenschnitzel mit Pommes und eine Apfelschorle.","zh":"好，那我要一份鸡肉排配薯条，再来一杯苹果汽水。"},{"who":"A","en":"Sehr gern. Kommt sofort.","zh":"好的，马上就来。"},{"who":"B","en":"Entschuldigung, wir möchten bitte zahlen.","zh":"（饭后）不好意思，我们要买单。"},{"who":"A","en":"Zusammen oder getrennt?","zh":"一起付还是分开付？"},{"who":"B","en":"Getrennt, bitte. Ich hatte das Schnitzel und die Apfelschorle.","zh":"分开，谢谢。我点的是肉排和苹果汽水。"},{"who":"A","en":"Das macht 21,50 Euro.","zh":"一共 21.50 欧元。"},{"who":"B","en":"Machen Sie 23, bitte. Ich zahle mit Karte.","zh":"算 23 欧吧。我刷卡。"},{"who":"A","en":"Danke schön! Hat es Ihnen geschmeckt?","zh":"谢谢！合您口味吗？"},{"who":"B","en":"Ja, sehr gut. Vielen Dank!","zh":"是的，非常好吃。非常感谢！"}],"phrases":[["Haben Sie schon gewählt?","您选好了吗？服务员点单时常问"],["Was können Sie empfehlen?","您推荐什么？"],["Ist das … aus Schweinefleisch?","这是猪肉做的吗？问食材的句型"],["Wir möchten bitte zahlen.","我们要买单"],["Zusammen oder getrennt?","一起付还是分开付？"],["Ich hatte …","我点的是……；用 haben 的过去式说自己吃了什么"],["Hat es Ihnen geschmeckt?","合您口味吗？回答 Ja, sehr gut! / Ja, lecker!"]],"tip":"德国餐厅不会主动给账单，要自己叫服务员买单；Zusammen oder getrennt? 很常见，分开付很正常。说自己点了什么用 Ich hatte …，不必说全菜名。"},{"id":"arzttermin_vereinbaren","title":"打电话约看医生","en_title":"Einen Arzttermin vereinbaren","level":"基础","scene":"你刚搬到莱比锡不久，嗓子疼还发烧，给附近的家庭医生诊所打电话约时间。","roles":{"A":"诊所前台","B":"病人"},"lines":[{"who":"A","en":"Praxis Dr. Becker, Schneider am Apparat. Guten Morgen!","zh":"贝克尔医生诊所，我是施奈德。早上好！"},{"who":"B","en":"Guten Morgen! Mein Name ist Ray. Ich möchte gern einen Termin machen.","zh":"早上好！我叫 Ray，我想预约一下。"},{"who":"A","en":"Waren Sie schon einmal bei uns?","zh":"您以前来过我们这儿吗？"},{"who":"B","en":"Nein, noch nie. Ich wohne erst seit Kurzem in Leipzig.","zh":"没有，从来没有。我刚搬到莱比锡不久。"},{"who":"A","en":"Was fehlt Ihnen denn?","zh":"您哪里不舒服？"},{"who":"B","en":"Ich habe seit zwei Tagen Halsschmerzen und Fieber.","zh":"我嗓子疼、发烧两天了。"},{"who":"A","en":"Sind Sie gesetzlich oder privat versichert?","zh":"您是公立医保还是私人医保？"},{"who":"B","en":"Gesetzlich, bei der Techniker Krankenkasse.","zh":"公立医保，在 TK（技术人员医保公司）。"},{"who":"A","en":"Gut. Können Sie heute um halb zwölf kommen?","zh":"好。您今天十一点半能来吗？"},{"who":"B","en":"Ja, das passt mir gut. Muss ich etwas mitbringen?","zh":"可以，这个时间很合适。我需要带什么吗？"},{"who":"A","en":"Bitte bringen Sie Ihre Versichertenkarte mit.","zh":"请带上您的医保卡。"},{"who":"B","en":"Alles klar. Vielen Dank, bis später!","zh":"好的。非常感谢，待会儿见！"},{"who":"A","en":"Gute Besserung!","zh":"祝您早日康复！"}],"phrases":[["einen Termin machen / vereinbaren","预约；vereinbaren 更正式"],["Was fehlt Ihnen?","您哪里不舒服？医生和前台的固定问法"],["Ich habe seit … Halsschmerzen.","我嗓子疼了……；持续的症状用现在时 + seit"],["gesetzlich / privat versichert","公立 / 私人医保，德国看病必问"],["Das passt mir gut.","这个时间对我合适；不合适说 Das passt mir leider nicht."],["die Versichertenkarte","医保卡，也叫 Gesundheitskarte"],["Gute Besserung!","祝早日康复！对病人的固定祝福"]],"tip":"说“已经疼了两天”用现在时 + seit：Ich habe seit zwei Tagen Fieber，千万不要用过去时。德国看病一般先找家庭医生（Hausarzt），最好先打电话或网上预约（不少诊所也有不用预约的 offene Sprechstunde，但可能要等很久）。"},{"id":"apotheke","title":"在药店买药","en_title":"In der Apotheke","level":"基础","scene":"你感冒了，鼻子堵、头疼，去药店买药，药剂师问你症状、过敏情况，并告诉你怎么用药。","roles":{"A":"药剂师","B":"顾客"},"lines":[{"who":"A","en":"Guten Tag! Was kann ich für Sie tun?","zh":"您好！有什么可以帮您？"},{"who":"B","en":"Hallo! Ich habe Schnupfen und Kopfschmerzen. Können Sie mir etwas empfehlen?","zh":"您好！我流鼻涕、头疼。您能推荐点什么吗？"},{"who":"A","en":"Haben Sie auch Fieber?","zh":"您也发烧吗？"},{"who":"B","en":"Nein, kein Fieber. Aber ich schlafe schlecht, weil meine Nase zu ist.","zh":"不发烧。但是鼻子堵了，睡不好。"},{"who":"A","en":"Dann empfehle ich Ihnen ein Nasenspray und Ibuprofen gegen die Kopfschmerzen.","zh":"那我推荐您用鼻喷剂，再用布洛芬止头疼。"},{"who":"B","en":"Brauche ich dafür ein Rezept?","zh":"这些需要处方吗？"},{"who":"A","en":"Nein, beides ist rezeptfrei. Haben Sie Allergien oder nehmen Sie andere Medikamente?","zh":"不用，两样都是非处方药。您有过敏吗？或者在吃别的药吗？"},{"who":"B","en":"Nein, ich habe keine Allergien und nehme sonst nichts.","zh":"没有，我没有过敏，也没在吃别的药。"},{"who":"A","en":"Gut. Nehmen Sie das Nasenspray aber höchstens eine Woche lang.","zh":"好。不过鼻喷剂最多用一周。"},{"who":"B","en":"Und wie oft soll ich die Tabletten nehmen?","zh":"药片一天吃几次？"},{"who":"A","en":"Bei Bedarf eine Tablette, aber nicht mehr als drei pro Tag.","zh":"需要时吃一片，但一天不超过三片。"},{"who":"B","en":"Alles klar. Was macht das zusammen?","zh":"明白了。一共多少钱？"},{"who":"A","en":"12,80 Euro. Gute Besserung!","zh":"12.80 欧元。祝您早日康复！"}],"phrases":[["Was kann ich für Sie tun?","有什么可以帮您？店员、药剂师常用"],["Können Sie mir etwas empfehlen?","您能给我推荐点什么吗？"],["Meine Nase ist zu.","我鼻子堵了；zu 在这里是“堵住、关着”"],["Brauche ich dafür ein Rezept?","这个需要处方吗？das Rezept 也是“菜谱”"],["rezeptfrei / verschreibungspflichtig","非处方 / 需要处方"],["bei Bedarf","需要时、按需"]],"tip":"德国的布洛芬、扑热息痛、消肿鼻喷剂这类药只在 Apotheke 卖，超市和 dm、Rossmann 这类日化店买不到（那里最多有感冒茶、润喉糖、海盐水鼻喷）。weil 引导的从句动词放最后：…, weil meine Nase zu ist。"},{"id":"videocall_technikprobleme","title":"视频会议的技术问题","en_title":"Technikprobleme im Videocall","level":"入门","scene":"你和一位德国客户 Herr Braun 开视频会议，一开始你忘了开麦，对方在火车上信号不好，还看不到你共享的屏幕。","roles":{"A":"客户 Herr Braun","B":"你"},"lines":[{"who":"A","en":"Hallo Ray, ich sehe Sie, aber ich höre nichts. Ich glaube, Ihr Mikrofon ist stumm geschaltet.","zh":"您好 Ray，我能看到您，但听不到声音。我觉得您的麦克风静音了。"},{"who":"B","en":"Oh, Entschuldigung! Können Sie mich jetzt hören?","zh":"哦，抱歉！现在能听到我吗？"},{"who":"A","en":"Ja, jetzt höre ich Sie gut.","zh":"能，现在听得很清楚。"},{"who":"B","en":"Super. Aber Ihr Ton ist bei mir ein bisschen abgehackt.","zh":"太好了。不过我这边听您的声音有点断断续续。"},{"who":"A","en":"Ich sitze im Zug, das Netz ist hier nicht so gut. Ich schalte mal die Kamera aus, vielleicht hilft das.","zh":"我在火车上，这里信号不好。我先关掉摄像头，也许有用。"},{"who":"B","en":"Ja, jetzt ist es viel besser. Sehen Sie meinen Bildschirm?","zh":"是的，现在好多了。您能看到我的屏幕吗？"},{"who":"A","en":"Nein, ich sehe nur Ihr Gesicht.","zh":"看不到，我只看到您的脸。"},{"who":"B","en":"Moment, ich teile ihn noch einmal. Und jetzt?","zh":"稍等，我再共享一次。现在呢？"},{"who":"A","en":"Ja, jetzt sehe ich die Präsentation.","zh":"对，现在能看到演示文稿了。"},{"who":"B","en":"Perfekt. Falls die Verbindung abbricht, rufe ich Sie einfach noch einmal an.","zh":"好极了。如果连接断了，我就再打给您。"},{"who":"A","en":"Gut, so machen wir das.","zh":"好，就这么办。"},{"who":"B","en":"Dann fange ich jetzt an.","zh":"那我现在开始了。"}],"phrases":[["Können Sie mich hören?","您能听到我吗？视频会议第一句"],["stumm geschaltet","静音了；Sie sind noch auf stumm. = 您还开着静音"],["Der Ton ist abgehackt.","声音断断续续"],["die Kamera ausschalten","关摄像头（可分动词）；打开是 einschalten"],["den Bildschirm teilen","共享屏幕"],["Falls die Verbindung abbricht, …","如果连接断了……；falls 从句动词放句末"]],"tip":"视频会议必备三件套：stumm geschaltet（静音）、Bildschirm teilen（共享屏幕）、Die Verbindung bricht ab（断线）。可分动词在主句里前缀放句末：Ich schalte die Kamera aus。"},{"id":"paket_abholen","title":"取包裹","en_title":"Ein Paket abholen","level":"入门","scene":"快递来的时候你不在家，信箱里留了一张通知单，你去附近的邮局网点取包裹，顺便问能不能寄包裹到马来西亚。","roles":{"A":"邮局工作人员","B":"收件人"},"lines":[{"who":"B","en":"Guten Tag! Ich möchte ein Paket abholen. Hier ist die Benachrichtigungskarte.","zh":"您好！我想取一个包裹。这是通知单。"},{"who":"A","en":"Danke. Haben Sie einen Ausweis dabei?","zh":"谢谢。您带证件了吗？"},{"who":"B","en":"Ja, hier ist mein Aufenthaltstitel.","zh":"带了，这是我的居留卡。"},{"who":"A","en":"Einen Moment, ich schaue nach … Hm, das Paket ist noch nicht da.","zh":"请稍等，我查一下……嗯，包裹还没到。"},{"who":"B","en":"Oh. Auf der Karte steht aber „ab heute abholbereit“.","zh":"哦。可是通知单上写着“今天起可取”。"},{"who":"A","en":"Ah, Entschuldigung, hier ist es. Es lag im falschen Regal.","zh":"啊，抱歉，在这儿。放错架子了。"},{"who":"B","en":"Kein Problem. Das ist ziemlich schwer!","zh":"没关系。这个挺重的！"},{"who":"A","en":"Ja. Bitte unterschreiben Sie hier.","zh":"是啊。请在这儿签字。"},{"who":"B","en":"Hier?","zh":"这儿吗？"},{"who":"A","en":"Ja, genau. Danke, das war's schon.","zh":"对。谢谢，这就好了。"},{"who":"B","en":"Noch eine Frage: Kann ich hier auch ein Paket nach Malaysia schicken?","zh":"再问一下：在这儿也能寄包裹到马来西亚吗？"},{"who":"A","en":"Ja, natürlich. Dafür brauchen Sie aber eine Zollinhaltserklärung.","zh":"当然可以，不过需要填一张海关申报单。"},{"who":"B","en":"Okay, dann komme ich morgen wieder. Schönen Tag noch!","zh":"好的，那我明天再来。祝您愉快！"}],"phrases":[["ein Paket abholen","取包裹（可分动词）：Ich hole das Paket ab."],["die Benachrichtigungskarte","快递没送到时留下的通知单"],["Ich schaue nach.","我查一下；nachschauen 是可分动词"],["Auf der Karte steht …","卡上写着……；“写着”用 stehen，不用 schreiben"],["Bitte unterschreiben Sie hier.","请在这儿签字"],["ein Paket nach … schicken","寄包裹到……"]],"tip":"德国快递如果送货时你不在家，常会放到附近网点、邻居家或 Packstation，记得看信箱里的通知单。Paket 是中性：das Paket，所以用 es 指代（Es lag im falschen Regal）。"},{"id":"nachbarin_small_talk","title":"和邻居寒暄","en_title":"Small Talk mit der Nachbarin","level":"基础","scene":"你刚搬进新公寓，傍晚在楼梯间碰到住楼下的老太太 Frau Krüger，互相介绍，她还告诉你垃圾怎么扔。","roles":{"A":"邻居 Frau Krüger","B":"新住户（你）"},"lines":[{"who":"A","en":"Guten Abend! Sie sind bestimmt der neue Nachbar von oben, oder?","zh":"晚上好！您一定是楼上新搬来的邻居吧？"},{"who":"B","en":"Ja, genau! Ich heiße Ray. Ich bin letzte Woche eingezogen.","zh":"对！我叫 Ray，上周搬进来的。"},{"who":"A","en":"Herzlich willkommen! Ich bin Frau Krüger. Ich wohne schon seit 30 Jahren hier.","zh":"欢迎欢迎！我是克吕格太太。我在这儿已经住了 30 年了。"},{"who":"B","en":"Wow, so lange! Dann kennen Sie das Viertel ja sehr gut.","zh":"哇，这么久！那您一定很了解这一带。"},{"who":"A","en":"Oh ja. Wo kommen Sie denn her?","zh":"是啊。您是哪里人？"},{"who":"B","en":"Ich komme aus China, aber vorher habe ich in Malaysia gelebt.","zh":"我是中国人，不过之前住在马来西亚。"},{"who":"A","en":"Malaysia! Da ist es bestimmt wärmer als hier.","zh":"马来西亚！那儿肯定比这儿暖和。"},{"who":"B","en":"Ja, viel wärmer! An den deutschen Winter muss ich mich noch gewöhnen.","zh":"是啊，暖和多了！德国的冬天我还得慢慢适应。"},{"who":"A","en":"Das schaffen Sie schon. Ach, übrigens: Der Restmüll wird hier dienstags abgeholt.","zh":"您没问题的。哦对了：这里每周二收其他垃圾。"},{"who":"B","en":"Danke für den Tipp! Wohin kommt eigentlich das Altpapier?","zh":"谢谢提醒！那废纸扔到哪儿？"},{"who":"A","en":"In die blaue Tonne, hinten im Hof.","zh":"扔进后院的蓝色垃圾桶。"},{"who":"B","en":"Super, danke. Wenn Sie mal etwas brauchen, klingeln Sie einfach bei mir.","zh":"太好了，谢谢。您要是需要什么，直接按我门铃就行。"},{"who":"A","en":"Das ist nett. Einen schönen Abend noch!","zh":"您真好。祝您晚上愉快！"},{"who":"B","en":"Danke, Ihnen auch!","zh":"谢谢，您也是！"}],"phrases":[["Ich bin letzte Woche eingezogen.","我上周搬进来的；einziehen 搬入，ausziehen 搬出，都用 sein 作助动词"],["Herzlich willkommen!","热烈欢迎！"],["Wo kommen Sie her?","您是哪里人？= Woher kommen Sie?"],["sich an etwas gewöhnen","习惯某事；an + 第四格：an den Winter"],["Danke für den Tipp!","谢谢提醒/建议！"],["die blaue Tonne","蓝色垃圾桶（放纸）"],["bei jemandem klingeln","按某人的门铃"]],"tip":"德国垃圾分类：蓝桶放纸、黄桶或黄袋放包装、棕桶放厨余、黑/灰桶放其他垃圾（Restmüll），玻璃瓶按颜色投到街边回收箱。和年长邻居一定用 Sie，等对方主动提出才改 du。"},{"id":"party_small_talk","title":"在派对上聊天","en_title":"Small Talk auf einer Party","level":"基础","scene":"你在汉堡出差三个月，被同事 Anna 邀请去她家的派对，在厨房遇到一个陌生人 Jonas，同龄人之间直接用 du。","roles":{"A":"派对客人 Jonas","B":"你"},"lines":[{"who":"A","en":"Hi! Ich glaube, wir kennen uns noch nicht. Ich bin Jonas.","zh":"嗨！我们好像还不认识。我是 Jonas。"},{"who":"B","en":"Hi Jonas, ich bin Ray. Freut mich!","zh":"嗨 Jonas，我是 Ray。很高兴认识你！"},{"who":"A","en":"Freut mich auch. Woher kennst du Anna?","zh":"我也是。你怎么认识 Anna 的？"},{"who":"B","en":"Wir arbeiten zusammen. Und du?","zh":"我们是同事。你呢？"},{"who":"A","en":"Wir haben zusammen studiert. Was machst du beruflich?","zh":"我们是大学同学。你做什么工作的？"},{"who":"B","en":"Ich bin Programmierer. Ich bin gerade für drei Monate in Hamburg, eigentlich wohne ich in Kuala Lumpur.","zh":"我是程序员。我现在在汉堡待三个月，其实我住在吉隆坡。"},{"who":"A","en":"Echt? Wie gefällt dir Hamburg bisher?","zh":"真的？到现在为止你觉得汉堡怎么样？"},{"who":"B","en":"Sehr gut! Nur das Wetter ist ein bisschen grau. Was machst du so am Wochenende?","zh":"很好！就是天气有点阴。你周末一般做什么？"},{"who":"A","en":"Im Sommer bin ich oft an der Elbe, im Winter eher im Kino. Warst du schon auf dem Fischmarkt?","zh":"夏天常去易北河边，冬天多半去看电影。你去过鱼市了吗？"},{"who":"B","en":"Nein, noch nicht. Lohnt sich das?","zh":"还没。值得去吗？"},{"who":"A","en":"Auf jeden Fall! Aber du musst früh aufstehen, er findet nur sonntagmorgens statt.","zh":"绝对值得！不过你得早起，鱼市只在周日早上开。"},{"who":"B","en":"Okay, dann versuche ich es diesen Sonntag. Willst du auch noch was trinken? Ich hole mir gerade ein Bier.","zh":"好，那我这周日试试。你还想喝点什么吗？我正要去拿瓶啤酒。"},{"who":"A","en":"Gern, bring mir auch eins mit!","zh":"好啊，帮我也带一瓶！"},{"who":"B","en":"Mach ich!","zh":"没问题！"}],"phrases":[["Ich glaube, wir kennen uns noch nicht.","我们好像还不认识——主动搭话的好开场"],["Woher kennst du …?","你怎么认识……的？派对破冰神器"],["Was machst du beruflich?","你做什么工作？"],["Wie gefällt dir …?","你觉得……怎么样？主语是被喜欢的东西"],["Lohnt sich das?","值得吗？sich lohnen = 值得"],["Auf jeden Fall!","绝对！一定！"],["Mach ich!","好嘞！没问题！口语里省掉了 das"]],"tip":"gefallen 的用法和中文相反：Hamburg gefällt mir（汉堡让我喜欢），不要说 Ich gefalle Hamburg。was trinken 是 etwas trinken 的口语省略，派对上很常见。"},{"id":"deutschkurs_erste_stunde","title":"德语课第一节课","en_title":"Die erste Stunde im Deutschkurs","level":"入门","scene":"你报了一个线上德语 A1 课，第一节课老师 Frau Lange 请每个人做自我介绍。","roles":{"A":"德语老师 Frau Lange","B":"你"},"lines":[{"who":"A","en":"Herzlich willkommen im Kurs! Wie heißen Sie?","zh":"欢迎来上课！您叫什么名字？"},{"who":"B","en":"Ich heiße Ray.","zh":"我叫 Ray。"},{"who":"A","en":"Woher kommen Sie, Ray?","zh":"Ray，您是哪里人？"},{"who":"B","en":"Ich komme aus China.","zh":"我来自中国。"},{"who":"A","en":"Und wo wohnen Sie?","zh":"那您住在哪儿？"},{"who":"B","en":"Ich wohne in Kuala Lumpur. Das ist in Malaysia.","zh":"我住在吉隆坡，在马来西亚。"},{"who":"A","en":"Was sind Sie von Beruf?","zh":"您是做什么工作的？"},{"who":"B","en":"Ich bin Softwareentwickler.","zh":"我是软件开发人员。"},{"who":"A","en":"Welche Sprachen sprechen Sie?","zh":"您会说哪些语言？"},{"who":"B","en":"Ich spreche Chinesisch, Englisch und ein bisschen Deutsch.","zh":"我会说中文、英语和一点德语。"},{"who":"A","en":"Sehr gut! Und was sind Ihre Hobbys?","zh":"很好！您有什么爱好？"},{"who":"B","en":"Ich koche gern und ich gehe gern schwimmen.","zh":"我喜欢做饭，也喜欢去游泳。"},{"who":"A","en":"Wunderbar. Vielen Dank, Ray!","zh":"太好了。谢谢 Ray！"}],"phrases":[["Wie heißen Sie? – Ich heiße …","您叫什么？——我叫……"],["Woher kommen Sie? – Ich komme aus …","您从哪里来？——我来自……"],["Was sind Sie von Beruf?","您的职业是什么？"],["Ich bin Softwareentwickler.","职业前不加冠词"],["ein bisschen Deutsch","一点德语；也可说 ein wenig"],["Ich koche gern.","我喜欢做饭；gern 放在动词后表示“喜欢做”"]],"tip":"说职业不加冠词：Ich bin Softwareentwickler，不说 ein Softwareentwickler。这组问答（名字、来自哪里、住哪、职业、语言、爱好）就是 A1 口语考试第一部分，要能脱口而出。"},{"id":"kleidung_umtauschen","title":"退换衣服","en_title":"Kleidung umtauschen","level":"基础","scene":"你上周买的毛衣太小了，带着小票回店里想换大一号，结果想要的颜色没货了。","roles":{"A":"店员","B":"顾客"},"lines":[{"who":"B","en":"Guten Tag! Ich habe diesen Pullover letzte Woche hier gekauft. Leider ist er mir zu klein.","zh":"您好！我上周在这儿买了这件毛衣，可惜太小了。"},{"who":"A","en":"Oh, das tut mir leid. Haben Sie den Kassenbon dabei?","zh":"哦，真抱歉。您带小票了吗？"},{"who":"B","en":"Ja, hier ist er. Kann ich den Pullover umtauschen? Ich brauche eine Nummer größer.","zh":"带了，在这儿。这件毛衣能换吗？我需要大一号的。"},{"who":"A","en":"Natürlich. Welche Größe ist das?","zh":"当然。这件是什么码？"},{"who":"B","en":"Das ist M. Ich glaube, L passt mir besser.","zh":"这件是 M，我觉得 L 更合适。"},{"who":"A","en":"Einen Moment … In Blau haben wir L leider nicht mehr. Nur noch in Grau oder Schwarz.","zh":"请稍等……蓝色的 L 码可惜没有了，只剩灰色和黑色。"},{"who":"B","en":"Hm. Kann ich den grauen mal anprobieren?","zh":"嗯。我能试一下灰色的吗？"},{"who":"A","en":"Klar, die Umkleidekabinen sind dort hinten.","zh":"当然，试衣间在那后面。"},{"who":"B","en":"Der graue passt perfekt, aber die Farbe gefällt mir nicht so. Kann ich auch mein Geld zurückbekommen?","zh":"（试完后）灰色的很合身，但颜色我不太喜欢。我也可以退钱吗？"},{"who":"A","en":"Ja, innerhalb von 30 Tagen ist das bei uns kein Problem.","zh":"可以，在我们店 30 天内没问题。"},{"who":"B","en":"Dann hätte ich lieber mein Geld zurück.","zh":"那我还是退钱吧。"},{"who":"A","en":"Gut. Sie haben mit Karte bezahlt, oder? Dann buche ich den Betrag auf Ihre Karte zurück.","zh":"好。您是刷卡付的吧？那我把钱退回您的卡上。"},{"who":"B","en":"Ja, genau. Vielen Dank für Ihre Hilfe!","zh":"对。非常感谢您的帮助！"}],"phrases":[["Er ist mir zu klein.","它对我来说太小了；er 指 der Pullover，mir 是第三格"],["der Kassenbon","购物小票，退换货必带"],["etwas umtauschen","换货（可分动词）"],["eine Nummer größer / kleiner","大一号 / 小一号"],["Kann ich … anprobieren?","我能试穿……吗？"],["die Umkleidekabine","试衣间"],["das Geld zurückbekommen","拿回钱、退款"]],"tip":"der Pullover 是阳性，所以要用 er / ihn / den grauen 指代——中国人最容易在这里乱用 es。另外在德国实体店，商品没有质量问题时，退款和换货都不是法定义务，要看店铺规定（Kulanz）；换货（Umtausch）通常比退款更容易。"},{"id":"wochenende_erzaehlen","title":"聊周末做了什么","en_title":"Wie war dein Wochenende?","level":"入门","scene":"周一早上团队视频会议还没开始，同事 Lisa 问你周末过得怎么样。你们平时用 du。","roles":{"A":"同事 Lisa","B":"你"},"lines":[{"who":"A","en":"Guten Morgen, Ray! Wie war dein Wochenende?","zh":"早上好 Ray！你周末过得怎么样？"},{"who":"B","en":"Morgen, Lisa! Es war sehr schön, danke.","zh":"早，Lisa！很好，谢谢。"},{"who":"A","en":"Was hast du gemacht?","zh":"你做了什么？"},{"who":"B","en":"Am Samstag bin ich mit Freunden wandern gegangen.","zh":"周六我和朋友去徒步了。"},{"who":"A","en":"Oh, schön! Wo denn?","zh":"哦，真好！去哪儿了？"},{"who":"B","en":"Am Bukit Tabur, das ist ein Hügel in der Nähe von KL. Die Aussicht war toll!","zh":"在 Bukit Tabur，是吉隆坡附近的一座小山。风景很棒！"},{"who":"A","en":"War es nicht zu heiß?","zh":"不会太热吗？"},{"who":"B","en":"Doch, ein bisschen. Deshalb sind wir schon um fünf Uhr morgens losgegangen.","zh":"有点热。所以我们早上五点就出发了。"},{"who":"A","en":"Wow, so früh! Und am Sonntag?","zh":"哇，这么早！那周日呢？"},{"who":"B","en":"Am Sonntag habe ich nicht viel gemacht. Ich habe gekocht und Deutsch gelernt. Und du?","zh":"周日没做什么，做了饭，学了德语。你呢？"},{"who":"A","en":"Ich war bei meinen Eltern. Wir haben zusammen gegessen.","zh":"我去了我父母家，我们一起吃了饭。"},{"who":"B","en":"Das klingt gemütlich!","zh":"听起来很惬意！"}],"phrases":[["Wie war dein Wochenende?","你周末过得怎么样？周一必问"],["Es war sehr schön.","很好；sein 的过去式 war 比 ist gewesen 更常用"],["wandern gehen","去徒步：Ich bin wandern gegangen."],["Die Aussicht war toll!","风景/视野很棒！"],["losgehen","出发（步行）；完成时用 sein：Wir sind losgegangen."],["Ich war bei meinen Eltern.","我去了我父母家；bei + 人 = 在某人那里"],["gemütlich","舒适惬意，德国人很爱用的词"]],"tip":"讲过去的事用现在完成时：表示移动的动词用 sein（Ich bin gewandert / losgegangen），其他大多用 haben（Ich habe gekocht）。sein 和 haben 本身口语里常用过去式：Es war schön, ich war bei …。"},{"id":"handyvertrag","title":"办手机卡","en_title":"Im Handyladen","level":"基础","scene":"你刚到德国，在手机店想办一个本地号码，店员介绍合约套餐和预付卡，你比较后选了一个。","roles":{"A":"店员","B":"顾客"},"lines":[{"who":"A","en":"Hallo! Kann ich Ihnen helfen?","zh":"您好！需要帮忙吗？"},{"who":"B","en":"Ja, ich brauche eine deutsche Handynummer. Was für Tarife haben Sie?","zh":"是的，我需要一个德国手机号。你们有哪些套餐？"},{"who":"A","en":"Möchten Sie einen Vertrag oder lieber Prepaid?","zh":"您想要合约套餐还是预付卡？"},{"who":"B","en":"Was ist der Unterschied?","zh":"有什么区别？"},{"who":"A","en":"Ein Vertrag läuft meistens 24 Monate und Sie zahlen jeden Monat. Bei Prepaid laden Sie Guthaben auf und können jederzeit aufhören.","zh":"合约一般签 24 个月，每月付费。预付卡是充值话费，随时可以停用。"},{"who":"B","en":"24 Monate sind mir zu lang. Ich nehme lieber Prepaid.","zh":"24 个月对我来说太长了。我还是选预付卡。"},{"who":"A","en":"Gut. Wie viel Datenvolumen brauchen Sie?","zh":"好。您需要多少流量？"},{"who":"B","en":"Ziemlich viel. Ich benutze unterwegs oft Google Maps und mache Videocalls.","zh":"挺多的。我在外面常用谷歌地图，还打视频电话。"},{"who":"A","en":"Dann empfehle ich diesen Tarif: 20 Gigabyte für 15 Euro im Monat.","zh":"那我推荐这个套餐：每月 20G 流量，15 欧。"},{"who":"B","en":"Gut, den nehme ich. Was brauchen Sie von mir?","zh":"好，就要这个。需要我提供什么？"},{"who":"A","en":"Ihren Reisepass für die Identifizierung, bitte.","zh":"请给我您的护照做身份验证。"},{"who":"B","en":"Hier, bitte. Kann ich die Karte sofort benutzen?","zh":"给您。卡马上能用吗？"},{"who":"A","en":"In ungefähr einer Stunde ist sie aktiv.","zh":"大约一小时后就激活了。"},{"who":"B","en":"Perfekt, vielen Dank!","zh":"太好了，非常感谢！"}],"phrases":[["der Tarif / der Vertrag","套餐 / 合约"],["Was ist der Unterschied?","有什么区别？比较选项时很好用"],["Guthaben aufladen","充值话费；das Guthaben = 余额"],["Das ist mir zu lang.","这对我来说太长了；zu + 形容词 = 太……"],["das Datenvolumen","流量"],["Den nehme ich.","我就要这个；den 指 der Tarif（第四格）"]],"tip":"德国办任何手机卡都要实名验证，记得带护照。Den nehme ich 用指示代词放句首，比 Ich nehme diesen Tarif 更口语。Vertrag 的 V 读 [f]。"},{"id":"urlaub_planen","title":"和朋友计划假期","en_title":"Den Urlaub planen","level":"基础","scene":"你打算明年夏天去德国旅行，和住在慕尼黑的德国朋友 Lukas 视频通话，商量去哪儿、怎么走、住哪儿。","roles":{"A":"朋友 Lukas","B":"你"},"lines":[{"who":"A","en":"Und, steht dein Plan für den Sommer schon?","zh":"怎么样，你夏天的计划定了吗？"},{"who":"B","en":"Fast! Ich möchte im Juli für zwei Wochen nach Deutschland kommen.","zh":"差不多了！我想七月去德国两周。"},{"who":"A","en":"Super! Welche Städte willst du sehen?","zh":"太棒了！你想去哪些城市？"},{"who":"B","en":"Auf jeden Fall München, weil du da wohnst. Danach vielleicht Berlin und Hamburg.","zh":"一定去慕尼黑，因为你住那儿。然后也许去柏林和汉堡。"},{"who":"A","en":"Gute Idee, aber zwei Wochen sind nicht so viel. Vielleicht konzentrierst du dich lieber auf den Süden?","zh":"好主意，不过两周不算长。也许你可以集中去南部？"},{"who":"B","en":"Was würdest du denn empfehlen?","zh":"那你会推荐什么？"},{"who":"A","en":"Ein paar Tage München, dann in die Alpen und an den Bodensee. Das ist im Sommer wunderschön.","zh":"在慕尼黑待几天，然后去阿尔卑斯山和博登湖。那儿夏天美极了。"},{"who":"B","en":"Das klingt toll! Kommt man da gut mit dem Zug hin?","zh":"听起来很棒！坐火车方便去吗？"},{"who":"A","en":"Ja, das geht. Aber mit dem Auto bist du flexibler. Wir könnten auch zusammen fahren, ich habe im Juli Urlaub.","zh":"可以。不过开车更灵活。我们也可以一起去，我七月正好休假。"},{"who":"B","en":"Echt? Das wäre super! Dann müssen wir nur noch die Unterkünfte buchen.","zh":"真的吗？那太好了！那我们只需要订住的地方了。"},{"who":"A","en":"Am besten bald. Im Sommer ist dort schnell alles ausgebucht.","zh":"最好早点订，夏天那边很快就订满了。"},{"who":"B","en":"Okay, ich schicke dir heute Abend ein paar Links und wir entscheiden zusammen.","zh":"好，我今晚发你几个链接，我们一起决定。"},{"who":"A","en":"Perfekt. Ich freue mich schon!","zh":"太好了，我已经开始期待了！"},{"who":"B","en":"Ich mich auch!","zh":"我也是！"}],"phrases":[["Steht dein Plan schon?","你的计划定了吗？stehen = 定下来"],["sich auf etwas konzentrieren","集中在某事上；auf + 第四格"],["Was würdest du empfehlen?","你会推荐什么？würde 让语气更委婉"],["Kommt man da gut hin?","那里好去吗？hinkommen = 到达那里"],["Urlaub haben","休假；请假是 Urlaub nehmen"],["ausgebucht","订满了"],["Ich freue mich schon!","我已经开始期待了！回答 Ich mich auch!"]],"tip":"去城市、国家用 nach（nach Deutschland），去山区和湖边用 in die Alpen / an den Bodensee（表示方向用第四格）。Ich freue mich auf den Urlaub 是期待将来，Ich freue mich über … 是为已发生的事高兴。"},{"id":"wohnungsbesichtigung","title":"看房","en_title":"Bei der Wohnungsbesichtigung","level":"进阶","scene":"你在法兰克福看一套两居室，和房东聊房租、附加费、押金和入住时间，并主动提供材料争取拿到这套房。","roles":{"A":"房东","B":"租房人（你）"},"lines":[{"who":"A","en":"Guten Tag, kommen Sie rein! Das ist die Wohnung.","zh":"您好，请进！这就是那套房子。"},{"who":"B","en":"Guten Tag! Danke, dass ich sie mir ansehen darf. Die Küche ist ja schön hell.","zh":"您好！谢谢您让我来看房。厨房挺亮堂的。"},{"who":"A","en":"Ja, die Einbauküche ist erst zwei Jahre alt.","zh":"是的，整体厨房才用了两年。"},{"who":"B","en":"Wie hoch ist die Miete genau? In der Anzeige stand 950 Euro warm.","zh":"房租具体是多少？广告上写的是暖租 950 欧。"},{"who":"A","en":"Genau, 780 Euro kalt plus 170 Euro Nebenkosten, inklusive Heizung.","zh":"对，冷租 780 欧，加 170 欧附加费，含暖气。"},{"who":"B","en":"Und wie hoch ist die Kaution?","zh":"押金是多少？"},{"who":"A","en":"Drei Kaltmieten, also 2.340 Euro.","zh":"三个月冷租，也就是 2340 欧。"},{"who":"B","en":"Verstehe. Ab wann wäre die Wohnung frei?","zh":"明白。房子从什么时候可以入住？"},{"who":"A","en":"Ab dem ersten März. Was machen Sie beruflich?","zh":"3 月 1 日起。您是做什么工作的？"},{"who":"B","en":"Ich bin Softwareentwickler und habe einen unbefristeten Arbeitsvertrag.","zh":"我是软件开发人员，签的是无固定期限劳动合同。"},{"who":"A","en":"Haben Sie Haustiere, oder rauchen Sie?","zh":"您养宠物吗？或者抽烟吗？"},{"who":"B","en":"Nein, weder noch. Wenn Sie möchten, kann ich Ihnen meine Gehaltsnachweise und eine Schufa-Auskunft schicken.","zh":"都没有。如果您需要，我可以把工资证明和 Schufa 信用报告发给您。"},{"who":"A","en":"Das wäre super. Ich melde mich dann Ende der Woche bei Ihnen.","zh":"那太好了。我这周晚些时候联系您。"},{"who":"B","en":"Vielen Dank! Ich würde mich sehr freuen, von Ihnen zu hören.","zh":"非常感谢！期待您的消息。"}],"phrases":[["die Warmmiete / die Kaltmiete","暖租（含附加费和暖气）/ 冷租（纯房租）"],["die Nebenkosten","附加费：水、垃圾、楼道清洁等"],["die Kaution","押金，法定最多三个月冷租"],["Ab wann wäre die Wohnung frei?","房子从什么时候可以住？wäre 让语气更委婉"],["einen unbefristeten Arbeitsvertrag haben","有无固定期限的劳动合同（房东最爱听）"],["weder noch","两者都不"],["die Schufa-Auskunft","Schufa 信用报告，租房常被要求提供"],["Ich melde mich bei Ihnen.","我会联系您"]],"tip":"德国大城市找房竞争激烈，看房时主动提供 Gehaltsnachweise、Schufa-Auskunft 和前房东的无欠租证明（Mietschuldenfreiheitsbescheinigung）会大大加分。多用 Konjunktiv II（wäre、könnte、würde）显得礼貌又专业。"},{"id":"wg_casting","title":"合租面试","en_title":"Beim WG-Casting","level":"进阶","scene":"你在柏林申请合租公寓（WG）的一个房间，两位室友面试你，主要由 Lena 提问。WG 里大家一律用 du。","roles":{"A":"WG 室友 Lena","B":"申请人（你）"},"lines":[{"who":"A","en":"Hi, komm rein! Ich bin Lena. Willst du einen Tee?","zh":"嗨，进来吧！我是 Lena。要喝茶吗？"},{"who":"B","en":"Hi Lena, ich bin Ray. Ja, gern, danke!","zh":"嗨 Lena，我是 Ray。好啊，谢谢！"},{"who":"A","en":"Erzähl doch mal ein bisschen von dir. Was machst du so?","zh":"说说你自己吧。你平时做什么？"},{"who":"B","en":"Ich bin Softwareentwickler und arbeite meistens im Homeoffice. Ich komme aus China, habe aber die letzten Jahre in Kuala Lumpur gelebt.","zh":"我是做软件开发的，大多在家办公。我是中国人，不过最近几年住在吉隆坡。"},{"who":"A","en":"Spannend! Und warum suchst du ausgerechnet eine WG?","zh":"好有意思！那你为什么偏偏要找合租？"},{"who":"B","en":"Ich bin neu in Berlin und möchte nicht allein wohnen. Außerdem kann ich so mein Deutsch verbessern.","zh":"我刚来柏林，不想一个人住。而且这样可以提高我的德语。"},{"who":"A","en":"Verstehe. Wie stellst du dir das WG-Leben vor? Eher Zweck-WG, oder sollen wir viel zusammen machen?","zh":"理解。你理想的合租生活是什么样的？各住各的，还是大家常一起活动？"},{"who":"B","en":"Ich mag es, ab und zu zusammen zu kochen oder einen Film zu schauen. Aber wenn ich arbeite, brauche ich auch meine Ruhe.","zh":"我喜欢偶尔一起做饭或看电影。不过工作的时候我也需要安静。"},{"who":"A","en":"Passt. Wir haben übrigens einen Putzplan. Ist das okay für dich?","zh":"挺好。顺便说一下，我们有打扫值日表。你能接受吗？"},{"who":"B","en":"Klar, das finde ich sogar gut. Ich koche übrigens gern, chinesisch und malaysisch.","zh":"当然，我反而觉得挺好。顺便说，我很喜欢做饭，中餐和马来西亚菜都会。"},{"who":"A","en":"Oh, das hören wir gern! Hast du noch Fragen an uns?","zh":"哦，这个我们爱听！你还有什么问题要问我们吗？"},{"who":"B","en":"Ja: Wie teilt ihr euch die Kosten für Internet und Strom?","zh":"有：网费和电费你们怎么分？"},{"who":"A","en":"Die teilen wir durch drei, das sind ungefähr 40 Euro pro Person im Monat. Wir melden uns bis Sonntag bei dir.","zh":"三个人平摊，每人每月大约 40 欧。我们周日前给你答复。"},{"who":"B","en":"Super, danke für den Tee und das nette Gespräch!","zh":"太好了，谢谢你们的茶和愉快的聊天！"}],"phrases":[["Erzähl doch mal ein bisschen von dir.","说说你自己吧；doch mal 让请求更随意亲切"],["ausgerechnet","偏偏、恰恰"],["die Zweck-WG","只为分摊房租、各过各的合租"],["sich etwas vorstellen","想象、设想：Wie stellst du dir das vor?"],["meine Ruhe brauchen","需要安静、不被打扰"],["der Putzplan","打扫值日表"],["sich die Kosten teilen","分摊费用"]],"tip":"WG-Casting 很像面试，但气氛随意，一律用 du。重点展示你好相处、愿意分担家务；主动问 Putzplan 和费用怎么分会显得你很靠谱。对两个或更多人说“你们”用 ihr，动词词尾 -t：Wie teilt ihr …？"},{"id":"buergeramt_anmeldung","title":"在市民局登记住址","en_title":"Anmeldung beim Bürgeramt","level":"进阶","scene":"你搬到德国后要在两周内去市民局（Bürgeramt）办住址登记，带着预约、护照、登记表和房东的入住证明。","roles":{"A":"市民局工作人员","B":"申请人（你）"},"lines":[{"who":"A","en":"Guten Tag, nehmen Sie bitte Platz. Was ist Ihr Anliegen?","zh":"您好，请坐。您要办什么事？"},{"who":"B","en":"Guten Tag! Ich möchte meinen Wohnsitz anmelden. Ich habe einen Termin um 9:15 Uhr.","zh":"您好！我想登记住址。我约了 9:15。"},{"who":"A","en":"Haben Sie das Anmeldeformular und die Wohnungsgeberbestätigung dabei?","zh":"您带了登记表和房东开的入住证明吗？"},{"who":"B","en":"Ja, hier sind beide. Und das ist mein Reisepass.","zh":"带了，两份都在这儿。这是我的护照。"},{"who":"A","en":"Danke. Seit wann wohnen Sie unter dieser Adresse?","zh":"谢谢。您从什么时候开始住在这个地址？"},{"who":"B","en":"Seit dem dritten November. Ich bin aus Malaysia hierhergezogen.","zh":"从 11 月 3 日开始。我是从马来西亚搬过来的。"},{"who":"A","en":"Ist das Ihre einzige Wohnung in Deutschland?","zh":"这是您在德国唯一的住处吗？"},{"who":"B","en":"Ja, genau. Entschuldigung, was bedeutet „Religion“ hier im Formular? Muss ich das ausfüllen?","zh":"对。不好意思，表上的“宗教”这一栏是什么意思？我必须填吗？"},{"who":"A","en":"Da geht es um die Kirchensteuer. Wenn Sie keiner Kirche angehören, lassen Sie das Feld einfach frei.","zh":"这和教会税有关。如果您不属于任何教会，这一栏空着就行。"},{"who":"B","en":"Ah, verstehe. Ich gehöre keiner Kirche an.","zh":"啊，明白了。我不属于任何教会。"},{"who":"A","en":"Gut. So, hier ist Ihre Meldebescheinigung.","zh":"好。好了，这是您的住址登记证明。"},{"who":"B","en":"Vielen Dank. Brauche ich die für die Bank?","zh":"非常感谢。开银行账户需要这个吗？"},{"who":"A","en":"Ja, und auch für viele andere Ämter. Bewahren Sie sie gut auf. Ihre Steuer-ID bekommen Sie in ein paar Wochen per Post.","zh":"是的，很多其他部门也要。请好好保管。您的税号几周后会邮寄给您。"},{"who":"B","en":"Perfekt, danke für Ihre Hilfe!","zh":"太好了，谢谢您的帮助！"}],"phrases":[["Was ist Ihr Anliegen?","您要办什么事？办事窗口的正式问法"],["den Wohnsitz anmelden","登记住址；搬走时要 abmelden"],["die Wohnungsgeberbestätigung","房东出具的入住证明，Anmeldung 必备"],["unter dieser Adresse wohnen","住在这个地址；介词用 unter"],["einer Kirche angehören","属于某个教会；angehören 接第三格"],["die Meldebescheinigung","住址登记证明，开户、签合同都要用"],["die Steuer-ID","税号，首次登记后自动邮寄"]],"tip":"搬进新住处后两周内必须办 Anmeldung，开银行账户、签手机合同、拿税号都靠它，大城市的预约要提前抢。“住在某地址”说 unter dieser Adresse wohnen，不说 in dieser Adresse。"},{"id":"bankkonto_eroeffnen","title":"开银行账户","en_title":"Ein Bankkonto eröffnen","level":"进阶","scene":"你开始在德国工作，去银行网点开一个活期账户，顾问给你解释费用、银行卡和网银。","roles":{"A":"银行顾问","B":"客户（你）"},"lines":[{"who":"A","en":"Guten Tag! Womit kann ich Ihnen helfen?","zh":"您好！有什么可以帮您？"},{"who":"B","en":"Guten Tag! Ich möchte ein Girokonto eröffnen. Ich arbeite seit diesem Monat in Deutschland.","zh":"您好！我想开一个活期账户。我这个月开始在德国工作。"},{"who":"A","en":"Gern. Haben Sie Ihren Pass und Ihre Meldebescheinigung dabei?","zh":"好的。您带护照和住址登记证明了吗？"},{"who":"B","en":"Ja, beides. Welche Kosten hat das Konto?","zh":"都带了。这个账户有哪些费用？"},{"who":"A","en":"Das Konto kostet 4,90 Euro im Monat. Bei einem monatlichen Gehaltseingang ab 1.000 Euro ist es kostenlos.","zh":"账户每月 4.90 欧。如果每月工资入账 1000 欧以上就免费。"},{"who":"B","en":"Das klingt gut, mein Gehalt wird ja hierher überwiesen. Bekomme ich auch eine Kreditkarte?","zh":"听起来不错，我的工资正好会打到这里。我也能拿到信用卡吗？"},{"who":"A","en":"Sie bekommen eine Debitkarte. Damit können Sie fast überall bezahlen, auch online. Eine Kreditkarte können Sie später beantragen.","zh":"您会拿到一张借记卡，几乎到处都能付款，网上也可以。信用卡以后可以再申请。"},{"who":"B","en":"Alles klar. Kann ich auch Geld nach Malaysia überweisen?","zh":"好的。我也可以汇钱到马来西亚吗？"},{"who":"A","en":"Ja, das geht über das Online-Banking. Für Überweisungen außerhalb der EU fallen aber Gebühren an.","zh":"可以，通过网银就能办。不过汇到欧盟以外要收手续费。"},{"who":"B","en":"Verstehe. Wie lange dauert es, bis die Karte da ist?","zh":"明白。卡多久能到？"},{"who":"A","en":"Ungefähr eine Woche. Die PIN kommt separat per Post.","zh":"大约一周。密码会单独邮寄。"},{"who":"B","en":"Gut. Und wie richte ich das Online-Banking ein?","zh":"好。那网银怎么开通？"},{"who":"A","en":"Sie laden unsere App herunter und folgen einfach den Schritten. Bei Problemen rufen Sie uns an.","zh":"下载我们的 app，按步骤操作就行。有问题就给我们打电话。"},{"who":"B","en":"Super. Dann würde ich das Konto gern heute eröffnen.","zh":"太好了。那我想今天就开户。"}],"phrases":[["ein Girokonto eröffnen","开活期账户；das Konto 是中性"],["Welche Kosten hat das Konto?","这个账户有哪些费用？"],["der Gehaltseingang","工资入账"],["Geld überweisen / die Überweisung","转账、汇款"],["Es fallen Gebühren an.","会产生手续费；anfallen 是可分动词"],["das Online-Banking einrichten","开通网银；einrichten = 设置、开通"],["Wie lange dauert es, bis …?","要多久才能……？bis 从句动词放句末"]],"tip":"德国日常转账、交房租基本都靠 Überweisung，要会读自己的 IBAN。herunterladen、einrichten、anfallen 都是可分动词：Sie laden die App herunter。die Gebühr 的复数是 Gebühren。"},{"id":"polizei_diebstahl","title":"报警：手机被偷","en_title":"Einen Diebstahl bei der Polizei melden","level":"进阶","scene":"你在慕尼黑坐地铁时手机被偷了，去警察局报案，警察问你经过并给你案件编号。","roles":{"A":"警察","B":"报案人（你）"},"lines":[{"who":"A","en":"Guten Tag. Was ist passiert?","zh":"您好。发生什么事了？"},{"who":"B","en":"Guten Tag. Mir wurde in der U-Bahn mein Handy gestohlen. Ich möchte Anzeige erstatten.","zh":"您好。我的手机在地铁上被偷了。我想报案。"},{"who":"A","en":"Das tut mir leid. Wann und wo genau war das?","zh":"很遗憾。具体是什么时候、在哪儿？"},{"who":"B","en":"Heute gegen 17 Uhr in der U3, zwischen Marienplatz und Münchner Freiheit.","zh":"今天下午五点左右，在 U3 线上，玛利亚广场和慕尼黑自由广场之间。"},{"who":"A","en":"Haben Sie gesehen, wer es war?","zh":"您看到是谁了吗？"},{"who":"B","en":"Nicht genau. Es war sehr voll. Ein Mann hat mich angerempelt, und danach war das Handy weg.","zh":"没看清。车上很挤。有个男人撞了我一下，之后手机就不见了。"},{"who":"A","en":"Wo hatten Sie das Handy?","zh":"手机当时放在哪儿？"},{"who":"B","en":"In meiner Jackentasche. Die Tasche war offen.","zh":"在我的外套口袋里，口袋是敞着的。"},{"who":"A","en":"Können Sie das Handy beschreiben?","zh":"您能描述一下手机吗？"},{"who":"B","en":"Ein schwarzes iPhone mit einer blauen Hülle. Die IMEI-Nummer steht auf der Rechnung.","zh":"一部黑色 iPhone，蓝色手机壳。IMEI 号在发票上有。"},{"who":"A","en":"Sehr gut, die brauchen wir. Haben Sie Ihre SIM-Karte schon sperren lassen?","zh":"很好，我们需要这个。您已经让运营商停卡了吗？"},{"who":"B","en":"Noch nicht, das mache ich gleich. Brauche ich für meine Versicherung eine Bestätigung?","zh":"还没，我马上去办。我的保险需要一份证明吗？"},{"who":"A","en":"Ja, hier ist Ihre Vorgangsnummer. Wenn wir das Handy finden, melden wir uns bei Ihnen.","zh":"需要，这是您的案件编号。如果找到手机，我们会联系您。"},{"who":"B","en":"Vielen Dank für Ihre Hilfe.","zh":"非常感谢您的帮助。"}],"phrases":[["Was ist passiert?","发生什么事了？"],["Mir wurde … gestohlen.","我的……被偷了；被动态 + 第三格 mir"],["Anzeige erstatten","报案、正式举报"],["Ein Mann hat mich angerempelt.","有个男人撞了我；anrempeln = 故意或不小心撞人"],["Das Handy war weg.","手机不见了；weg sein = 不见了"],["etwas sperren lassen","让人把……冻结/停用（卡、账户）"],["die Vorgangsnummer","案件编号，保险理赔要用"]],"tip":"德国报警电话 110，急救和消防 112。报案时常用被动：Mir wurde mein Handy gestohlen / Mein Handy wurde gestohlen，不必说 Jemand hat …（是谁偷的你也不知道）。紧急时直接喊 Hilfe! 或 Rufen Sie bitte die Polizei!"},{"id":"bug_erklaeren","title":"向产品经理解释 bug","en_title":"Einen Bug erklären","level":"进阶","scene":"客户反馈支付页面出错，德国产品经理 Frau Hoffmann 在视频会议上问你原因、影响范围和修复计划。","roles":{"A":"产品经理 Frau Hoffmann","B":"你（开发）"},"lines":[{"who":"A","en":"Ray, können Sie mir erklären, was mit der Bezahlseite los ist?","zh":"Ray，您能给我解释一下支付页面出了什么问题吗？"},{"who":"B","en":"Ja, natürlich. Seit dem Update am Dienstag schlägt bei manchen Kunden die Zahlung fehl.","zh":"当然。自从周二更新以后，部分客户付款失败。"},{"who":"A","en":"Wie viele Kunden sind betroffen?","zh":"有多少客户受影响？"},{"who":"B","en":"Laut unseren Logs etwa fünf Prozent, und zwar nur Kunden, die mit Kreditkarte zahlen.","zh":"根据日志大约 5%，而且只有用信用卡付款的客户。"},{"who":"A","en":"Wissen Sie schon, woran es liegt?","zh":"您已经知道原因了吗？"},{"who":"B","en":"Ja. Beim Update wurde ein Timeout verkürzt. Wenn die Bank zu langsam antwortet, bricht unser System die Zahlung ab.","zh":"知道了。更新时缩短了一个超时时间。如果银行响应太慢，我们的系统就会中断付款。"},{"who":"A","en":"Verstehe. Wann können Sie das beheben?","zh":"明白。您什么时候能修好？"},{"who":"B","en":"Den Fix habe ich schon geschrieben, er wird gerade getestet. Wenn alles gut geht, können wir ihn heute Abend ausrollen.","zh":"修复我已经写好了，正在测试。如果一切顺利，今晚就能上线。"},{"who":"A","en":"Gut. Und was ist mit den Kunden, deren Zahlung fehlgeschlagen ist?","zh":"好。那些付款失败的客户怎么办？"},{"who":"B","en":"Ich würde vorschlagen, dass der Support ihnen eine E-Mail schickt. Ich kann eine Liste der betroffenen Bestellungen erstellen.","zh":"我建议客服给他们发邮件。我可以整理一份受影响订单的清单。"},{"who":"A","en":"Gute Idee. Wie verhindern wir, dass so etwas noch einmal passiert?","zh":"好主意。我们怎么防止这种事再次发生？"},{"who":"B","en":"Wir sollten einen automatischen Test für langsame Antworten der Bank einbauen. Außerdem richte ich einen Alarm für steigende Fehlerraten ein.","zh":"我们应该加一个针对银行响应慢的自动化测试。另外我会设置一个错误率上升时的告警。"},{"who":"A","en":"Prima. Halten Sie mich bitte auf dem Laufenden.","zh":"很好。请随时告诉我进展。"},{"who":"B","en":"Mache ich. Ich schreibe Ihnen, sobald der Fix live ist.","zh":"好的。修复一上线我就给您发消息。"}],"phrases":[["Was ist mit … los?","……怎么了？出了什么问题？"],["Die Zahlung schlägt fehl.","付款失败；fehlschlagen 是可分动词"],["betroffen sein","受影响"],["Woran liegt es?","原因是什么？回答用 Es liegt an …"],["etwas beheben","修复、排除（故障）"],["etwas ausrollen","发布、上线（新版本）"],["Ich würde vorschlagen, dass …","我建议……；委婉提建议"],["Halten Sie mich auf dem Laufenden.","请随时告诉我进展"]],"tip":"解释问题按三步走：现象（Seit … schlägt … fehl）→ 原因（Es liegt an … / Beim Update wurde …）→ 方案（Ich würde vorschlagen, dass …）。dass、wenn、sobald 引导的从句动词放最后：…, sobald der Fix live ist。"},{"id":"meeting_verschieben","title":"跨时区改会议时间","en_title":"Ein Meeting verschieben","level":"进阶","scene":"德国同事 Frau Meier 约你周四德国时间 9 点开会，但那时吉隆坡已经下午四点，你另有客户会议，于是打电话商量改时间。","roles":{"A":"德国同事 Frau Meier","B":"你"},"lines":[{"who":"B","en":"Hallo Frau Meier, hier ist Ray. Haben Sie kurz Zeit?","zh":"您好 Meier 女士，我是 Ray。您现在方便吗？"},{"who":"A","en":"Hallo Ray! Ja, worum geht es?","zh":"你好 Ray！方便，什么事？"},{"who":"B","en":"Es geht um das Meeting am Donnerstag um 9 Uhr. Könnten wir es vielleicht verschieben?","zh":"是关于周四 9 点的会议。我们能不能改个时间？"},{"who":"A","en":"Ja, das sollte gehen. Passt Ihnen die Uhrzeit nicht?","zh":"应该可以。是这个时间不合适吗？"},{"who":"B","en":"Leider nicht. 9 Uhr bei Ihnen ist bei mir schon 16 Uhr, und da habe ich einen Kundentermin.","zh":"可惜不行。您那边 9 点，我这边已经下午 4 点了，那时我有一个客户会议。"},{"who":"A","en":"Ach so, der Zeitunterschied! Wie wäre es dann mit Donnerstag um 8 Uhr?","zh":"哦对，时差！那周四 8 点怎么样？"},{"who":"B","en":"Das wäre bei mir 15 Uhr. Das passt leider auch nicht, weil der Kundentermin schon um halb drei anfängt.","zh":"那我这边是下午 3 点。可惜也不行，因为客户会议两点半就开始了。"},{"who":"A","en":"Hm. Und am Freitag? Da bin ich den ganzen Vormittag frei.","zh":"嗯。那周五呢？我周五整个上午都有空。"},{"who":"B","en":"Freitag um 9 Uhr deutscher Zeit wäre perfekt. Dauert das Meeting eine Stunde?","zh":"周五德国时间 9 点很合适。会议要一个小时吗？"},{"who":"A","en":"Eher 45 Minuten. Ich passe die Einladung gleich an.","zh":"大概 45 分钟。我这就把会议邀请改过去。"},{"who":"B","en":"Vielen Dank! Könnten Sie die Uhrzeit bitte in beiden Zeitzonen angeben? Dann gibt es keine Missverständnisse.","zh":"非常感谢！您能在邀请里写上两个时区的时间吗？这样就不会弄错了。"},{"who":"A","en":"Gute Idee. Übrigens: Ende März stellen wir die Uhren um, dann sind es nur noch sechs Stunden Unterschied.","zh":"好主意。顺便说一下：三月底我们改夏令时，到时候时差就只有六个小时了。"},{"who":"B","en":"Stimmt, das vergesse ich immer! Danke für den Hinweis.","zh":"没错，这个我总是忘！谢谢提醒。"},{"who":"A","en":"Gern. Dann bis Freitag!","zh":"不客气。那周五见！"}],"phrases":[["Haben Sie kurz Zeit?","您现在有空吗？打电话、找人谈事的开场"],["Es geht um …","是关于……的事；Worum geht es? 什么事？"],["ein Meeting verschieben","把会议改期/推迟"],["Passt Ihnen …?","……您方便吗？passen + 第三格"],["Wie wäre es mit …?","……怎么样？委婉提议"],["der Zeitunterschied","时差"],["um 9 Uhr deutscher Zeit","德国时间 9 点"],["die Uhren umstellen","调钟（夏令时/冬令时切换）"]],"tip":"约时间多用 Konjunktiv II 显得礼貌：Könnten wir …? Wie wäre es mit …? Das wäre …。德国冬季比吉隆坡晚 7 小时，夏令时（3 月底到 10 月底）晚 6 小时；写邀请时注明两边时间最保险。"},{"id":"code_review_feedback","title":"讨论代码评审意见","en_title":"Feedback im Code-Review","level":"进阶","scene":"同事 Jonas 对你的 Pull Request 提了意见，你们在通话里讨论。你接受一部分建议，也礼貌地坚持另一部分。团队里用 du。","roles":{"A":"同事 Jonas","B":"你"},"lines":[{"who":"A","en":"Hast du kurz Zeit? Ich wollte mit dir über deinen Pull Request sprechen.","zh":"你有空吗？我想和你聊聊你的 Pull Request。"},{"who":"B","en":"Klar! Ich habe deine Kommentare gesehen. Danke für das ausführliche Feedback.","zh":"当然！我看到你的评论了。谢谢你这么详细的反馈。"},{"who":"A","en":"Gern. Die Funktion ist ziemlich lang. Ich würde sie in zwei kleinere Funktionen aufteilen.","zh":"不客气。这个函数挺长的，我会把它拆成两个小函数。"},{"who":"B","en":"Da hast du recht, das mache ich.","zh":"你说得对，我来改。"},{"who":"A","en":"Und warum hast du hier keine Bibliothek für die Datumsberechnung verwendet?","zh":"还有，这里为什么没用库来算日期？"},{"who":"B","en":"Darüber habe ich nachgedacht. Aber wir brauchen nur eine einfache Berechnung, und jede neue Abhängigkeit macht das Projekt größer.","zh":"我考虑过。但我们只需要一个简单的计算，而每加一个新依赖项目就更大。"},{"who":"A","en":"Hm, aber bei Zeitzonen passieren schnell Fehler.","zh":"嗯，不过时区很容易出错。"},{"who":"B","en":"Das stimmt. Deshalb habe ich Tests für verschiedene Zeitzonen geschrieben. Wenn wir später mehr brauchen, können wir immer noch eine Bibliothek einbauen.","zh":"没错。所以我写了针对不同时区的测试。如果以后需要更多功能，我们还是可以再引入一个库。"},{"who":"A","en":"Okay, das überzeugt mich. Lass es so.","zh":"好，你说服我了。就这样吧。"},{"who":"B","en":"Gibt es sonst noch etwas?","zh":"还有别的吗？"},{"who":"A","en":"Nur ein paar Kleinigkeiten bei den Variablennamen. Manche sind nicht ganz klar.","zh":"就是变量名有些小问题，有几个不太清楚。"},{"who":"B","en":"Gut, die ändere ich auch. Ich melde mich, wenn ich fertig bin.","zh":"好，那些我也改。改完了跟你说。"},{"who":"A","en":"Super, danke!","zh":"太好了，谢谢！"}],"phrases":[["Hast du kurz Zeit?","你有空吗？找同事聊事的开场"],["Danke für das Feedback.","谢谢反馈；das Feedback 是中性"],["Da hast du recht.","你说得对；recht 小写"],["Darüber habe ich nachgedacht.","这个我考虑过；nachdenken über + 第四格"],["die Abhängigkeit","依赖（项）"],["Das überzeugt mich.","你说服我了"],["Ich melde mich, wenn …","……的时候我跟你说"]],"tip":"礼貌地反对三步走：先认同（Das stimmt / Da hast du recht），再给理由（Aber …），最后留退路（Wenn …, können wir immer noch …）。德国同事给反馈很直接，不代表不友好，你直接讲理由就好。"}],"functions":[{"id":"begruessen","title":"👋 打招呼和告别","note":"Hallo 什么场合都能用；Guten Tag / Auf Wiedersehen 偏正式，Tschüss 偏随意。德国人问 Wie geht's? 比英语 How are you 更像真的在问，一般熟人之间才问，回答也可以说实话。","items":[{"en":"Hallo!","zh":"你好！","reg":"中性","ex":"A: Hallo, Ray! / B: Hallo, Anna! Wie geht's?","exzh":"A：你好，Ray！/ B：你好，Anna！最近怎么样？"},{"en":"Guten Morgen!","zh":"早上好！","reg":"中性","ex":"A: Guten Morgen! / B: Morgen! Gut geschlafen?","exzh":"A：早上好！/ B：早！睡得好吗？"},{"en":"Guten Tag!","zh":"您好！（白天通用）","reg":"正式","ex":"A: Guten Tag, was darf es sein? / B: Guten Tag, ich hätte gern zwei Brötchen.","exzh":"A：您好，您要点什么？/ B：您好，我要两个小面包。"},{"en":"Wie geht's?","zh":"最近怎么样？（对 du 的熟人）","reg":"随意","ex":"A: Hey Lisa, wie geht's? / B: Gut, danke! Und dir?","exzh":"A：嘿，Lisa，最近怎么样？/ B：挺好，谢谢！你呢？"},{"en":"Wie geht es Ihnen?","zh":"您好吗？（对 Sie 的人，Ihnen 是与格）","reg":"正式","ex":"A: Guten Tag, Herr Weber, wie geht es Ihnen? / B: Danke, sehr gut. Und Ihnen?","exzh":"A：您好，韦伯先生，您好吗？/ B：谢谢，很好。您呢？"},{"en":"Ganz gut, und dir?","zh":"还不错，你呢？","reg":"随意","ex":"A: Na, wie geht's? / B: Ganz gut, und dir?","exzh":"A：嘿，怎么样？/ B：还不错，你呢？"},{"en":"Lange nicht gesehen!","zh":"好久不见！","reg":"随意","ex":"A: Ray! Lange nicht gesehen! / B: Ja, stimmt! Wie geht's dir?","exzh":"A：Ray！好久不见！/ B：是啊！你怎么样？"},{"en":"Tschüss!","zh":"拜拜！","reg":"随意","ex":"A: Ich muss los. Tschüss! / B: Tschüss, bis morgen!","exzh":"A：我得走了，拜拜！/ B：拜拜，明天见！"},{"en":"Auf Wiedersehen!","zh":"再见！（正式，当面）","reg":"正式","ex":"A: Vielen Dank für Ihren Besuch. / B: Gern. Auf Wiedersehen!","exzh":"A：非常感谢您的光临。/ B：不客气，再见！"},{"en":"Bis später!","zh":"回头见！","reg":"随意","ex":"A: Ich gehe jetzt in die Mittagspause. / B: Okay, bis später!","exzh":"A：我现在去午休了。/ B：好，回头见！"},{"en":"Schönen Abend noch!","zh":"祝你晚上愉快！","reg":"中性","ex":"A: Schönen Abend noch! / B: Danke, gleichfalls!","exzh":"A：祝你晚上愉快！/ B：谢谢，你也是！"}]},{"id":"vorstellen","title":"🙋 自我介绍","note":"Ich heiße … / Ich bin … / Mein Name ist …（最正式）。说职业时不加冠词：Ich bin Softwareentwickler，不说 ein Softwareentwickler。来自哪里用 aus，住在城市用 in。","items":[{"en":"Ich heiße Ray.","zh":"我叫 Ray。","reg":"中性","ex":"A: Wie heißt du? / B: Ich heiße Ray. Und du?","exzh":"A：你叫什么名字？/ B：我叫 Ray。你呢？"},{"en":"Mein Name ist Rui, aber alle nennen mich Ray.","zh":"我的名字是 Rui，不过大家都叫我 Ray。","reg":"中性","ex":"A: Wie ist Ihr Name, bitte? / B: Mein Name ist Rui, aber alle nennen mich Ray.","exzh":"A：请问您叫什么名字？/ B：我叫 Rui，不过大家都叫我 Ray。"},{"en":"Ich komme aus China.","zh":"我来自中国。","reg":"中性","ex":"A: Woher kommst du? / B: Ich komme aus China, aber ich wohne in Malaysia.","exzh":"A：你从哪里来？/ B：我来自中国，不过住在马来西亚。"},{"en":"Ich wohne in Kuala Lumpur.","zh":"我住在吉隆坡。","reg":"中性","ex":"A: Wo wohnen Sie? / B: Ich wohne in Kuala Lumpur, in Malaysia.","exzh":"A：您住在哪里？/ B：我住在马来西亚的吉隆坡。"},{"en":"Ich bin Softwareentwickler.","zh":"我是软件开发工程师。（职业前不加 ein）","reg":"中性","ex":"A: Was machst du beruflich? / B: Ich bin Softwareentwickler. Ich arbeite bei einer IT-Firma.","exzh":"A：你做什么工作？/ B：我是软件开发工程师，在一家 IT 公司上班。"},{"en":"Ich lerne seit drei Monaten Deutsch.","zh":"我学德语三个月了。（seit + 现在时）","reg":"中性","ex":"A: Dein Deutsch ist schon gut! / B: Danke! Ich lerne seit drei Monaten Deutsch.","exzh":"A：你的德语已经不错了！/ B：谢谢！我学德语三个月了。"},{"en":"Freut mich!","zh":"很高兴认识你/您！","reg":"中性","ex":"A: Ich bin Jonas, der neue Kollege. / B: Freut mich! Ich bin Ray.","exzh":"A：我是 Jonas，新同事。/ B：很高兴认识你！我是 Ray。"},{"en":"Freut mich, Sie kennenzulernen.","zh":"很高兴认识您。","reg":"正式","ex":"A: Darf ich vorstellen? Das ist Frau Schneider. / B: Freut mich, Sie kennenzulernen.","exzh":"A：我来介绍一下，这是施耐德女士。/ B：很高兴认识您。"},{"en":"Darf ich mich kurz vorstellen?","zh":"我可以简单介绍一下自己吗？","reg":"正式","ex":"Darf ich mich kurz vorstellen? Ich bin Ray, Backend-Entwickler aus dem Team in Kuala Lumpur.","exzh":"我简单介绍一下自己：我是 Ray，吉隆坡团队的后端开发。"}]},{"id":"bitten_danken","title":"🙏 请求和道谢","note":"bitte 是万能词：「请」「不客气」「给你」都是它。Danke schön 的标准回答是 Bitte schön；Gern geschehen 更客气。请人帮忙加个 bitte 或用 Könnten Sie … 就很礼貌。","items":[{"en":"Bitte!","zh":"不客气！/ 请！/ 给你！","reg":"中性","ex":"A: Danke! / B: Bitte!","exzh":"A：谢谢！/ B：不客气！"},{"en":"Danke schön!","zh":"谢谢！","reg":"中性","ex":"A: Hier ist Ihr Kaffee. / B: Danke schön!","exzh":"A：这是您的咖啡。/ B：谢谢！"},{"en":"Vielen Dank!","zh":"非常感谢！","reg":"中性","ex":"A: Ich habe dir die Datei geschickt. / B: Super, vielen Dank!","exzh":"A：我把文件发给你了。/ B：太好了，非常感谢！"},{"en":"Gern geschehen.","zh":"不客气。（乐意效劳）","reg":"中性","ex":"A: Danke für deine Hilfe! / B: Gern geschehen.","exzh":"A：谢谢你的帮忙！/ B：不客气。"},{"en":"Gerne!","zh":"不客气！（口语，最常用）","reg":"随意","ex":"A: Danke fürs Mitnehmen! / B: Gerne!","exzh":"A：谢谢你捎我一程！/ B：不客气！"},{"en":"Kein Problem.","zh":"没问题 / 小事。","reg":"随意","ex":"A: Danke, dass du so schnell geantwortet hast. / B: Kein Problem.","exzh":"A：谢谢你回复得这么快。/ B：小事。"},{"en":"Kannst du mir mal das Salz geben?","zh":"你能把盐递给我吗？（mal 让请求更随和）","reg":"随意","ex":"A: Kannst du mir mal das Salz geben? / B: Klar, hier.","exzh":"A：能把盐递给我吗？/ B：当然，给你。"},{"en":"Könnten Sie bitte das Fenster zumachen?","zh":"您能把窗户关上吗？（Könnten 比 Können 更客气）","reg":"正式","ex":"A: Könnten Sie bitte das Fenster zumachen? Es zieht. / B: Ja, natürlich.","exzh":"A：您能把窗户关上吗？有穿堂风。/ B：好的，当然。"},{"en":"Vielen Dank für Ihre Hilfe.","zh":"非常感谢您的帮助。","reg":"正式","ex":"A: So, jetzt funktioniert es wieder. / B: Vielen Dank für Ihre Hilfe!","exzh":"A：好了，现在又能用了。/ B：非常感谢您的帮助！"},{"en":"Das ist sehr nett von Ihnen.","zh":"您真是太好了。","reg":"正式","ex":"A: Ich kann Sie zum Bahnhof bringen. / B: Oh, das ist sehr nett von Ihnen!","exzh":"A：我可以送您去火车站。/ B：哦，您真是太好了！"},{"en":"Danke, gleichfalls!","zh":"谢谢，你也是！（回应祝福）","reg":"中性","ex":"A: Schönes Wochenende! / B: Danke, gleichfalls!","exzh":"A：周末愉快！/ B：谢谢，你也是！"}]},{"id":"entschuldigen","title":"🙇 道歉","note":"Entschuldigung 既是「对不起」，也是「打扰一下」（引起别人注意）。真心道歉用 Es tut mir leid（leid 小写）。年轻人和同事之间 Sorry 也很常见。","items":[{"en":"Entschuldigung!","zh":"不好意思 / 打扰一下 / 对不起","reg":"中性","ex":"A: Entschuldigung, ist hier noch frei? / B: Ja, bitte.","exzh":"A：不好意思，这里有人吗？/ B：没人，请坐。"},{"en":"Tut mir leid.","zh":"对不起。","reg":"中性","ex":"A: Du bist zehn Minuten zu spät. / B: Tut mir leid, die U-Bahn hatte Verspätung.","exzh":"A：你迟到了十分钟。/ B：对不起，地铁晚点了。"},{"en":"Sorry!","zh":"抱歉！（口语）","reg":"随意","ex":"A: Au, das war mein Fuß! / B: Oh, sorry!","exzh":"A：哎哟，踩到我脚了！/ B：哦，抱歉！"},{"en":"Es tut mir wirklich leid.","zh":"真的非常抱歉。","reg":"正式","ex":"A: Die Lieferung ist schon wieder nicht da. / B: Es tut mir wirklich leid. Wir kümmern uns sofort darum.","exzh":"A：货又没到。/ B：真的非常抱歉，我们马上处理。"},{"en":"Das war meine Schuld.","zh":"是我的错。","reg":"中性","ex":"A: Warum ist der Build kaputt? / B: Das war meine Schuld. Ich kümmere mich gleich darum.","exzh":"A：构建为什么挂了？/ B：是我的错，我马上处理。"},{"en":"Entschuldigen Sie die Verspätung.","zh":"抱歉我迟到了。（正式）","reg":"正式","ex":"Entschuldigen Sie die Verspätung, ich hatte Probleme mit dem Internet.","exzh":"抱歉我迟到了，刚才网络出了问题。"},{"en":"Schon gut.","zh":"没事，算了。（回应道歉）","reg":"随意","ex":"A: Sorry, ich habe deine Nachricht übersehen. / B: Schon gut, kein Stress.","exzh":"A：抱歉，我没看到你的消息。/ B：没事，别有压力。"},{"en":"Macht nichts.","zh":"没关系。","reg":"中性","ex":"A: Entschuldigung, ich habe mich verwählt. / B: Macht nichts. Auf Wiederhören!","exzh":"A：不好意思，我打错电话了。/ B：没关系，再见！"},{"en":"Entschuldige, ich wollte dich nicht stören.","zh":"不好意思，我不是故意打扰你。","reg":"随意","ex":"A: Entschuldige, ich wollte dich nicht stören. / B: Kein Problem, ich habe gerade Pause.","exzh":"A：不好意思，打扰你了。/ B：没事，我正好在休息。"}]},{"id":"nachfragen","title":"❓ 听不懂时怎么问","note":"听不懂就直接问，德国人很习惯。Wie bitte? 是最常用的「请再说一遍」，别用 Was?（对陌生人显得粗鲁）。问词义用 Was bedeutet …?，问拼写用 Wie schreibt man das?","items":[{"en":"Wie bitte?","zh":"您说什么？/ 请再说一遍。","reg":"中性","ex":"A: Brauchen Sie eine Tüte? / B: Wie bitte?","exzh":"A：您需要袋子吗？/ B：您说什么？"},{"en":"Können Sie das bitte wiederholen?","zh":"您能再说一遍吗？","reg":"正式","ex":"A: Ihre Kundennummer ist 4-7-1-1-9. / B: Können Sie das bitte wiederholen?","exzh":"A：您的客户号是 4-7-1-1-9。/ B：您能再说一遍吗？"},{"en":"Können Sie bitte langsamer sprechen?","zh":"您能说慢一点吗？","reg":"中性","ex":"A: Sie müssen zuerst zum Bürgeramt und dann zur Ausländerbehörde. / B: Entschuldigung, können Sie bitte langsamer sprechen?","exzh":"A：您得先去市民局，再去外管局。/ B：不好意思，您能说慢一点吗？"},{"en":"Was bedeutet „Feierabend“?","zh":"Feierabend 是什么意思？","reg":"中性","ex":"A: Was bedeutet „Feierabend“? / B: Das ist die Freizeit nach der Arbeit.","exzh":"A：Feierabend 是什么意思？/ B：就是下班后的时间。"},{"en":"Ich habe das nicht verstanden.","zh":"我没听懂。","reg":"中性","ex":"A: Alles klar? / B: Nicht ganz. Ich habe den letzten Teil nicht verstanden.","exzh":"A：都清楚了吗？/ B：不太清楚，最后一部分我没听懂。"},{"en":"Was meinst du damit?","zh":"你这话是什么意思？","reg":"随意","ex":"A: Der Code ist ein bisschen … kreativ. / B: Haha, was meinst du damit?","exzh":"A：这代码有点……有创意。/ B：哈哈，你什么意思？"},{"en":"Wie sagt man „durian“ auf Deutsch?","zh":"「榴莲」用德语怎么说？","reg":"中性","ex":"A: Wie sagt man „durian“ auf Deutsch? / B: Ich glaube, auch einfach „Durian“.","exzh":"A：「榴莲」德语怎么说？/ B：我觉得也就叫 Durian。"},{"en":"Wie schreibt man das?","zh":"这个怎么拼？","reg":"中性","ex":"A: Ich wohne in der Schlossstraße. / B: Wie schreibt man das?","exzh":"A：我住在城堡街。/ B：这个怎么拼？"},{"en":"Habe ich Sie richtig verstanden?","zh":"我理解得对吗？（确认信息）","reg":"正式","ex":"Habe ich Sie richtig verstanden: Das Meeting ist am Donnerstag und nicht am Mittwoch?","exzh":"我理解得对吗：会议是周四，不是周三？"},{"en":"Noch mal, bitte.","zh":"请再说一次。（口语）","reg":"随意","ex":"A: Mein WLAN-Passwort ist „Sonnenblume77“. / B: Noch mal, bitte?","exzh":"A：我的 Wi-Fi 密码是 Sonnenblume77。/ B：再说一次？"}]},{"id":"meinung","title":"💬 表达观点","note":"Ich finde / Ich denke / Ich glaube 后面可以直接接主句，也可以接 dass（动词放句末）。Meiner Meinung nach 后面动词紧跟（倒装）：Meiner Meinung nach ist …","items":[{"en":"Ich finde das gut.","zh":"我觉得这个不错。","reg":"中性","ex":"A: Wie findest du die neue App? / B: Ich finde sie richtig gut.","exzh":"A：你觉得这个新 App 怎么样？/ B：我觉得挺好的。"},{"en":"Ich finde, dass …","zh":"我觉得……（dass 从句动词放句末）","reg":"中性","ex":"Ich finde, dass wir mehr Tests schreiben sollten.","exzh":"我觉得我们应该多写点测试。"},{"en":"Meiner Meinung nach …","zh":"在我看来……（后面动词紧跟）","reg":"正式","ex":"Meiner Meinung nach ist die zweite Lösung besser.","exzh":"在我看来，第二个方案更好。"},{"en":"Ich denke, das ist möglich.","zh":"我觉得这是可能的。","reg":"中性","ex":"A: Schaffen wir das bis Freitag? / B: Ich denke, das ist möglich.","exzh":"A：我们周五前能搞定吗？/ B：我觉得可以。"},{"en":"Ich bin mir nicht sicher.","zh":"我不太确定。","reg":"中性","ex":"A: Ist das eine gute Idee? / B: Ich bin mir nicht sicher.","exzh":"A：这是个好主意吗？/ B：我不太确定。"},{"en":"Ich glaube schon.","zh":"我想是的。","reg":"中性","ex":"A: Hat der Supermarkt heute geöffnet? / B: Ich glaube schon.","exzh":"A：超市今天开门吗？/ B：我想是开的。"},{"en":"Ich glaube nicht.","zh":"我觉得不会。/ 我想不是。","reg":"中性","ex":"A: Regnet es heute noch? / B: Ich glaube nicht.","exzh":"A：今天还会下雨吗？/ B：我觉得不会。"},{"en":"Was hältst du davon?","zh":"你觉得怎么样？","reg":"随意","ex":"A: Wir könnten am Samstag grillen. Was hältst du davon? / B: Gute Idee!","exzh":"A：我们周六可以烧烤，你觉得怎么样？/ B：好主意！"},{"en":"Was ist Ihre Meinung dazu?","zh":"您对此怎么看？","reg":"正式","ex":"Frau Müller, was ist Ihre Meinung dazu?","exzh":"穆勒女士，您对此怎么看？"},{"en":"Ehrlich gesagt …","zh":"说实话……（后面动词紧跟）","reg":"中性","ex":"Ehrlich gesagt finde ich das Design ein bisschen zu bunt.","exzh":"说实话，我觉得这个设计有点太花了。"}]},{"id":"zustimmen_widersprechen","title":"🤝 同意与委婉反对","note":"德国人说话比较直接，不同意可以直说，但用 Ja, aber … / Ich sehe das ein bisschen anders 会显得更客气。注意 recht haben（有道理）不要说成 richtig haben。","items":[{"en":"Genau!","zh":"没错！","reg":"随意","ex":"A: Wir brauchen also mehr Zeit. / B: Genau!","exzh":"A：所以我们需要更多时间。/ B：没错！"},{"en":"Stimmt.","zh":"对。/ 确实。","reg":"随意","ex":"A: Hier ist es echt teuer. / B: Stimmt.","exzh":"A：这里真贵。/ B：确实。"},{"en":"Da hast du recht.","zh":"你说得对。","reg":"中性","ex":"A: Wir sollten das vorher testen. / B: Da hast du recht.","exzh":"A：我们应该先测一下。/ B：你说得对。"},{"en":"Da bin ich ganz Ihrer Meinung.","zh":"我完全同意您的看法。","reg":"正式","ex":"A: Die Kunden brauchen eine einfachere Lösung. / B: Da bin ich ganz Ihrer Meinung.","exzh":"A：客户需要更简单的方案。/ B：我完全同意您的看法。"},{"en":"Das sehe ich auch so.","zh":"我也这么看。","reg":"中性","ex":"A: Ich finde, das neue Feature ist noch nicht reif für das Release. / B: Das sehe ich auch so.","exzh":"A：我觉得新功能还不够成熟，不能发布。/ B：我也这么看。"},{"en":"Ja, aber …","zh":"是的，不过……","reg":"中性","ex":"A: Lass uns einfach alles neu schreiben! / B: Ja, aber dafür haben wir keine Zeit.","exzh":"A：干脆全部重写吧！/ B：是，不过我们没时间。"},{"en":"Ich sehe das ein bisschen anders.","zh":"我的看法有点不一样。","reg":"中性","ex":"A: Im Homeoffice arbeitet man weniger. / B: Ich sehe das ein bisschen anders.","exzh":"A：在家办公的人干活少。/ B：我的看法有点不一样。"},{"en":"Das stimmt nicht ganz.","zh":"不完全对。","reg":"中性","ex":"A: In Malaysia ist es überall heiß. / B: Das stimmt nicht ganz. In den Cameron Highlands ist es ziemlich kühl.","exzh":"A：马来西亚到处都很热。/ B：不完全对，金马伦高原挺凉快的。"},{"en":"Auf keinen Fall!","zh":"绝对不行！","reg":"随意","ex":"A: Sollen wir freitags um 17 Uhr deployen? / B: Auf keinen Fall!","exzh":"A：我们周五下午五点上线吧？/ B：绝对不行！"},{"en":"Einverstanden.","zh":"同意。/ 就这么定了。","reg":"中性","ex":"A: Dann treffen wir uns um zehn. / B: Einverstanden.","exzh":"A：那我们十点见。/ B：就这么定。"}]},{"id":"vorschlaege","title":"💡 提建议","note":"朋友之间常用 Lass uns … / Wollen wir …? / Hast du Lust, … zu …?；稍正式用 Wir könnten … / Wie wäre es mit …?（mit + 与格）。","items":[{"en":"Lass uns einen Kaffee trinken gehen!","zh":"我们去喝杯咖啡吧！","reg":"随意","ex":"A: Ich bin so müde. / B: Lass uns einen Kaffee trinken gehen!","exzh":"A：我好累。/ B：我们去喝杯咖啡吧！"},{"en":"Wollen wir heute Abend essen gehen?","zh":"我们今晚出去吃饭吧？","reg":"随意","ex":"A: Wollen wir heute Abend essen gehen? / B: Gern! Wohin?","exzh":"A：今晚出去吃饭吗？/ B：好啊！去哪儿？"},{"en":"Wie wäre es mit Freitag?","zh":"周五怎么样？","reg":"中性","ex":"A: Wann passt es dir? / B: Wie wäre es mit Freitag?","exzh":"A：你什么时候方便？/ B：周五怎么样？"},{"en":"Wir könnten …","zh":"我们可以……","reg":"中性","ex":"Wir könnten das Problem in zwei kleinere Tickets aufteilen.","exzh":"我们可以把这个问题拆成两个小工单。"},{"en":"Hast du Lust, am Wochenende wandern zu gehen?","zh":"你周末想去徒步吗？","reg":"随意","ex":"A: Hast du Lust, am Wochenende wandern zu gehen? / B: Ja, total gern!","exzh":"A：周末想去徒步吗？/ B：非常想！"},{"en":"Sollen wir eine kurze Pause machen?","zh":"我们休息一下吧？","reg":"中性","ex":"A: Sollen wir eine kurze Pause machen? / B: Gute Idee, zehn Minuten?","exzh":"A：休息一下吧？/ B：好主意，十分钟？"},{"en":"Ich schlage vor, dass …","zh":"我建议……","reg":"正式","ex":"Ich schlage vor, dass wir das Meeting auf nächste Woche verschieben.","exzh":"我建议把会议推到下周。"},{"en":"Warum nicht?","zh":"为什么不呢？/ 好啊。","reg":"随意","ex":"A: Kommst du mit ins Kino? / B: Warum nicht?","exzh":"A：一起去看电影吗？/ B：好啊，为什么不呢？"},{"en":"Gute Idee!","zh":"好主意！","reg":"中性","ex":"A: Wir könnten im Team einen Deutschkurs machen. / B: Gute Idee!","exzh":"A：我们团队可以一起上德语课。/ B：好主意！"}]},{"id":"einladungen","title":"🎉 邀请、接受和拒绝","note":"拒绝时德国人习惯：先道谢或说 leider，再给理由，最后提 ein anderes Mal。注意 Ich lade dich ein 既是「我邀请你」，也常是「我请客」。","items":[{"en":"Hast du am Samstag Zeit?","zh":"你周六有空吗？","reg":"随意","ex":"A: Hast du am Samstag Zeit? / B: Ja, warum?","exzh":"A：你周六有空吗？/ B：有啊，怎么了？"},{"en":"Möchtest du mitkommen?","zh":"你想一起来吗？","reg":"中性","ex":"A: Wir gehen heute Abend in eine Bar. Möchtest du mitkommen? / B: Ja, gern!","exzh":"A：我们今晚去酒吧，你想一起来吗？/ B：好啊！"},{"en":"Ja, gern!","zh":"好啊，乐意！","reg":"中性","ex":"A: Kommst du am Freitag zum Essen? / B: Ja, gern! Um wie viel Uhr?","exzh":"A：周五来吃饭吗？/ B：好啊！几点？"},{"en":"Da bin ich dabei!","zh":"算我一个！","reg":"随意","ex":"A: Wir spielen am Sonntag Badminton. / B: Da bin ich dabei!","exzh":"A：我们周日打羽毛球。/ B：算我一个！"},{"en":"Ich lade dich ein.","zh":"我请客。/ 我邀请你。","reg":"随意","ex":"A: Was bekommst du von mir? / B: Nichts, ich lade dich ein!","exzh":"A：我该给你多少钱？/ B：不用，我请你！"},{"en":"Leider kann ich nicht.","zh":"可惜我去不了。","reg":"中性","ex":"A: Kommst du morgen zur Party? / B: Leider kann ich nicht. Ich muss arbeiten.","exzh":"A：你明天来派对吗？/ B：可惜去不了，我得上班。"},{"en":"Vielleicht ein anderes Mal?","zh":"改天吧？","reg":"中性","ex":"A: Schade, dass du keine Zeit hast. / B: Ja, leider. Vielleicht ein anderes Mal?","exzh":"A：可惜你没空。/ B：是啊，改天吧？"},{"en":"Danke für die Einladung!","zh":"谢谢邀请！","reg":"中性","ex":"A: Wir würden Sie gern zu unserem Sommerfest einladen. / B: Danke für die Einladung! Ich komme gern.","exzh":"A：我们想邀请您参加夏日聚会。/ B：谢谢邀请！我很乐意去。"},{"en":"Ich schaue mal, ob ich Zeit habe.","zh":"我看看有没有空。（有时是委婉的拒绝）","reg":"随意","ex":"A: Kommst du am Freitag? / B: Ich schaue mal, ob ich Zeit habe, und sage dir Bescheid.","exzh":"A：你周五来吗？/ B：我看看有没有空，再告诉你。"},{"en":"Soll ich etwas mitbringen?","zh":"要我带点什么吗？","reg":"中性","ex":"A: Wir grillen am Samstag bei mir. / B: Super! Soll ich etwas mitbringen?","exzh":"A：周六在我家烧烤。/ B：太好了！要我带点什么吗？"}]},{"id":"termine","title":"📅 约时间","note":"德国做什么都要 Termin（预约），也很看重准时。时间：um + 钟点，am + 星期/日期。大坑：halb drei 是 2:30，不是 3:30！跟德国同事约会议记得时差：冬季吉隆坡比德国快 7 小时，夏令时期间快 6 小时。","items":[{"en":"Wann passt es Ihnen?","zh":"您什么时候方便？","reg":"正式","ex":"A: Ich würde gern einen Termin vereinbaren. / B: Gern. Wann passt es Ihnen?","exzh":"A：我想预约一个时间。/ B：好的，您什么时候方便？"},{"en":"Passt dir Dienstag?","zh":"周二你方便吗？","reg":"随意","ex":"A: Passt dir Dienstag? / B: Dienstag ist schlecht. Mittwoch geht.","exzh":"A：周二你方便吗？/ B：周二不行，周三可以。"},{"en":"Am Montag um 10 Uhr geht es bei mir.","zh":"周一十点我可以。","reg":"中性","ex":"A: Wann haben Sie Zeit? / B: Am Montag um 10 Uhr geht es bei mir.","exzh":"A：您什么时候有空？/ B：周一十点我可以。"},{"en":"Ich hätte gern einen Termin.","zh":"我想预约。","reg":"中性","ex":"A: Praxis Dr. Becker, guten Tag. / B: Guten Tag, ich hätte gern einen Termin.","exzh":"A：贝克尔医生诊所，您好。/ B：您好，我想预约。"},{"en":"Können wir den Termin verschieben?","zh":"我们能改个时间吗？","reg":"中性","ex":"Es tut mir leid, aber können wir den Termin auf nächste Woche verschieben?","exzh":"很抱歉，我们能把时间改到下周吗？"},{"en":"Um halb drei?","zh":"两点半？（halb drei = 2:30）","reg":"中性","ex":"A: Treffen wir uns um halb drei? / B: Also um 14:30 Uhr? Okay.","exzh":"A：我们两点半见？/ B：就是 14:30 对吧？好。"},{"en":"Da kann ich leider nicht.","zh":"那个时间我不行。","reg":"中性","ex":"A: Wie wäre es mit Donnerstag? / B: Da kann ich leider nicht. Ich habe schon einen Termin.","exzh":"A：周四怎么样？/ B：那天我不行，已经有约了。"},{"en":"Bei mir ist es dann schon 23 Uhr.","zh":"那时我这边已经晚上 11 点了。","reg":"中性","ex":"A: Können wir um 16 Uhr telefonieren? / B: Bei mir ist es dann schon 23 Uhr. Geht es auch am Vormittag?","exzh":"A：我们下午四点通个电话？/ B：那时我这边已经 11 点了。上午可以吗？"},{"en":"Ich schicke Ihnen eine Einladung.","zh":"我给您发个会议邀请。","reg":"正式","ex":"A: Dann also Donnerstag um 9 Uhr. / B: Perfekt, ich schicke Ihnen eine Einladung.","exzh":"A：那就周四九点。/ B：好的，我给您发个邀请。"}]},{"id":"telefon","title":"📞 打电话","note":"德国人接电话常直接报姓或公司名。打电话先说 Hier ist … / Mein Name ist …，再说来意 Ich rufe wegen … an（wegen + 属格，口语常用与格）。电话里说再见用 Auf Wiederhören，不是 Auf Wiedersehen。","items":[{"en":"Hallo, hier ist Ray.","zh":"喂，我是 Ray。","reg":"随意","ex":"A: Ja, hallo? / B: Hallo, hier ist Ray. Ist Lisa da?","exzh":"A：喂？/ B：喂，我是 Ray。Lisa 在吗？"},{"en":"Ich rufe wegen meiner Bestellung an.","zh":"我打电话是关于我的订单。","reg":"正式","ex":"Guten Tag, mein Name ist Ray. Ich rufe wegen meiner Bestellung an.","exzh":"您好，我叫 Ray，我打电话是想问一下我的订单。"},{"en":"Kann ich bitte mit Frau Schmidt sprechen?","zh":"请问施密特女士在吗？","reg":"正式","ex":"A: Firma Krause, guten Tag. / B: Guten Tag, kann ich bitte mit Frau Schmidt sprechen?","exzh":"A：克劳斯公司，您好。/ B：您好，请找施密特女士。"},{"en":"Einen Moment, bitte. Ich verbinde.","zh":"请稍等，我帮您转接。","reg":"正式","ex":"A: Kann ich bitte mit Herrn Wolf sprechen? / B: Einen Moment, bitte. Ich verbinde.","exzh":"A：请找沃尔夫先生。/ B：请稍等，我帮您转接。"},{"en":"Die Verbindung ist schlecht.","zh":"信号不好。","reg":"中性","ex":"Entschuldigung, die Verbindung ist schlecht. Können Sie das wiederholen?","exzh":"不好意思，信号不好，您能再说一遍吗？"},{"en":"Kann ich eine Nachricht hinterlassen?","zh":"我可以留个言吗？","reg":"中性","ex":"A: Herr Wolf ist leider nicht im Büro. / B: Kann ich eine Nachricht hinterlassen?","exzh":"A：沃尔夫先生不在办公室。/ B：我可以留个言吗？"},{"en":"Ich rufe später noch mal an.","zh":"我晚点再打。","reg":"中性","ex":"A: Sie ist gerade in einem Meeting. / B: Okay, dann rufe ich später noch mal an.","exzh":"A：她正在开会。/ B：好，那我晚点再打。"},{"en":"Können Sie das bitte buchstabieren?","zh":"您能拼一下吗？","reg":"中性","ex":"A: Mein Name ist Pfeiffer. / B: Können Sie das bitte buchstabieren?","exzh":"A：我姓 Pfeiffer。/ B：您能拼一下吗？"},{"en":"Auf Wiederhören!","zh":"再见！（电话专用）","reg":"正式","ex":"A: Vielen Dank, Sie hören von uns. / B: Danke, auf Wiederhören!","exzh":"A：非常感谢，我们会联系您。/ B：谢谢，再见！"}]},{"id":"meeting","title":"💻 开会和视频会议","note":"德国的 IT 团队里同事之间多用 du，对客户和高层用 Sie。会议一般准时开始。IT 圈常夹英语词（Feature、Bug、deployen、Release），这很正常。","items":[{"en":"Könnt ihr mich hören?","zh":"大家能听到我吗？（ihr = 你们）","reg":"随意","ex":"A: Könnt ihr mich hören? / B: Ja, laut und deutlich.","exzh":"A：大家能听到我吗？/ B：能，很清楚。"},{"en":"Du bist noch stummgeschaltet.","zh":"你还在静音。","reg":"随意","ex":"A: Hört ihr mich? Hallo? / B: Jetzt ja! Du warst noch stummgeschaltet.","exzh":"A：听得到吗？喂？/ B：现在听到了！你刚才还静着音。"},{"en":"Ich teile mal meinen Bildschirm.","zh":"我共享一下屏幕。","reg":"中性","ex":"Ich teile mal meinen Bildschirm. Seht ihr jetzt den Code?","exzh":"我共享一下屏幕。现在能看到代码吗？"},{"en":"Kurzes Update von mir:","zh":"我简单汇报一下：","reg":"中性","ex":"Kurzes Update von mir: Das Login-Feature ist fertig, heute schreibe ich die Tests.","exzh":"我简单汇报一下：登录功能做完了，今天写测试。"},{"en":"Ich habe eine Frage dazu.","zh":"关于这个我有个问题。","reg":"中性","ex":"Ich habe eine Frage dazu: Wer ist für das Deployment verantwortlich?","exzh":"我有个问题：谁负责部署？"},{"en":"Darf ich kurz etwas ergänzen?","zh":"我可以补充一点吗？","reg":"正式","ex":"Darf ich kurz etwas ergänzen? Wir müssen auch an die Datenbank denken.","exzh":"我补充一点：我们也得考虑数据库。"},{"en":"Lass uns das nach dem Meeting klären.","zh":"这个会后再说吧。","reg":"中性","ex":"A: Das API-Problem ist ziemlich kompliziert. / B: Lass uns das nach dem Meeting klären.","exzh":"A：这个 API 问题挺复杂的。/ B：我们会后再说吧。"},{"en":"Wer übernimmt das?","zh":"谁来负责这个？","reg":"中性","ex":"A: Wir müssen noch die Dokumentation aktualisieren. Wer übernimmt das? / B: Das mache ich.","exzh":"A：文档还要更新，谁来做？/ B：我来。"},{"en":"Zurück zum Thema.","zh":"回到正题。","reg":"中性","ex":"Okay, zurück zum Thema: Was machen wir mit dem Bug?","exzh":"好，回到正题：这个 bug 怎么办？"},{"en":"Können wir kurz zusammenfassen?","zh":"我们能简单总结一下吗？","reg":"正式","ex":"Können wir kurz zusammenfassen, was wir heute entschieden haben?","exzh":"我们能简单总结一下今天决定了什么吗？"},{"en":"Ich muss leider etwas früher los.","zh":"不好意思，我得早点走。","reg":"随意","ex":"Sorry, ich muss leider etwas früher los. Ich habe noch einen Termin.","exzh":"抱歉，我得早点走，还有个约。"}]},{"id":"gefuehle","title":"😊 表达感受","note":"多数感受用 Ich bin + 形容词（müde, froh, gestresst）。但冷热要用与格：Mir ist kalt / Mir ist heiß。千万别说 Ich bin heiß，听起来有性暗示！","items":[{"en":"Ich freue mich schon!","zh":"我已经很期待了！","reg":"中性","ex":"A: Nächste Woche kommst du nach Berlin, oder? / B: Ja, ich freue mich schon!","exzh":"A：你下周来柏林对吧？/ B：对，我已经很期待了！"},{"en":"Ich bin total müde.","zh":"我累死了。","reg":"随意","ex":"A: Du siehst müde aus. / B: Ja, ich bin total müde. Ich habe nur vier Stunden geschlafen.","exzh":"A：你看起来很累。/ B：是啊，累死了，只睡了四个小时。"},{"en":"Mir ist heiß.","zh":"我好热。（不能说 Ich bin heiß）","reg":"中性","ex":"A: Mir ist so heiß! / B: Willkommen in Kuala Lumpur!","exzh":"A：我好热！/ B：欢迎来到吉隆坡！"},{"en":"Mir ist kalt.","zh":"我好冷。","reg":"中性","ex":"A: Mir ist kalt. / B: Kein Wunder, die Klimaanlage läuft auf 18 Grad.","exzh":"A：我好冷。/ B：难怪，空调开到 18 度了。"},{"en":"Ich bin gerade ziemlich gestresst.","zh":"我最近压力挺大的。","reg":"中性","ex":"A: Alles okay? / B: Na ja, ich bin gerade ziemlich gestresst. Wir haben bald ein Release.","exzh":"A：你还好吗？/ B：嗯，最近压力挺大，马上要发版了。"},{"en":"Ich habe ein bisschen Angst davor.","zh":"我有点害怕（这件事）。","reg":"中性","ex":"A: Wann ist deine Deutschprüfung? / B: Nächsten Monat. Ich habe ein bisschen Angst davor.","exzh":"A：你的德语考试什么时候？/ B：下个月，我有点怕。"},{"en":"Das nervt!","zh":"好烦！","reg":"随意","ex":"A: Das WLAN ist schon wieder weg. / B: Echt? Das nervt!","exzh":"A：Wi-Fi 又断了。/ B：真的？好烦！"},{"en":"Ich bin so froh, dass …","zh":"我很高兴……","reg":"中性","ex":"Ich bin so froh, dass das Projekt endlich fertig ist.","exzh":"项目终于做完了，我太高兴了。"},{"en":"Ich vermisse meine Familie.","zh":"我想念家人。","reg":"中性","ex":"A: Fährst du zum chinesischen Neujahr nach Hause? / B: Ja, ich vermisse meine Familie sehr.","exzh":"A：春节你回家吗？/ B：回，我很想家人。"},{"en":"Ich bin echt enttäuscht.","zh":"我真的很失望。","reg":"中性","ex":"A: Das Konzert wurde abgesagt. / B: Oh nein, ich bin echt enttäuscht.","exzh":"A：演唱会取消了。/ B：哦不，我真失望。"},{"en":"Mir geht's heute nicht so gut.","zh":"我今天不太舒服。/ 状态不太好。","reg":"随意","ex":"A: Was ist los? / B: Mir geht's heute nicht so gut. Ich glaube, ich werde krank.","exzh":"A：怎么了？/ B：我今天不太舒服，好像要生病了。"}]},{"id":"smalltalk","title":"☕ 闲聊","note":"德国人的闲聊话题：周末、天气、度假、吃的。工资、政治、宗教一般不聊。和德国同事视频时，问问那边天气、说说吉隆坡的生活都是好话题。","items":[{"en":"Wie war dein Wochenende?","zh":"你周末过得怎么样？","reg":"随意","ex":"A: Wie war dein Wochenende? / B: Sehr entspannt. Ich war einfach zu Hause.","exzh":"A：你周末过得怎么样？/ B：很放松，就待在家。"},{"en":"Was hast du am Wochenende vor?","zh":"你周末有什么打算？","reg":"随意","ex":"A: Was hast du am Wochenende vor? / B: Ich gehe mit Freunden essen.","exzh":"A：你周末打算干嘛？/ B：和朋友出去吃饭。"},{"en":"Schönes Wetter heute, oder?","zh":"今天天气真好，是吧？","reg":"中性","ex":"A: Schönes Wetter heute, oder? / B: Ja, endlich mal Sonne!","exzh":"A：今天天气真好，是吧？/ B：是啊，终于出太阳了！"},{"en":"Wie ist das Wetter bei dir?","zh":"你那边天气怎么样？","reg":"随意","ex":"A: Wie ist das Wetter bei dir in Kuala Lumpur? / B: Heiß und feucht, wie immer. Und am Nachmittag regnet es oft.","exzh":"A：吉隆坡那边天气怎么样？/ B：又热又潮，老样子。下午还经常下雨。"},{"en":"Warst du schon mal in Asien?","zh":"你去过亚洲吗？","reg":"随意","ex":"A: Warst du schon mal in Asien? / B: Ja, in Thailand. Aber noch nie in Malaysia.","exzh":"A：你去过亚洲吗？/ B：去过泰国，但还没去过马来西亚。"},{"en":"Was machst du in deiner Freizeit?","zh":"你业余时间做什么？","reg":"随意","ex":"A: Was machst du in deiner Freizeit? / B: Ich koche gern und gehe joggen.","exzh":"A：你业余时间做什么？/ B：我喜欢做饭，还去跑步。"},{"en":"Wie lange wohnst du schon hier?","zh":"你在这儿住多久了？","reg":"随意","ex":"A: Wie lange wohnst du schon in Kuala Lumpur? / B: Seit zwei Jahren.","exzh":"A：你在吉隆坡住多久了？/ B：两年了。"},{"en":"Hast du schon Pläne für den Urlaub?","zh":"你假期有计划了吗？","reg":"随意","ex":"A: Hast du schon Pläne für den Urlaub? / B: Ich fliege vielleicht nach Penang.","exzh":"A：假期有计划了吗？/ B：可能飞去槟城。"},{"en":"Was gefällt dir hier am besten?","zh":"你最喜欢这里的什么？","reg":"随意","ex":"A: Was gefällt dir an Malaysia am besten? / B: Das Essen! Nasi Lemak, Roti Canai … einfach super.","exzh":"A：你最喜欢马来西亚哪一点？/ B：吃的！椰浆饭、印度煎饼……太棒了。"},{"en":"Erzähl mal!","zh":"说来听听！","reg":"随意","ex":"A: Ich war letzte Woche in Langkawi. / B: Oh, schön! Erzähl mal!","exzh":"A：我上周去了兰卡威。/ B：哦，真好！说来听听！"}]},{"id":"hilfe","title":"🆘 求助","note":"向陌生人求助先说 Entschuldigung，再用 Können Sie mir helfen?。Wissen Sie, wo … ist? 是间接问句，动词放最后。德国急救和消防电话是 112，报警是 110。","items":[{"en":"Können Sie mir bitte helfen?","zh":"您能帮帮我吗？","reg":"中性","ex":"A: Entschuldigung, können Sie mir bitte helfen? Ich finde den Bahnsteig nicht. / B: Klar, welchen suchen Sie?","exzh":"A：不好意思，您能帮我一下吗？我找不到站台。/ B：当然，您找哪个站台？"},{"en":"Kannst du mir kurz helfen?","zh":"你能帮我一下吗？","reg":"随意","ex":"A: Kannst du mir kurz helfen? Mein Docker-Container startet nicht. / B: Klar, zeig mal.","exzh":"A：能帮我一下吗？我的 Docker 容器起不来。/ B：行，给我看看。"},{"en":"Ich habe mich verlaufen.","zh":"我迷路了。（步行时）","reg":"中性","ex":"A: Entschuldigung, ich habe mich verlaufen. Wo ist der Bahnhof? / B: Gehen Sie hier geradeaus und dann links.","exzh":"A：不好意思，我迷路了，火车站在哪儿？/ B：一直往前走，然后左转。"},{"en":"Ich habe ein Problem mit meinem Konto.","zh":"我的账户有问题。","reg":"中性","ex":"Ich habe ein Problem mit meinem Konto. Ich kann mich nicht einloggen.","exzh":"我的账户有问题，登录不了。"},{"en":"Wissen Sie, wo die nächste Apotheke ist?","zh":"您知道最近的药店在哪儿吗？（动词放句末）","reg":"中性","ex":"A: Wissen Sie, wo die nächste Apotheke ist? / B: Ja, gleich da vorne an der Ecke.","exzh":"A：您知道最近的药店在哪儿吗？/ B：知道，就在前面拐角。"},{"en":"Wir brauchen einen Arzt!","zh":"我们需要医生！","reg":"中性","ex":"A: Was ist passiert? / B: Mein Freund ist gestürzt. Wir brauchen einen Arzt!","exzh":"A：怎么了？/ B：我朋友摔倒了，我们需要医生！"},{"en":"Hilfe!","zh":"救命！","reg":"中性","ex":"Hilfe! Rufen Sie bitte einen Krankenwagen!","exzh":"救命！请叫救护车！"},{"en":"Ich habe mein Portemonnaie verloren.","zh":"我的钱包丢了。","reg":"中性","ex":"A: Ich habe mein Portemonnaie verloren. / B: Oh nein! Gehen Sie am besten zum Fundbüro.","exzh":"A：我的钱包丢了。/ B：哦不！您最好去失物招领处。"},{"en":"Wie funktioniert das?","zh":"这个怎么用？","reg":"中性","ex":"A: Wie funktioniert dieser Fahrkartenautomat? / B: Zuerst wählen Sie das Ziel, dann bezahlen Sie.","exzh":"A：这台售票机怎么用？/ B：先选目的地，再付款。"},{"en":"Könnten Sie mir zeigen, wie das geht?","zh":"您能演示一下怎么弄吗？","reg":"正式","ex":"Ich bin neu hier. Könnten Sie mir zeigen, wie das System funktioniert?","exzh":"我是新来的，您能给我演示一下这个系统怎么用吗？"}]},{"id":"beschwerde","title":"😤 投诉和提意见","note":"投诉时冷静、具体：Leider … + 问题 + 你想要的结果。德国很讲规矩，比如晚上 22 点后一般要保持安静（Nachtruhe），可以礼貌地提醒邻居。","items":[{"en":"Entschuldigung, das habe ich nicht bestellt.","zh":"不好意思，这不是我点的。","reg":"中性","ex":"A: Hier ist Ihr Schnitzel. / B: Entschuldigung, das habe ich nicht bestellt. Ich hatte die Suppe.","exzh":"A：这是您的炸肉排。/ B：不好意思，这不是我点的，我点的是汤。"},{"en":"Leider ist das Essen kalt.","zh":"可惜饭菜是凉的。","reg":"中性","ex":"A: Ist alles in Ordnung? / B: Leider nicht. Das Essen ist kalt.","exzh":"A：一切都还好吗？/ B：不太好，饭菜是凉的。"},{"en":"Die Heizung funktioniert nicht.","zh":"暖气坏了。","reg":"中性","ex":"Guten Tag, Herr Lange, in meiner Wohnung funktioniert die Heizung nicht.","exzh":"您好，朗格先生，我公寓的暖气坏了。"},{"en":"Ich möchte mich beschweren.","zh":"我想投诉。","reg":"正式","ex":"Ich möchte mich beschweren. Ich warte seit zwei Wochen auf mein Paket.","exzh":"我想投诉，我的包裹等了两周了。"},{"en":"Das ist nicht in Ordnung.","zh":"这样不对。/ 这不合理。","reg":"中性","ex":"A: Die Reparatur kostet 300 Euro extra. / B: Das ist nicht in Ordnung. Das war so nicht vereinbart.","exzh":"A：维修要额外 300 欧。/ B：这不合理，当初不是这么说好的。"},{"en":"Können Sie das bitte überprüfen?","zh":"您能核实一下吗？","reg":"正式","ex":"Auf der Rechnung steht zweimal derselbe Betrag. Können Sie das bitte überprüfen?","exzh":"账单上同一笔钱出现了两次，您能核实一下吗？"},{"en":"Ich hätte gern mein Geld zurück.","zh":"我想退款。","reg":"中性","ex":"A: Die Kopfhörer sind kaputt. Ich hätte gern mein Geld zurück. / B: Haben Sie den Kassenbon dabei?","exzh":"A：耳机坏了，我想退款。/ B：您带收据了吗？"},{"en":"Wir warten schon seit 40 Minuten.","zh":"我们已经等了 40 分钟了。","reg":"中性","ex":"Entschuldigung, wir warten schon seit 40 Minuten auf unser Essen.","exzh":"不好意思，我们的菜已经等了 40 分钟了。"},{"en":"Könnten Sie bitte etwas leiser sein?","zh":"您能小声一点吗？","reg":"中性","ex":"Entschuldigung, könnten Sie bitte etwas leiser sein? Es ist schon nach 22 Uhr.","exzh":"不好意思，您能小声一点吗？已经过了晚上十点了。"}]},{"id":"wuensche","title":"🛍 表达愿望（点餐购物）","note":"点餐购物用 Ich hätte gern … / Ich möchte … 最礼貌。Ich will … 很直接，跟朋友说没问题，对店员说会显得有点冲。Ich würde gern … 用来说想做的事。","items":[{"en":"Ich hätte gern einen Cappuccino.","zh":"我要一杯卡布奇诺。","reg":"中性","ex":"A: Was darf es sein? / B: Ich hätte gern einen Cappuccino, bitte.","exzh":"A：您要点什么？/ B：我要一杯卡布奇诺。"},{"en":"Ich möchte bitte zahlen.","zh":"我想买单。","reg":"中性","ex":"A: Ich möchte bitte zahlen. / B: Zusammen oder getrennt?","exzh":"A：我想买单。/ B：一起付还是分开付？"},{"en":"Ich nehme die Nummer 12.","zh":"我要 12 号。","reg":"中性","ex":"A: Haben Sie schon gewählt? / B: Ja, ich nehme die Nummer 12.","exzh":"A：您选好了吗？/ B：选好了，我要 12 号。"},{"en":"Für mich bitte ein stilles Wasser.","zh":"给我一瓶不带气的水。","reg":"中性","ex":"A: Und was möchten Sie trinken? / B: Für mich bitte ein stilles Wasser.","exzh":"A：您喝点什么？/ B：给我一瓶不带气的水。"},{"en":"Haben Sie das auch in Größe M?","zh":"这个有 M 码吗？","reg":"中性","ex":"A: Haben Sie das auch in Größe M? / B: Moment, ich schaue mal nach.","exzh":"A：这个有 M 码吗？/ B：稍等，我去看看。"},{"en":"Ich hätte lieber einen Platz am Fenster.","zh":"我更想要靠窗的位子。","reg":"中性","ex":"A: Möchten Sie hier sitzen? / B: Ich hätte lieber einen Platz am Fenster, wenn das geht.","exzh":"A：您坐这里可以吗？/ B：如果可以的话，我更想要靠窗的位子。"},{"en":"Zum Mitnehmen, bitte.","zh":"打包带走。","reg":"中性","ex":"A: Für hier oder zum Mitnehmen? / B: Zum Mitnehmen, bitte.","exzh":"A：在这儿吃还是带走？/ B：带走。"},{"en":"Ich würde gern mal nach Deutschland fliegen.","zh":"我很想去一趟德国。","reg":"中性","ex":"A: Warst du schon mal in Deutschland? / B: Noch nicht, aber ich würde gern mal hinfliegen.","exzh":"A：你去过德国吗？/ B：还没有，不过很想去一趟。"},{"en":"Ich will unbedingt Pizza!","zh":"我就想吃披萨！（对朋友）","reg":"随意","ex":"A: Was willst du heute Abend essen? / B: Ich will unbedingt Pizza!","exzh":"A：今晚想吃什么？/ B：我就想吃披萨！"}]},{"id":"zeit_gewinnen","title":"⏳ 争取思考时间（填充词）","note":"一时想不出词别沉默，用这些词撑一下，听起来更像母语者。äh / ähm 也完全正常。注意 Moment mal 语气重一点时是「等一下，不对吧」，表示异议。","items":[{"en":"Also …","zh":"嗯……那个……（开头整理思路）","reg":"随意","ex":"A: Was hast du gestern gemacht? / B: Also … zuerst war ich im Büro, dann im Fitnessstudio.","exzh":"A：你昨天干嘛了？/ B：嗯……先去了办公室，然后去了健身房。"},{"en":"Na ja …","zh":"嗯……还行吧（犹豫、不太满意）","reg":"随意","ex":"A: Wie war der Film? / B: Na ja … ganz okay.","exzh":"A：电影怎么样？/ B：嗯……还行吧。"},{"en":"Moment mal …","zh":"等一下……","reg":"随意","ex":"A: Wie ist deine Adresse? / B: Moment mal, ich muss kurz nachsehen.","exzh":"A：你的地址是什么？/ B：等一下，我查一下。"},{"en":"Lass mich kurz überlegen.","zh":"让我想一想。","reg":"随意","ex":"A: Was ist dein Lieblingsessen? / B: Hm, lass mich kurz überlegen …","exzh":"A：你最喜欢吃什么？/ B：嗯，让我想想……"},{"en":"Wie sagt man das noch mal?","zh":"那个怎么说来着？","reg":"随意","ex":"Ich brauche … wie sagt man das noch mal … einen Adapter für die Steckdose.","exzh":"我需要一个……那个怎么说来着……插座转换头。"},{"en":"Gute Frage!","zh":"好问题！","reg":"中性","ex":"A: Warum lernst du eigentlich Deutsch? / B: Gute Frage! Also, ich arbeite viel mit deutschen Kollegen …","exzh":"A：你为什么学德语？/ B：好问题！嗯，我经常和德国同事一起工作……"},{"en":"Wie soll ich sagen …","zh":"怎么说呢……","reg":"随意","ex":"Das Projekt ist, wie soll ich sagen, ein bisschen chaotisch.","exzh":"这个项目，怎么说呢，有点乱。"},{"en":"Ich meine …","zh":"我是说……（修正或解释）","reg":"随意","ex":"Das ist teuer. Ich meine, nicht zu teuer, aber teurer als in Malaysia.","exzh":"这挺贵的。我是说，不算太贵，但比马来西亚贵。"},{"en":"Eigentlich …","zh":"其实……","reg":"中性","ex":"A: Hast du Hunger? / B: Eigentlich nicht, ich habe gerade gegessen.","exzh":"A：你饿吗？/ B：其实不饿，我刚吃过。"},{"en":"Sagen wir mal …","zh":"就说……吧 / 大概……（估算时）","reg":"随意","ex":"A: Wie viel Zeit brauchst du? / B: Sagen wir mal … zwei Tage.","exzh":"A：你需要多长时间？/ B：就说……两天吧。"},{"en":"Wie gesagt, …","zh":"就像我说的……","reg":"中性","ex":"Wie gesagt, ich bin am Freitag nicht da.","exzh":"就像我说的，我周五不在。"}]},{"id":"ueberraschung","title":"😲 表示惊讶和反应","note":"别人说话时及时给反应，对话才自然。Ach so 是「原来如此」，德国人用得极多；Echt? / Im Ernst? 是「真的？」。","items":[{"en":"Echt?","zh":"真的？","reg":"随意","ex":"A: Ich ziehe nach München. / B: Echt? Seit wann weißt du das?","exzh":"A：我要搬去慕尼黑了。/ B：真的？你什么时候知道的？"},{"en":"Wirklich?","zh":"真的吗？","reg":"中性","ex":"A: In Malaysia gibt es keinen Winter. / B: Wirklich? Das ist ja toll!","exzh":"A：马来西亚没有冬天。/ B：真的吗？太棒了！"},{"en":"Ach so!","zh":"原来如此！/ 哦，这样啊！","reg":"中性","ex":"A: Die Geschäfte sind sonntags geschlossen. / B: Ach so! Das wusste ich nicht.","exzh":"A：商店周日不开门。/ B：原来如此！我不知道。"},{"en":"Das gibt's doch nicht!","zh":"不会吧！/ 怎么可能！","reg":"随意","ex":"A: Mein Laptop ist schon wieder abgestürzt. / B: Das gibt's doch nicht!","exzh":"A：我的电脑又死机了。/ B：不会吧！"},{"en":"Wahnsinn!","zh":"太厉害了！/ 太疯狂了！","reg":"随意","ex":"A: Ich habe die B1-Prüfung bestanden! / B: Wahnsinn! Herzlichen Glückwunsch!","exzh":"A：我通过 B1 考试了！/ B：太厉害了！恭喜！"},{"en":"Ach du meine Güte!","zh":"我的天哪！","reg":"中性","ex":"A: Ich habe meinen Pass im Taxi vergessen. / B: Ach du meine Güte! Ruf sofort die Taxifirma an!","exzh":"A：我把护照忘在出租车上了。/ B：天哪！马上给出租车公司打电话！"},{"en":"Oh nein!","zh":"哦不！","reg":"中性","ex":"A: Der Flug hat drei Stunden Verspätung. / B: Oh nein!","exzh":"A：航班晚点三个小时。/ B：哦不！"},{"en":"Das ist ja interessant!","zh":"这真有意思！","reg":"中性","ex":"A: In Malaysia spricht man Malaiisch, Englisch, Chinesisch und Tamil. / B: Das ist ja interessant!","exzh":"A：马来西亚人说马来语、英语、华语和泰米尔语。/ B：这真有意思！"},{"en":"Im Ernst?","zh":"你认真的？/ 真的假的？","reg":"随意","ex":"A: Ein Bier kostet hier 15 Euro. / B: Im Ernst?","exzh":"A：这里一杯啤酒 15 欧。/ B：真的假的？"},{"en":"Nicht schlecht!","zh":"不错嘛！/ 挺厉害！","reg":"中性","ex":"A: Ich bin letzte Woche meinen ersten Halbmarathon gelaufen. / B: Nicht schlecht!","exzh":"A：我上周跑了第一个半马。/ B：不错嘛！"}]},{"id":"gespraech_beenden","title":"🚪 结束对话","note":"想结束聊天时，德国人常说 Ich muss dann mal los。别直接走，加一句祝福（Schönes Wochenende!）或约下次（Wir hören uns!）更自然。","items":[{"en":"Ich muss dann mal los.","zh":"那我先走了。","reg":"随意","ex":"A: Oh, schon so spät! Ich muss dann mal los. / B: Okay, bis bald!","exzh":"A：哦，这么晚了！我得走了。/ B：好，回头见！"},{"en":"Es war schön, mit dir zu reden.","zh":"和你聊天很开心。","reg":"随意","ex":"A: Es war schön, mit dir zu reden. / B: Fand ich auch! Bis bald.","exzh":"A：和你聊天很开心。/ B：我也是！回头见。"},{"en":"Es hat mich gefreut, Sie kennenzulernen.","zh":"很高兴认识您。（告别时）","reg":"正式","ex":"A: Es hat mich gefreut, Sie kennenzulernen. / B: Ganz meinerseits. Auf Wiedersehen!","exzh":"A：很高兴认识您。/ B：我也是。再见！"},{"en":"Wir hören uns!","zh":"保持联系！/ 回头再聊！","reg":"随意","ex":"A: Ich schicke dir morgen die Unterlagen. / B: Super, wir hören uns!","exzh":"A：我明天把资料发给你。/ B：好，回头聊！"},{"en":"Lass uns in Kontakt bleiben.","zh":"我们保持联系吧。","reg":"随意","ex":"A: Lass uns in Kontakt bleiben! / B: Auf jeden Fall. Schreib mir einfach auf WhatsApp.","exzh":"A：我们保持联系吧！/ B：一定，直接在 WhatsApp 上找我。"},{"en":"Ich will dich nicht länger aufhalten.","zh":"不耽误你了。","reg":"随意","ex":"Ich will dich nicht länger aufhalten. Viel Erfolg bei deiner Präsentation!","exzh":"不耽误你了，祝你演讲顺利！"},{"en":"Grüß Anna von mir!","zh":"替我向 Anna 问好！","reg":"随意","ex":"A: Tschüss, Ray! / B: Tschüss! Und grüß Anna von mir!","exzh":"A：拜拜，Ray！/ B：拜拜！替我向 Anna 问好！"},{"en":"Schönes Wochenende!","zh":"周末愉快！","reg":"中性","ex":"A: Schönes Wochenende! / B: Danke, dir auch!","exzh":"A：周末愉快！/ B：谢谢，你也是！"},{"en":"Melde dich, wenn du Fragen hast.","zh":"有问题就找我。","reg":"随意","ex":"A: Danke für die Erklärung! / B: Gerne. Melde dich, wenn du noch Fragen hast.","exzh":"A：谢谢你的讲解！/ B：不客气，还有问题就找我。"},{"en":"Bis zum nächsten Mal!","zh":"下次见！","reg":"中性","ex":"A: Danke für das tolle Gespräch. / B: Ich danke Ihnen. Bis zum nächsten Mal!","exzh":"A：谢谢这次愉快的交谈。/ B：我也谢谢您，下次见！"}]}],"slang":[{"id":"umgangssprache","title":"🍻 朋友之间的口语","note":"这些是德国人和朋友、同龄人之间天天说的口语。对陌生人、客户、上司用就显得太随便，先听懂、跟熟人用。","items":[{"en":"Na?","zh":"嗨，怎么样？（熟人见面打招呼，回一句 Na? 也行）","reg":"随意","ex":"A: Na, Ray? / B: Na? Alles gut bei dir?","exzh":"A：嗨，Ray！/ B：嗨！你一切都好吧？"},{"en":"Alles klar!","zh":"好的！/ 明白！（也可当问候：Alles klar?）","reg":"随意","ex":"A: Wir treffen uns um acht vor dem Kino. / B: Alles klar, bis dann!","exzh":"A：我们八点在电影院门口见。/ B：好嘞，到时见！"},{"en":"Bock haben (auf)","zh":"想（干某事）/ 有兴致；keinen Bock = 不想干","reg":"随意","ex":"A: Hast du Bock auf Kino heute? / B: Nee, keinen Bock. Ich bin zu müde.","exzh":"A：今天想去看电影吗？/ B：不想去，太累了。"},{"en":"Krass!","zh":"太夸张了！/ 太厉害了！（褒贬都可以）","reg":"随意","ex":"A: Ich habe in einem Jahr zehn Kilo abgenommen. / B: Krass! Wie hast du das gemacht?","exzh":"A：我一年瘦了十公斤。/ B：太夸张了！你怎么做到的？"},{"en":"Quatsch!","zh":"胡说！/ 瞎扯！（朋友间反驳，不算骂人）","reg":"随意","ex":"A: Mein Deutsch ist so schlecht. / B: Quatsch! Du sprichst schon richtig gut.","exzh":"A：我德语好差。/ B：瞎说！你已经说得很好了。"},{"en":"Egal.","zh":"无所谓。（Das ist mir egal 语气重时显得冷淡）","reg":"随意","ex":"A: Willst du Pizza oder Pasta? / B: Egal, ich habe einfach Hunger.","exzh":"A：你要披萨还是意面？/ B：无所谓，我就是饿了。"},{"en":"Nee.","zh":"不。（nein 的口语）","reg":"随意","ex":"A: Kommst du mit? / B: Nee, heute nicht.","exzh":"A：一起去吗？/ B：不了，今天不去。"},{"en":"Kein Ding!","zh":"小事一桩！/ 不客气！","reg":"随意","ex":"A: Danke, dass du mir beim Umzug geholfen hast! / B: Kein Ding!","exzh":"A：谢谢你帮我搬家！/ B：小事一桩！"},{"en":"Passt schon.","zh":"没事，行了。/ 还凑合。","reg":"随意","ex":"A: Sorry, ich bin ein bisschen spät. / B: Passt schon.","exzh":"A：抱歉，我晚了一点。/ B：没事。"},{"en":"Ich bin pleite.","zh":"我没钱了。/ 我破产了。（口语夸张）","reg":"随意","ex":"A: Gehen wir am Wochenende feiern? / B: Ich kann nicht, ich bin total pleite.","exzh":"A：周末去玩吗？/ B：去不了，我穷光蛋了。"},{"en":"Mist!","zh":"糟了！/ 该死！（温和的抱怨，不算脏话）","reg":"随意","ex":"Mist! Ich habe meinen Schlüssel in der Wohnung vergessen.","exzh":"糟了！我把钥匙忘在屋里了。"},{"en":"Mach's gut!","zh":"保重！/ 再见！","reg":"随意","ex":"A: Ich fliege morgen zurück nach Kuala Lumpur. / B: Mach's gut! Und melde dich mal!","exzh":"A：我明天飞回吉隆坡。/ B：保重！记得联系！"}]},{"id":"modalpartikeln","title":"🧂 语气小词（doch, mal, halt …）","note":"这些 Modalpartikeln 没有固定的中文翻译，作用是调整语气：缓和、强调、表示理所当然或无奈。它们一般放在句子中间、动词后面，不重读。德国人说话离不开它们，用对了会非常地道。","items":[{"en":"Doch!","zh":"不，是的！（反驳否定的问题或说法；回答否定问句时不能用 Ja。这里的 Doch 是应答词，要重读，和句中不重读的语气词 doch 不同）","reg":"中性","ex":"A: Du hast keine Zeit, oder? / B: Doch, ich habe Zeit!","exzh":"A：你没空吧？/ B：不，我有空！"},{"en":"Komm doch mit!","zh":"一起来嘛！（祈使句里的 doch 让邀请更热情、带点劝说）","reg":"随意","ex":"A: Ich weiß nicht, ob ich mitkommen soll. / B: Komm doch mit! Das wird lustig.","exzh":"A：我不知道要不要一起去。/ B：一起来嘛！会很好玩的。"},{"en":"Kannst du mal kurz schauen?","zh":"你能帮我看一下吗？（mal 让请求显得轻松、不麻烦）","reg":"随意","ex":"A: Kannst du mal kurz auf meinen Code schauen? / B: Klar, schick mir den Link.","exzh":"A：你能帮我看一下代码吗？/ B：行，把链接发我。"},{"en":"Das ist halt so.","zh":"就是这样，没办法。（halt 表示无奈接受事实）","reg":"随意","ex":"A: Warum regnet es hier fast jeden Nachmittag? / B: Das ist halt so in den Tropen.","exzh":"A：这里为什么几乎每天下午下雨？/ B：热带就是这样，没办法。"},{"en":"Dann machen wir es eben morgen.","zh":"那就明天做呗。（eben 和 halt 类似，表示「只能这样」）","reg":"中性","ex":"A: Heute schaffen wir das nicht mehr. / B: Dann machen wir es eben morgen.","exzh":"A：今天做不完了。/ B：那就明天做呗。"},{"en":"Das ist ja super!","zh":"这也太棒了吧！（ja 表示惊讶，不是「是」）","reg":"中性","ex":"A: Ich habe die Wohnung bekommen! / B: Das ist ja super!","exzh":"A：我租到那套房子了！/ B：太棒了吧！"},{"en":"Du weißt ja, …","zh":"你也知道……（ja 表示「这是我们都知道的事」）","reg":"中性","ex":"Du weißt ja, ich trinke keinen Alkohol.","exzh":"你也知道，我不喝酒。"},{"en":"Das schaffst du schon!","zh":"你肯定没问题的！（schon 表示安慰、相信结果会好）","reg":"中性","ex":"A: Ich habe morgen meine Prüfung. / B: Keine Sorge, das schaffst du schon!","exzh":"A：我明天考试。/ B：别担心，你肯定没问题！"},{"en":"Ja, schon, aber …","zh":"是倒是，不过……（schon 表示让步）","reg":"中性","ex":"A: Berlin ist doch toll! / B: Ja, schon, aber im Winter ist es mir zu kalt.","exzh":"A：柏林多好啊！/ B：是倒是，不过冬天对我来说太冷了。"},{"en":"Was machst du denn hier?","zh":"你怎么在这儿？（问句里的 denn 表示好奇、语气更自然，不是「因为」）","reg":"中性","ex":"A: Ray! Was machst du denn hier? / B: Ich hole nur schnell einen Kaffee.","exzh":"A：Ray！你怎么在这儿？/ B：我就来买杯咖啡。"},{"en":"Wie heißt du eigentlich?","zh":"话说你叫什么来着？（问句里的 eigentlich = 顺便问一下）","reg":"中性","ex":"A: Wir reden schon so lange … wie heißt du eigentlich? / B: Haha, ich bin Ray!","exzh":"A：我们聊了这么久……话说你叫什么？/ B：哈哈，我是 Ray！"},{"en":"Der ist wohl kaputt.","zh":"这个大概是坏了。（wohl 表示推测）","reg":"中性","ex":"A: Der Drucker druckt nicht. / B: Der ist wohl kaputt.","exzh":"A：打印机打不出来。/ B：大概是坏了。"}]},{"id":"jugendsprache","title":"🔥 年轻人用语 / 网络用语（非常随意）","note":"⚠️ 非常随意！只在很熟的同龄朋友之间或聊天软件里用，对同事、长辈、陌生人千万别用，先听懂就好。这类词变化快，有的过两年就过时了（lost、cringe 都曾当选德国「年度青少年用语」）。","items":[{"en":"mega","zh":"超级，特别（mega gut = 超好）","reg":"随意","ex":"Das Konzert gestern war mega gut!","exzh":"昨天的演唱会超好看！"},{"en":"Safe!","zh":"肯定！/ 绝对！（= sicher）","reg":"随意","ex":"A: Kommst du heute Abend? / B: Safe!","exzh":"A：你今晚来吗？/ B：肯定来！"},{"en":"Digga","zh":"哥们，兄弟（来自北德口语，原是 Dicker，现在没有贬义，多为男生之间）","reg":"随意","ex":"A: Digga, wo bist du? Wir warten schon! / B: Bin gleich da!","exzh":"A：兄弟，你在哪儿？我们等着呢！/ B：马上到！"},{"en":"Was geht?","zh":"咋样？/ 最近怎么样？（年轻人打招呼）","reg":"随意","ex":"A: Yo, was geht? / B: Nicht viel. Und bei dir?","exzh":"A：哟，咋样？/ B：没啥。你呢？"},{"en":"chillen","zh":"放松，待着，什么都不干","reg":"随意","ex":"A: Was machst du heute? / B: Nichts, ich chille einfach zu Hause.","exzh":"A：你今天干嘛？/ B：不干嘛，就在家躺着。"},{"en":"cringe","zh":"好尴尬，让人脚趾抠地","reg":"随意","ex":"Er hat im Meeting angefangen zu rappen? Das ist so cringe!","exzh":"他在会上开始说唱？太尴尬了！"},{"en":"lost","zh":"一脸懵，完全搞不清状况","reg":"随意","ex":"A: Hast du die neue Aufgabe verstanden? / B: Nee, ich bin total lost.","exzh":"A：你看懂新任务了吗？/ B：没有，我完全懵了。"},{"en":"Ehrenmann / Ehrenfrau","zh":"够意思的人，好人（夸别人仗义）","reg":"随意","ex":"A: Ich habe dir einen Kaffee mitgebracht. / B: Danke, du bist ein Ehrenmann!","exzh":"A：我给你带了杯咖啡。/ B：谢了，你真够意思！"},{"en":"Wie geil ist das denn?!","zh":"这也太棒了吧！（geil 原本有性含义，年轻人泛指「超棒」，正式场合和长辈面前避免）","reg":"随意","ex":"A: Wir fliegen nächsten Monat nach Bali! / B: Wie geil ist das denn?!","exzh":"A：我们下个月飞巴厘岛！/ B：也太爽了吧！"},{"en":"Läuft bei dir!","zh":"你混得不错嘛！/ 你状态真好！","reg":"随意","ex":"A: Ich habe einen neuen Job und eine neue Wohnung. / B: Läuft bei dir!","exzh":"A：我换了新工作，还搬了新家。/ B：混得不错嘛！"},{"en":"Alter!","zh":"天哪！/ 哥们！（表示惊讶或不满，朋友间用）","reg":"随意","ex":"Alter, das kann doch nicht wahr sein!","exzh":"天哪，这不可能吧！"},{"en":"Gönn dir!","zh":"尽情享受吧！/ 犒劳一下自己！","reg":"随意","ex":"A: Ich bestelle mir heute zwei Desserts. / B: Gönn dir!","exzh":"A：我今天要点两份甜点。/ B：吃吧，犒劳一下自己！"}]}],"drills":[{"id":"ich_haette_gern","pat":"Ich hätte gern ...","zh":"我想要……（点餐购物最礼貌的说法；hätte 是虚拟式。后面接宾格：einen 阳性 / eine 阴性 / ein 中性）","items":[{"cue":"你在面包店想要两个小面包","en":"Ich hätte gern zwei Brötchen, bitte."},{"cue":"你在咖啡店想要一杯拿铁玛奇朵","en":"Ich hätte gern einen Latte macchiato."},{"cue":"你在火车站想买一张去慕尼黑的票","en":"Ich hätte gern eine Fahrkarte nach München."},{"cue":"你在药店想要治头疼的药","en":"Ich hätte gern etwas gegen Kopfschmerzen."},{"cue":"你在餐厅想要一张靠窗的桌子","en":"Ich hätte gern einen Tisch am Fenster."},{"cue":"你在吉隆坡的 mamak 档想点一杯拉茶","en":"Ich hätte gern einen Teh Tarik, bitte."}]},{"id":"koennten_sie","pat":"Könnten Sie ...?","zh":"您能……吗？（比 Können Sie 更客气；动词原形放句末）","items":[{"cue":"你请办事员说慢一点","en":"Könnten Sie bitte etwas langsamer sprechen?"},{"cue":"你请德国客户把文件发邮件给你","en":"Könnten Sie mir die Datei per E-Mail schicken?"},{"cue":"你没听清，请对方再说一遍","en":"Könnten Sie das bitte wiederholen?"},{"cue":"你出门了，请邻居帮你收包裹","en":"Könnten Sie mein Paket annehmen?"},{"cue":"你请出租车司机在下一个路口停车","en":"Könnten Sie an der nächsten Kreuzung halten?"},{"cue":"你请路人帮你们拍张照","en":"Könnten Sie ein Foto von uns machen?"}]},{"id":"ich_moechte","pat":"Ich möchte ...","zh":"我想……（möchte + 句末动词原形；也可以直接 + 名词：Ich möchte einen Kaffee）","items":[{"cue":"你想把德语说得更好","en":"Ich möchte besser Deutsch sprechen."},{"cue":"你在银行想开个账户","en":"Ich möchte ein Konto eröffnen."},{"cue":"你想周五在家办公","en":"Ich möchte am Freitag im Homeoffice arbeiten."},{"cue":"你想把会议改到下午","en":"Ich möchte das Meeting auf den Nachmittag verschieben."},{"cue":"你想退掉这双鞋","en":"Ich möchte diese Schuhe zurückgeben."},{"cue":"你想十二月飞去兰卡威","en":"Ich möchte im Dezember nach Langkawi fliegen."}]},{"id":"kann_ich","pat":"Kann ich ...?","zh":"我可以……吗？（口语里问能不能做某事，比 Darf ich 随意；动词原形放句末）","items":[{"cue":"你在德国咖啡店问能不能刷卡","en":"Kann ich mit Karte zahlen?"},{"cue":"你问同事能不能借一下他的充电线","en":"Kann ich kurz dein Ladekabel benutzen?"},{"cue":"你在服装店问能不能试穿","en":"Kann ich das anprobieren?"},{"cue":"视频会议上你问能不能共享屏幕","en":"Kann ich kurz meinen Bildschirm teilen?"},{"cue":"你问这里能不能停车","en":"Kann ich hier parken?"},{"cue":"你在咖啡店问能不能坐这儿","en":"Kann ich mich hier hinsetzen?"}]},{"id":"ich_muss","pat":"Ich muss ...","zh":"我得……（müssen 变位：ich muss, du musst, er muss。注意 nicht müssen 是「不必」，不是「不许」）","items":[{"cue":"你明天早上要早起","en":"Ich muss morgen früh aufstehen."},{"cue":"你今天得加班","en":"Ich muss heute länger arbeiten."},{"cue":"你下班后还得去趟药店","en":"Ich muss nach der Arbeit noch zur Apotheke."},{"cue":"你得先修好这个 bug","en":"Ich muss zuerst diesen Bug beheben."},{"cue":"你得去续签证","en":"Ich muss mein Visum verlängern."},{"cue":"你说周末不用上班","en":"Am Wochenende muss ich nicht arbeiten."}]},{"id":"perfekt_haben","pat":"Ich habe ... gemacht","zh":"现在完成时：haben + 过去分词（放句末）。德语口语讲过去的事几乎都用 Perfekt，大多数动词用 haben。","items":[{"cue":"你昨天做了中国菜","en":"Ich habe gestern chinesisch gekocht."},{"cue":"你周末看了一部德国电影","en":"Ich habe am Wochenende einen deutschen Film gesehen."},{"cue":"你告诉同事邮件已经发了","en":"Ich habe die E-Mail schon geschickt."},{"cue":"你在站会上说修好了登录的 bug","en":"Ich habe den Login-Bug behoben."},{"cue":"你在 Jalan Alor 吃了沙爹","en":"Ich habe in der Jalan Alor Satay gegessen."},{"cue":"你昨晚学了两个小时德语","en":"Ich habe gestern Abend zwei Stunden Deutsch gelernt."}]},{"id":"perfekt_sein","pat":"Ich bin ... gegangen","zh":"用 sein 的完成时：表示位置移动（gehen, fahren, fliegen, kommen）或状态变化（aufstehen, einschlafen），还有 bleiben 和 sein 本身。","items":[{"cue":"你昨天去了健身房","en":"Ich bin gestern ins Fitnessstudio gegangen."},{"cue":"你去年飞去了柏林","en":"Ich bin letztes Jahr nach Berlin geflogen."},{"cue":"你今天六点就起床了","en":"Ich bin heute um sechs Uhr aufgestanden."},{"cue":"你周末一直待在家","en":"Ich bin am Wochenende zu Hause geblieben."},{"cue":"你今天坐 LRT 去上班","en":"Ich bin heute mit der LRT zur Arbeit gefahren."},{"cue":"你看电影时睡着了","en":"Ich bin beim Film eingeschlafen."}]},{"id":"weil","pat":"..., weil ...","zh":"因为……（weil 引导从句，变位动词放到句末！另：denn 也表示「因为」，但后面是正常语序：…, denn ich bin krank）","items":[{"cue":"你今天来不了，因为生病了","en":"Ich kann heute nicht kommen, weil ich krank bin."},{"cue":"你学德语，因为有德国同事","en":"Ich lerne Deutsch, weil ich deutsche Kollegen habe."},{"cue":"你迟到了，因为路上太堵","en":"Ich bin spät dran, weil der Verkehr so schlimm war."},{"cue":"你喜欢吉隆坡，因为吃的好","en":"Ich mag Kuala Lumpur, weil das Essen so gut ist."},{"cue":"你需要咖啡，因为昨晚没睡好","en":"Ich brauche einen Kaffee, weil ich schlecht geschlafen habe."},{"cue":"你建议推迟发版，因为还有 bug","en":"Wir sollten das Release verschieben, weil es noch Bugs gibt."}]},{"id":"wenn","pat":"Wenn ..., ...","zh":"如果 / 每当……（wenn 从句动词放句末；从句放前面时，主句动词紧跟逗号：Wenn …, bleibe ich …）","items":[{"cue":"如果明天下雨你就待在家","en":"Wenn es morgen regnet, bleibe ich zu Hause."},{"cue":"你说有时间就来","en":"Wenn ich Zeit habe, komme ich gern."},{"cue":"你告诉新同事有问题就给你发消息","en":"Wenn du Fragen hast, schreib mir einfach."},{"cue":"你说测试全部通过就发版","en":"Wenn alle Tests grün sind, machen wir das Release."},{"cue":"你累的时候就听音乐","en":"Wenn ich müde bin, höre ich Musik."},{"cue":"你说以后去德国想参观新天鹅堡","en":"Wenn ich in Deutschland bin, möchte ich Neuschwanstein besuchen."}]},{"id":"dass","pat":"..., dass ...","zh":"引导宾语从句「……这件事」，动词放句末。常跟 Ich glaube / Ich weiß / Ich hoffe / Es tut mir leid。","items":[{"cue":"你希望朋友周末愉快","en":"Ich hoffe, dass du ein schönes Wochenende hast."},{"cue":"你知道会议是明天","en":"Ich weiß, dass das Meeting morgen ist."},{"cue":"你觉得他说得对","en":"Ich glaube, dass er recht hat."},{"cue":"你很高兴朋友来了","en":"Ich freue mich, dass du da bist."},{"cue":"你告诉老板项目周五能完成","en":"Ich sage meinem Chef, dass das Projekt am Freitag fertig ist."},{"cue":"你很抱歉不能来","en":"Es tut mir leid, dass ich nicht kommen kann."}]},{"id":"es_gibt","pat":"Es gibt ...","zh":"有……（表示存在，后面接宾格：einen / eine / ein；问句：Gibt es …?；否定用 kein）","items":[{"cue":"你问附近有没有超市","en":"Gibt es hier in der Nähe einen Supermarkt?"},{"cue":"你告诉德国同事吉隆坡有很多夜市","en":"In Kuala Lumpur gibt es viele Nachtmärkte."},{"cue":"你说代码里还有一个 bug","en":"Es gibt noch einen Bug im Code."},{"cue":"你在餐厅问有没有素食","en":"Gibt es auch etwas Vegetarisches?"},{"cue":"你告诉室友牛奶没了","en":"Es gibt keine Milch mehr."},{"cue":"你问咖啡店有没有 Wi-Fi","en":"Gibt es hier WLAN?"}]},{"id":"wie_komme_ich","pat":"Wie komme ich zum/zur ...?","zh":"怎么去……？（zu + 与格：zum = zu dem（阳性/中性），zur = zu der（阴性），复数 zu den；城市和国家用 nach）","items":[{"cue":"你问怎么去火车总站","en":"Wie komme ich zum Hauptbahnhof?"},{"cue":"你问怎么去机场","en":"Wie komme ich zum Flughafen?"},{"cue":"你问怎么去大学","en":"Wie komme ich zur Universität?"},{"cue":"你问怎么去最近的地铁站","en":"Wie komme ich zur nächsten U-Bahn-Station?"},{"cue":"你带德国朋友在吉隆坡找双子塔，问路人怎么走","en":"Wie komme ich zu den Petronas Towers?"},{"cue":"你问去慕尼黑最好怎么走","en":"Wie komme ich am besten nach München?"}]},{"id":"ich_finde_dass","pat":"Ich finde, dass ...","zh":"我觉得……（表达个人看法；dass 从句动词放句末。也可以不用 dass：Ich finde, das ist gut.）","items":[{"cue":"你觉得德语语法挺难","en":"Ich finde, dass die deutsche Grammatik ziemlich schwer ist."},{"cue":"你觉得这个方案太复杂","en":"Ich finde, dass diese Lösung zu kompliziert ist."},{"cue":"你觉得吉隆坡车太多","en":"Ich finde, dass es in Kuala Lumpur zu viel Verkehr gibt."},{"cue":"你觉得团队应该多做代码审查","en":"Ich finde, dass wir mehr Code-Reviews machen sollten."},{"cue":"你觉得德国面包很好吃","en":"Ich finde, dass das deutsche Brot sehr lecker ist."},{"cue":"你觉得在家办公很适合你","en":"Ich finde, dass Homeoffice gut zu mir passt."}]},{"id":"haetten_sie_zeit","pat":"Hätten Sie Zeit ...?","zh":"您有空……吗？（客气地约时间；朋友之间用 Hättest du Zeit / Hast du Zeit。后面可接 für + 宾格，或 zu + 不定式）","items":[{"cue":"你问德国同事明天有没有空开个短会","en":"Hätten Sie morgen Zeit für ein kurzes Meeting?"},{"cue":"你问经理这周能不能聊一聊","en":"Hätten Sie diese Woche Zeit für ein Gespräch?"},{"cue":"你问朋友周六有没有空","en":"Hättest du am Samstag Zeit?"},{"cue":"你请资深同事帮你看看代码","en":"Hätten Sie kurz Zeit, sich meinen Code anzusehen?"},{"cue":"你问客户下午三点有没有空","en":"Hätten Sie um 15 Uhr Zeit?"},{"cue":"你约朋友一起吃午饭","en":"Hättest du Zeit, mit mir zu Mittag zu essen?"}]},{"id":"freue_mich_auf","pat":"Ich freue mich auf ...","zh":"我期待……（auf + 宾格，指将来的事；对已经发生的事高兴用 sich freuen über）","items":[{"cue":"你期待周末","en":"Ich freue mich auf das Wochenende."},{"cue":"你期待德国之行","en":"Ich freue mich auf die Reise nach Deutschland."},{"cue":"你期待和朋友见面","en":"Ich freue mich auf unser Treffen."},{"cue":"你在邮件结尾说期待合作","en":"Ich freue mich auf die Zusammenarbeit."},{"cue":"你在邮件结尾说期待对方回复","en":"Ich freue mich auf Ihre Antwort."},{"cue":"对比：你为收到的礼物高兴","en":"Ich freue mich über das Geschenk."}]},{"id":"interessiere_mich_fuer","pat":"Ich interessiere mich für ...","zh":"我对……感兴趣（反身动词 sich interessieren + für + 宾格；反身代词要跟主语变：ich → mich, du → dich）","items":[{"cue":"你对德国历史感兴趣","en":"Ich interessiere mich für deutsche Geschichte."},{"cue":"你对人工智能感兴趣","en":"Ich interessiere mich für künstliche Intelligenz."},{"cue":"你问新朋友对什么感兴趣","en":"Wofür interessierst du dich?"},{"cue":"你说你对足球不感兴趣","en":"Ich interessiere mich nicht für Fußball."},{"cue":"你在求职信里说对后端开发职位感兴趣","en":"Ich interessiere mich für die Stelle als Backend-Entwickler."},{"cue":"你说德国同事对马来西亚美食很感兴趣","en":"Meine deutschen Kollegen interessieren sich sehr für malaysisches Essen."}]},{"id":"trennbare_verben","pat":"Ich rufe dich ... an.","zh":"可分动词：前缀跑到句末（anrufen → Ich rufe dich an）。但和情态动词连用、或在从句里时又合在一起：Kannst du mich abholen?","items":[{"cue":"你说今晚给朋友打电话","en":"Ich rufe dich heute Abend an."},{"cue":"你说每天七点起床","en":"Ich stehe jeden Tag um sieben Uhr auf."},{"cue":"你说下班后去超市买东西","en":"Ich kaufe nach der Arbeit im Supermarkt ein."},{"cue":"你提醒大家会议下午三点开始","en":"Das Meeting fängt um 15 Uhr an."},{"cue":"你告诉朋友在中央车站换车","en":"Wir steigen am Hauptbahnhof um."},{"cue":"你问朋友明天能不能来接你（情态动词）","en":"Kannst du mich morgen abholen?"}]},{"id":"wo_ist","pat":"Wo ist ... / Wo sind ...?","zh":"……在哪儿？（单数用 ist，复数用 sind。名词的性要记住：der Ausgang, die Toilette）","items":[{"cue":"你在餐厅找洗手间","en":"Entschuldigung, wo ist hier die Toilette?"},{"cue":"你出门前找不到钥匙","en":"Wo sind meine Schlüssel?"},{"cue":"你在商场找出口","en":"Wo ist der Ausgang?"},{"cue":"你在超市找鸡蛋","en":"Entschuldigung, wo sind die Eier?"},{"cue":"你在德国办公室找会议室","en":"Wo ist der Besprechungsraum?"},{"cue":"你问同事会议资料在哪儿","en":"Wo sind die Unterlagen für das Meeting?"}]},{"id":"darf_ich","pat":"Darf ich ...?","zh":"我可以……吗？（礼貌地请求许可，比 Kann ich 更正式）","items":[{"cue":"你敲门后问能不能进来","en":"Darf ich hereinkommen?"},{"cue":"你想问对方一个问题","en":"Darf ich Sie etwas fragen?"},{"cue":"你想开窗","en":"Darf ich das Fenster aufmachen?"},{"cue":"你在博物馆问能不能拍照","en":"Darf ich hier fotografieren?"},{"cue":"你介绍你的同事 Mei Ling","en":"Darf ich vorstellen? Das ist meine Kollegin Mei Ling."},{"cue":"你在别人家想用一下洗手间","en":"Darf ich mal Ihre Toilette benutzen?"}]},{"id":"keine_zeit","pat":"Ich habe keine Zeit / kein ...","zh":"否定名词用 kein，不用 nicht！kein 的变化跟 ein 一样：作宾语时 keinen（阳性）/ keine（阴性和复数）/ kein（中性）","items":[{"cue":"你今天没时间","en":"Ich habe heute leider keine Zeit."},{"cue":"你身上没带现金","en":"Ich habe kein Bargeld dabei."},{"cue":"你婉拒说不饿","en":"Danke, ich habe keinen Hunger."},{"cue":"会议最后你说没有问题了","en":"Ich habe keine Fragen mehr."},{"cue":"你说不想看足球","en":"Ich habe keine Lust auf Fußball."},{"cue":"你说你没有车","en":"Ich habe kein Auto."}]},{"id":"zu_infinitiv","pat":"... zu + Infinitiv","zh":"zu + 不定式放句末；常跟在 Lust haben, versuchen, vergessen, vorhaben, Es ist schwer … 后面。可分动词的 zu 夹在中间：anzurufen","items":[{"cue":"你说德语发音很难学","en":"Es ist schwer, die deutsche Aussprache zu lernen."},{"cue":"你忘了给妈妈打电话","en":"Ich habe vergessen, meine Mutter anzurufen."},{"cue":"你说你努力每天说德语","en":"Ich versuche, jeden Tag Deutsch zu sprechen."},{"cue":"你今天不想做饭","en":"Ich habe heute keine Lust zu kochen."},{"cue":"你打算明年去德国旅行","en":"Ich habe vor, nächstes Jahr nach Deutschland zu reisen."},{"cue":"你看着窗外说开始下雨了","en":"Es fängt an zu regnen."}]},{"id":"um_zu","pat":"..., um ... zu ...","zh":"为了……（表示目的，zu + 不定式放句末；前后主语不同时要用 damit）","items":[{"cue":"你学德语是为了和同事交流","en":"Ich lerne Deutsch, um mit meinen Kollegen zu sprechen."},{"cue":"你早起是为了去跑步","en":"Ich stehe früh auf, um joggen zu gehen."},{"cue":"你存钱是为了去欧洲旅行","en":"Ich spare Geld, um durch Europa zu reisen."},{"cue":"你去银行是为了开户","en":"Ich gehe zur Bank, um ein Konto zu eröffnen."},{"cue":"你需要 VPN 才能访问公司服务器","en":"Ich brauche das VPN, um auf den Firmenserver zuzugreifen."},{"cue":"你喝咖啡是为了保持清醒","en":"Ich trinke Kaffee, um wach zu bleiben."}]},{"id":"komparativ","pat":"... -er als ...","zh":"比较级：形容词 + er，「比」用 als（不是 wie）。很多单音节词要变音：groß → größer, warm → wärmer；不规则：gut → besser","items":[{"cue":"你说吉隆坡比柏林暖和","en":"Kuala Lumpur ist wärmer als Berlin."},{"cue":"你说柏林比慕尼黑大","en":"Berlin ist größer als München."},{"cue":"你说新电脑比旧的快","en":"Mein neuer Laptop ist schneller als der alte."},{"cue":"你觉得坐火车比开车舒服","en":"Mit dem Zug ist es bequemer als mit dem Auto."},{"cue":"你觉得德语比英语难","en":"Deutsch ist schwieriger als Englisch."},{"cue":"你说今天感觉比昨天好","en":"Heute geht es mir besser als gestern."}]},{"id":"lieber","pat":"lieber / am liebsten","zh":"更喜欢 / 最喜欢（gern → lieber → am liebsten，放在动词后面；比较对象用 als）","items":[{"cue":"你说比起咖啡更喜欢喝茶","en":"Ich trinke lieber Tee als Kaffee."},{"cue":"你说最喜欢吃椰浆饭","en":"Am liebsten esse ich Nasi Lemak."},{"cue":"你说更喜欢在家办公","en":"Ich arbeite lieber im Homeoffice."},{"cue":"你问朋友更想去海边还是山里","en":"Fährst du lieber ans Meer oder in die Berge?"},{"cue":"你问朋友周末最喜欢做什么","en":"Was machst du am Wochenende am liebsten?"},{"cue":"你说比起 Java 更喜欢用 Python","en":"Ich programmiere lieber in Python als in Java."}]},{"id":"seit","pat":"seit + Dativ","zh":"自从……/ ……多久了（seit + 与格：seit drei Jahren, seit einem Monat, seit letzter Woche。动作还在继续时用现在时，不用完成时！）","items":[{"cue":"你在吉隆坡住了三年了","en":"Ich wohne seit drei Jahren in Kuala Lumpur."},{"cue":"你学德语两个月了","en":"Ich lerne seit zwei Monaten Deutsch."},{"cue":"你从上周就开始生病","en":"Ich bin seit letzter Woche krank."},{"cue":"你在这家公司工作一年了","en":"Ich arbeite seit einem Jahr bei dieser Firma."},{"cue":"你已经等公交二十分钟了","en":"Ich warte schon seit zwanzig Minuten auf den Bus."},{"cue":"你问德国客户在德国住了多久","en":"Seit wann wohnen Sie in Deutschland?"}]}],"pron":{"pairs":[{"id":"i_long_short","title":"/iː/ vs /ɪ/ 长 i 和短 i","a":"/iː/","b":"/ɪ/","how":"/iː/ 嘴角往两边拉开像微笑，舌头抬高绷紧，声音拉长，像拖长的“衣——”。/ɪ/ 嘴巴放松、舌头稍低，又短又松，介于“衣”和“诶”之间。规律：ie、ih 读长音（ihn, Miete），少数 i+单辅音也读长音（wir, Tiger）；i+双辅音多为短音（Mitte, bitten），in、im、mit 这类小词也是短音。","words":[["ihn","in"],["ihm","im"],["Miete","Mitte"],["bieten","bitten"],["Stiel","still"],["schief","Schiff"],["Riese","Risse"],["wir","wirr"]],"sent":[["Die Miete ist zu hoch.","Die Mitte ist zu hoch."],["Die Riesen sind groß.","Die Risse sind groß."]]},{"id":"u_long_short","title":"/uː/ vs /ʊ/ 长 u 和短 u","a":"/uː/","b":"/ʊ/","how":"/uː/ 双唇撅圆向前突出，舌根抬高，拉长成“乌——”。/ʊ/ 嘴唇只轻轻收圆、更松，短促，有点接近“乌”和“喔”之间。拼写提示：uh、ß 前的 u 多为长音（Ruhm, Buße）；双辅音 ss、ck、mm 前为短音（Busse, spucken）。注意 er sucht（长）和 die Sucht（短）拼写一样、读法不同。","words":[["Mus","muss"],["Ruhm","Rum"],["Buße","Busse"],["spuken","spucken"],["sucht","Sucht"]],"sent":[["Er sucht Ruhm.","Er sucht Rum."],["Bitte nicht spuken!","Bitte nicht spucken!"]]},{"id":"ue_u","title":"/yː/ vs /uː/ ü 和 u","a":"/yː/ /ʏ/","b":"/uː/ /ʊ/","how":"ü 就是汉语拼音的 ü（“鱼”的韵母）：舌头位置同“衣”，嘴唇撅圆。u 是“乌”：舌头后缩，嘴唇撅圆。两者嘴唇一样圆，区别全在舌头前后。中国人容易把 Tür 读成 Tour，记住 ü 舌尖要抵下齿。","words":[["Tür","Tour"],["für","fuhr"],["Brüder","Bruder"],["Mütter","Mutter"],["drücken","drucken"],["nützen","nutzen"],["spülen","spulen"],["würde","wurde"]],"sent":[["Bitte drücken Sie hier.","Bitte drucken Sie hier."],["Die Tür ist schwer.","Die Tour ist schwer."]]},{"id":"oe_o","title":"/øː/ vs /oː/ ö 和 o","a":"/øː/ /œ/","b":"/oː/ /ɔ/","how":"ö：先发“诶”（e），舌头不动，把嘴唇撅圆，就是 ö；汉语里没有这个音，千万别读成“欧”或“饿”。o：舌头后缩，嘴唇撅圆成“喔”，长 o 不要滑成英语的 /oʊ/。练习时可以 e → ö → o 连着发，感受舌头从前往后移。","words":[["schön","schon"],["Böden","Boden"],["Öfen","Ofen"],["Töchter","Tochter"],["Vögel","Vogel"],["Löcher","Locher"],["lösen","losen"],["Höhle","hohle"]],"sent":[["Es ist schön warm.","Es ist schon warm."],["Wir müssen das lösen.","Wir müssen das losen."]]},{"id":"ue_i","title":"/yː/ vs /iː/ ü 和 i","a":"/yː/ /ʏ/","b":"/iː/ /ɪ/","how":"i 和 ü 舌头位置完全一样，只差嘴唇：i 嘴角往两边拉（微笑），ü 嘴唇撅圆（吹口哨）。练习：发长长的“衣——”，舌头不动，慢慢把嘴唇收圆，就变成 ü。很多人说 für 时嘴唇不圆，听起来就成了 vier。","words":[["Kissen","küssen"],["Tier","Tür"],["vier","für"],["Kiste","Küste"],["Biene","Bühne"],["spielen","spülen"],["liegen","lügen"],["Ziege","Züge"]],"sent":[["Ich spiele nach dem Essen.","Ich spüle nach dem Essen."],["Die Kiste ist lang.","Die Küste ist lang."]]},{"id":"ie_ei","title":"/iː/ vs /aɪ/ ie 和 ei","a":"/iː/ (ie)","b":"/aɪ/ (ei)","how":"德语拼写陷阱：ie 读长“衣” /iː/，ei 读“爱” /aɪ/，和英语直觉相反。记法：看第二个字母，按英语字母名读——ie 读字母 E 的音 /iː/，ei 读字母 I 的音 /aɪ/。Wien 是维也纳，Wein 是葡萄酒；Lied 是歌，Leid 是痛苦。","words":[["Lied","Leid"],["Biene","Beine"],["Wien","Wein"],["Lieder","leider"],["Riese","Reise"],["Wiese","Weise"],["lieb","Leib"],["Stiel","steil"]],"sent":[["Ich mag Wien.","Ich mag Wein."],["Was für ein Lied!","Was für ein Leid!"]]},{"id":"ich_sch","title":"/ç/ vs /ʃ/ ich-Laut 和 sch","a":"/ç/","b":"/ʃ/","how":"/ç/（ich 的 ch）：舌头位置同“衣”，舌面贴近硬腭，嘴角向两边拉，送气发“嘻”的摩擦声，嘴唇不撅。/ʃ/（sch）：嘴唇撅圆向前，舌尖稍后缩，像让人安静的“嘘”。中国人常把 ich 读成 isch 或 ik，记住 ch 嘴唇是扁的。","words":[["Kirche","Kirsche"],["mich","misch"],["Löcher","Löscher"],["wichen","wischen"],["Fichte","fischte"],["Gicht","Gischt"],["Wicht","wischt"]],"sent":[["Ich mag Kirchen.","Ich mag Kirschen."],["Die Kinder malen Kirchen.","Die Kinder malen Kirschen."]]},{"id":"ch_k","title":"/x/ /ç/ vs /k/ ch 和 k","a":"/x/ /ç/ (ch)","b":"/k/ (k, ck)","how":"ch 是摩擦音，气流不断：a/o/u/au 后读 /x/，像汉语“喝”的 h 但更靠后、更粗；e/i/ä/ö/ü、辅音后读 /ç/。k/ck 是爆破音，舌根先堵住再弹开，气流一下就断。别把 Nacht 读成 nackt（裸体），ch 一定要“拖”出摩擦声。","words":[["Nacht","nackt"],["doch","Dock"],["lochen","Locken"],["machen","Macken"],["pochen","Pocken"],["Becher","Bäcker"],["Strich","Strick"],["Rechen","recken"]],"sent":[["Ich brauche einen Becher.","Ich brauche einen Bäcker."],["Wo ist der Strich?","Wo ist der Strick?"]]},{"id":"r_l","title":"/ʁ/ vs /l/ 小舌 r 和 l","a":"/ʁ/","b":"/l/","how":"德语 r（音节开头）是小舌音：舌尖放下抵住下齿，舌根抬向小舌，轻轻摩擦，像漱口时喉咙里的声音，不卷舌。l 是舌尖顶住上齿龈，气流从两侧出，舌头前部要“亮”。中国南方同学容易 l/r 不分，先慢读 Rippe … Lippe，感受舌尖一个在下、一个在上。","words":[["Rand","Land"],["Rose","Lose"],["Rippe","Lippe"],["Ratte","Latte"],["Rücken","Lücken"],["Reise","leise"],["Rampe","Lampe"],["rot","Lot"]],"sent":[["Die Rippe tut weh.","Die Lippe tut weh."],["Die Lampe ist kaputt.","Die Rampe ist kaputt."]]},{"id":"z_s","title":"/ts/ vs /z/ z 和 s","a":"/ts/ (z)","b":"/z/ (s)","how":"德语 z 永远读 /ts/，像汉语拼音的 c（“次”），要先堵后擦、送气。元音前的 s 读浊音 /z/，像英语 zoo 的 z，声带振动、没有 t。常见错误是受英语影响把 z 读成 [z]（像 zoo），这样 Zoo 就和 so [zoː] 一样了；反过来也别把元音前的 s 读成清音 [s]。","words":[["Zahl","Saal"],["Zeit","seit"],["Zinn","Sinn"],["Zeh","See"],["Ziege","Siege"],["Zeile","Seile"],["Zoo","so"],["zieht","sieht"]],"sent":[["Er zieht das Auto.","Er sieht das Auto."],["Das ist ein großer Zeh.","Das ist ein großer See."]]},{"id":"a_long_short","title":"/aː/ vs /a/ 长 a 和短 a","a":"/aː/","b":"/a/","how":"德语 a 只有长短之分，音色几乎一样：长 a 拖长成“啊——”，短 a 干脆利落“啊”就收，后面的辅音紧跟上。规律：ah、aa、a+单辅音多为长音（Kahn, Staat, kam）；a+双辅音或辅音丛为短音（kann, Stadt, Kamm）。长短读错意思就变。","words":[["Staat","Stadt"],["Kahn","kann"],["kam","Kamm"],["Rate","Ratte"],["Saat","satt"],["Wahn","wann"],["Schal","Schall"],["Haken","hacken"]],"sent":[["Wir haken das ab.","Wir hacken das ab."],["Die Rate ist hoch.","Die Ratte ist hoch."]]},{"id":"h_zero","title":"/h/ vs 无 h 开头 h 和元音","a":"/h/","b":"∅（喉塞音）","how":"德语 h 比汉语“喝”的 h 轻得多：喉咙完全放松，只是呼一口气（像对着镜子哈气），舌根不要摩擦，否则 Hund 会听成 ach 的 ch。没有 h 的元音开头则要干脆地起音（喉塞音），不要带气。注意：元音后的 h 不发音，只表示长音（gehen, Bahn）。","words":[["Hund","und"],["hier","ihr"],["Haus","aus"],["halt","alt"],["heiß","Eis"],["hoffen","offen"],["Hecke","Ecke"],["heilen","eilen"]],"sent":[["Hier ist es kalt.","Ihr ist es kalt."],["Das ist heiß.","Das ist Eis."]]}],"connected":[{"type":"尾音清化","en":"Am Montag habe ich frei.","sounds":"/ʔam ˈmoːntaːk ˈhaːbə ʔɪç fʁaɪ̯/ Tag 读 [taːk]","zh":"词尾（和音节末尾）的 b d g 一律读成 p t k：Tag [taːk]、ab [ap]。但复数 Tage 里 g 又回到 [ɡ]。千万不要像英语那样读出浊音 g。"},{"type":"尾音清化","en":"Der Hund ist lieb.","sounds":"/deːɐ̯ hʊnt ʔɪst liːp/ 'Hunt … liep'","zh":"Hund 的 d 读 t，lieb 的 b 读 p。比较 Hunde [ˈhʊndə]、liebe [ˈliːbə]：后面有元音时才恢复浊音。"},{"type":"尾音清化","en":"Der Zug fährt gleich ab.","sounds":"/deːɐ̯ tsuːk fɛːɐ̯t ɡlaɪ̯ç ʔap/ 'Zuk … ap'","zh":"Zug 读 [tsuːk]，ab 读 [ap]。词尾的 s 也永远是清音 [s]，所以 Haus 是 [haʊ̯s]，复数 Häuser 才是 [z]。"},{"type":"喉塞音","en":"Ich beachte die Regeln.","sounds":"/ʔɪç bəˈʔaxtə diː ˈʁeːɡl̩n/ 'be|achte'","zh":"以元音开头的词干前，喉咙要轻轻“卡”一下再发音（Knacklaut）。be|achten 中间断开，不能连成 bea-chten。类似：ver|eisen、Ober|arm。"},{"type":"喉塞音","en":"Er isst einen Apfel.","sounds":"/ʔeːɐ̯ ʔɪst ʔaɪ̯nən ˈʔapfl̩/ 每个元音前都“卡”一下","zh":"德语不像英语那样把辅音连到下一个元音上：不是 Er-risst-teinen，而是 Er | isst | einen | Apfel。每个元音开头的词干净起音，听起来才“德国味”。"},{"type":"-er 读音","en":"Mein Lehrer ist sehr nett.","sounds":"/maɪ̯n ˈleːʁɐ ʔɪst zeːɐ̯ nɛt/ 'Lehra'","zh":"词尾 -er 不读“额儿”，而是读成很轻的 [ɐ]，像短而弱的“啊”。sehr 的 r 也变成 [ɐ̯]。不要卷舌，也不要读英语的 -er。"},{"type":"-er 读音","en":"Aber das ist viel besser.","sounds":"/ˈʔaːbɐ das ʔɪst fiːl ˈbɛsɐ/ 'Aba … bessa'","zh":"aber、besser、Wasser、Mutter 的 -er 都读 [ɐ]。比较 besser [ˈbɛsɐ] 和 Messe [ˈmɛsə]：-er 是开口的“啊”，-e 是轻声的“呃”。"},{"type":"r 元音化","en":"Wir sind sehr gern hier.","sounds":"/viːɐ̯ zɪnt zeːɐ̯ ɡɛɐ̯n hiːɐ̯/ r 变成 [ɐ̯]","zh":"元音后的 r（尤其长元音后、词尾）不发小舌音，而是变成半个“啊” [ɐ̯]：wir ≈ “维啊”、hier ≈ “希啊”。只有元音前的 r（rot, Straße, Ihre）才读小舌音。"},{"type":"-ig 读音","en":"Das ist wichtig und richtig.","sounds":"/das ʔɪst ˈvɪçtɪç ʔʊnt ˈʁɪçtɪç/ -ig 读 [ɪç]","zh":"标准德语里词尾 -ig 读 [ɪç]（像 ich 的 ch），不读 ik。但后面加了元音就读 [ɪɡ]：wichtige [ˈvɪçtɪɡə]、Könige [ˈkøːnɪɡə]。南德和奥地利常说 [ɪk]，也能听懂。"},{"type":"ch 读音","en":"Ich mache das noch nicht.","sounds":"/ʔɪç ˈmaxə das nɔx nɪçt/ ich [ç] / mache [x]","zh":"ch 两种读法：a o u au 后面是喉咙深处的 [x]（mache, noch, Buch, auch）；其他元音和辅音后面是舌面的 [ç]（ich, nicht, Milch）。别把 ich 读成“伊克”或“伊施”。"},{"type":"弱读","en":"Wir gehen morgen einkaufen.","sounds":"/viːɐ̯ ˈɡeːən ˈmɔʁɡŋ̍ ˈʔaɪ̯nkaʊ̯fn̩/ 'morgn … einkaufn'","zh":"非重读的 -en 在口语里 e 几乎消失，n 直接成为音节：kaufen ≈ [kaʊ̯fn̩]，morgen ≈ [mɔʁɡŋ̍]（受 g 影响变成 ng）。不要每个 -en 都清清楚楚读“恩”。"},{"type":"同化","en":"Wir haben keine Zeit.","sounds":"/viːɐ̯ ˈhaːbm̩ ˈkaɪ̯nə tsaɪ̯t/ haben → [ˈhaːbm̩]，口语甚至 'ham'","zh":"-en 前面是 b/p 时，n 被双唇“同化”成 m：haben [ˈhaːbm̩]、leben [ˈleːbm̩]。口语里 haben 常缩成 ham。前面是 g/k 时变成 ng：sagen [ˈzaːɡŋ̍]。"},{"type":"st sp","en":"Die Straße ist steil.","sounds":"/diː ˈʃtʁaːsə ʔɪst ʃtaɪ̯l/ Straße [ʃt]，ist [st]","zh":"词首（或词干开头）的 st、sp 读 [ʃt]、[ʃp]，像“诗特”；在词中或词尾仍读 [st]：ist、Fenster、bester。复合词按词干算：Bahnhofstraße 里的 Straße 还是 [ʃt]。"},{"type":"st sp","en":"Ich spreche ein bisschen Deutsch.","sounds":"/ʔɪç ˈʃpʁɛçə ʔaɪ̯n ˈbɪsçən dɔʏ̯tʃ/ 'schpreche'","zh":"sprechen、spielen、Sport 开头都是 [ʃp]，嘴唇要撅圆发“诗”再接 p。注意 bisschen 里的 ss-ch 分开读 [s-ç]，不是 sch。"},{"type":"v w","en":"Mein Vater kommt um vier.","sounds":"/maɪ̯n ˈfaːtɐ kɔmt ʔʊm fiːɐ̯/ v 读 [f]","zh":"德语本族词里的 v 读 [f]：Vater、vier、viel、von、Vogel。外来词里才读 [v]：Video、Vase、Klavier。看到 v 先默认读 f。"},{"type":"v w","en":"Was willst du am Wochenende machen?","sounds":"/vas vɪlst duː ʔam ˈvɔxn̩ʔɛndə ˈmaxn̩/ w 读 [v]","zh":"德语 w 读 [v]：上齿轻咬下唇、声带振动，不是英语的圆唇 w。Was 不是“哇斯”，而是“瓦斯”上齿碰唇。"},{"type":"z 读音","en":"Ich habe zehn Minuten Zeit.","sounds":"/ʔɪç ˈhaːbə tseːn miˈnuːtn̩ tsaɪ̯t/ z 读 [ts]","zh":"z 和 tz 一律读 [ts]，像拼音 c（“刺”），要送气：zehn、Zeit、Platz、jetzt。读成拼音 z 或英语 z 都不对。"},{"type":"s 读音","en":"Sie sagt, die Suppe ist super.","sounds":"/ziː zaːkt diː ˈzʊpə ʔɪst ˈzuːpɐ/ 元音前 s 读 [z]","zh":"元音前的 s 读浊音 [z]，声带振动（像英语 zoo）：Sie、sagen、Suppe、super、lesen。词尾和辅音前读 [s]；ß 和 ss 永远是 [s]。"},{"type":"双元音","en":"Mein Freund kauft heute ein Haus.","sounds":"/maɪ̯n fʁɔʏ̯nt kaʊ̯ft ˈhɔʏ̯tə ʔaɪ̯n haʊ̯s/ ei=[aɪ] eu=[ɔʏ] au=[aʊ]","zh":"三个双元音：ei/ai 读“爱”，eu/äu 读“奥伊”（像英语 boy），au 读“奥”（从 a 滑到 u）。eu 最容易错，别读成“欧”或“饿乌”。"},{"type":"长音规则","en":"Ich fahre mit der Bahn zum Zahnarzt.","sounds":"/ʔɪç ˈfaːʁə mɪt deːɐ̯ baːn tsʊm ˈtsaːnʔaːɐ̯tst/ 元音后 h 不发音","zh":"元音后面的 h 不发音，只是“拉长”标记：fahren、Bahn、Zahn、gehen、Uhr。元音要拖足长度，不要发出 h 的气声。"},{"type":"长音规则","en":"Das Boot liegt auf dem See.","sounds":"/das boːt liːkt ʔaʊ̯f deːm zeː/ oo ie ee 都是长音","zh":"双写元音（aa ee oo）和 ie 都表示长音：Boot、See、Tee、Staat、liegen。长元音要紧、要拖，长短不分母语者会听不懂。"},{"type":"长短音规则","en":"Ich komme mit, wenn ich kann.","sounds":"/ʔɪç ˈkɔmə mɪt vɛn ʔɪç kan/ 双辅音前元音短","zh":"元音后面有双辅音（mm nn ss tt ck）或两个以上辅音时，元音短而松：komme、wenn、kann、Bett。双写辅音本身只读一个，不要读两遍。"},{"type":"辅音丛","en":"Im Herbst sprichst du schon gut Deutsch.","sounds":"/ʔɪm hɛʁpst ʃpʁɪçst duː ʃoːn ɡuːt dɔʏ̯tʃ/ 'Herbst' 'schprichst'","zh":"德语辅音能连好几个，中间不要插“呃”：Herbst 是 [hɛʁpst]，不是“赫儿伯斯特”。sprichst = schp-r-i-ch-st，先慢慢拆开练，再连起来。"},{"type":"词重音","en":"Ich rufe dich später an.","sounds":"/ʔɪç ˈʁuːfə dɪç ˈʃpɛːtɐ ʔan/ anrufen 重音在 an","zh":"可分动词重音落在前缀上：ANrufen、AUFstehen、EINkaufen，句尾的 an 要读得清楚。不可分前缀 be- ver- er- ge- 不重读：verSTEHen、beSUCHen。"},{"type":"外来词","en":"Ich habe meinen Computer im Restaurant vergessen.","sounds":"/ʁɛstoˈʁɑ̃ː kɔmˈpjuːtɐ/ 'Resto-rang' 'Kom-pjuter'","zh":"外来词保留原语读音：Restaurant 按法语读，结尾鼻化不读 t；Computer 按英语读但 -er 仍是 [ɐ]；Chef 读 [ʃɛf]；-tion 读 [tsi̯oːn]（Information）。"},{"type":"口语缩略","en":"Haste heute Abend Zeit?","sounds":"/ˈhastə ˈhɔʏ̯tə ˈʔaːbn̩t tsaɪ̯t/ haste = hast du","zh":"随意口语：hast du 连读成 haste，du 的 d 被前面的 t 吞掉。类似 kannste（kannst du）、willste（willst du）。只在朋友间用，自己写邮件别这样写。"},{"type":"口语缩略","en":"Gibt's hier in der Nähe ein Café?","sounds":"/ɡɪpts hiːɐ̯ ʔɪn deːɐ̯ ˈnɛːə ʔaɪ̯n kaˈfeː/ gibt's = gibt es","zh":"gibt es 口语几乎都说 gibt's [ɡɪpts]，书面也常见。同理 wie geht's、was gibt's Neues。注意 gibt 的 b 读 p。"},{"type":"口语缩略","en":"Isses noch weit?","sounds":"/ˈʔɪsəs nɔx vaɪ̯t/ isses = ist es","zh":"随意口语里 ist es 吞掉 t 变成 isses。听懂就行，自己说 Ist es noch weit? 完全没问题。"},{"type":"口语缩略","en":"Ich hab 'n neuen Laptop.","sounds":"/ʔɪç haːp n̩ ˈnɔʏ̯ən ˈlɛptɔp/ hab' = habe，'n = einen","zh":"口语里 habe 去掉 e 变 hab'，ein/einen/eine 弱读成 'n、'ne：Ich hab 'ne Frage。标准形式：Ich habe einen neuen Laptop。"},{"type":"口语缩略","en":"Wir ham noch nich gegessen, ne?","sounds":"/viːɐ̯ ham nɔx nɪç ɡəˈɡɛsn̩ nə/ ham = haben，nich = nicht","zh":"随意口语三件套：haben → ham，nicht → nich（掉 t），句尾 ne? = nicht wahr? / oder?（“对吧？”）。北德尤其常见。标准形式：Wir haben noch nicht gegessen, oder?"}],"shadow":[{"group":"日常起居","items":[{"en":"Ich stehe jeden Tag um sieben auf.","zh":"我每天七点起床。"},{"en":"Ich habe letzte Nacht schlecht geschlafen.","zh":"我昨晚没睡好。"},{"en":"Ich gehe kurz duschen.","zh":"我去冲个澡。"},{"en":"Was gibt es heute zum Frühstück?","zh":"今天早餐吃什么？"},{"en":"Ich mache mir schnell einen Kaffee.","zh":"我赶紧给自己冲杯咖啡。"},{"en":"Kannst du bitte das Licht ausmachen?","zh":"你能把灯关了吗？"},{"en":"Ich bin müde und gehe ins Bett.","zh":"我累了，去睡觉了。"},{"en":"Wo ist denn mein Handy?","zh":"我的手机到底在哪儿？"},{"en":"Ich muss heute noch Wäsche waschen.","zh":"我今天还得洗衣服。"},{"en":"Der Kühlschrank ist fast leer.","zh":"冰箱快空了。"},{"en":"Ich räume schnell die Küche auf.","zh":"我快速收拾一下厨房。"},{"en":"Heute koche ich zu Hause.","zh":"今天我在家做饭。"},{"en":"Hast du den Müll schon rausgebracht?","zh":"你已经把垃圾拿出去了吗？"},{"en":"Ich bin gleich fertig.","zh":"我马上就好。"},{"en":"Mein Wecker hat nicht geklingelt.","zh":"我的闹钟没响。"},{"en":"Ich arbeite heute von zu Hause aus.","zh":"我今天在家办公。"},{"en":"Es ist so heiß, ich mache die Klimaanlage an.","zh":"太热了，我开空调。"},{"en":"Ich gehe noch schnell einkaufen.","zh":"我再赶紧去买点东西。"},{"en":"Kannst du mir bitte das Salz geben?","zh":"你能把盐递给我吗？"},{"en":"Gute Nacht, schlaf gut!","zh":"晚安，睡个好觉！"}]},{"group":"购物吃饭","items":[{"en":"Ich hätte gern zwei Brötchen, bitte.","zh":"我想要两个小面包，谢谢。"},{"en":"Wie viel kostet das hier?","zh":"这个多少钱？"},{"en":"Kann ich mit Karte zahlen?","zh":"可以刷卡吗？"},{"en":"Einen Tisch für zwei Personen, bitte.","zh":"请给我们一张两人桌。"},{"en":"Ich nehme die Suppe und ein Wasser.","zh":"我要汤和一瓶水。"},{"en":"Können wir bitte die Speisekarte haben?","zh":"可以给我们菜单吗？"},{"en":"Haben Sie das auch in Größe M?","zh":"这个有 M 码吗？"},{"en":"Wir möchten bitte zahlen.","zh":"我们想结账。"},{"en":"Wir zahlen getrennt, bitte.","zh":"我们分开付。"},{"en":"Das schmeckt wirklich sehr gut.","zh":"这个真的很好吃。"},{"en":"Ich esse kein Fleisch.","zh":"我不吃肉。"},{"en":"Ist das Essen sehr scharf?","zh":"这道菜很辣吗？"},{"en":"Ich brauche keine Tüte, danke.","zh":"我不需要袋子，谢谢。"},{"en":"Wo finde ich die Milch?","zh":"牛奶在哪儿？"},{"en":"Kann ich das noch umtauschen?","zh":"这个还能换吗？"},{"en":"Haben Sie noch frisches Brot?","zh":"还有新鲜面包吗？"},{"en":"Den Kaffee bitte zum Mitnehmen.","zh":"咖啡请帮我打包带走。"},{"en":"Das stimmt so, vielen Dank.","zh":"不用找了，非常感谢。"},{"en":"Das ist mir leider zu teuer.","zh":"这对我来说太贵了。"},{"en":"Könnte ich noch ein Glas Wasser bekommen?","zh":"能再给我一杯水吗？"}]},{"group":"出行问路","items":[{"en":"Entschuldigung, wo ist der Bahnhof?","zh":"打扰一下，火车站在哪儿？"},{"en":"Wie komme ich zum Flughafen?","zh":"去机场怎么走？"},{"en":"Ist das weit von hier?","zh":"离这儿远吗？"},{"en":"Kann ich zu Fuß gehen?","zh":"可以走路过去吗？"},{"en":"Welcher Bus fährt ins Zentrum?","zh":"哪路公交车去市中心？"},{"en":"Eine Fahrkarte nach München, bitte.","zh":"请给我一张去慕尼黑的车票。"},{"en":"Von welchem Gleis fährt der Zug?","zh":"火车从几号站台发车？"},{"en":"Muss ich in Köln umsteigen?","zh":"我要在科隆换车吗？"},{"en":"Der Zug hat zehn Minuten Verspätung.","zh":"火车晚点十分钟。"},{"en":"Gehen Sie geradeaus und dann links.","zh":"您一直往前走，然后左转。"},{"en":"Wo kann ich ein Ticket kaufen?","zh":"在哪儿可以买票？"},{"en":"Ist dieser Platz noch frei?","zh":"这个座位有人吗？"},{"en":"Ich habe mich verlaufen.","zh":"我迷路了。"},{"en":"Wann fährt der nächste Zug nach Berlin?","zh":"下一班去柏林的火车几点开？"},{"en":"Halten Sie bitte hier an.","zh":"请在这里停车。"},{"en":"Wie lange dauert die Fahrt?","zh":"车程要多久？"},{"en":"Ich nehme lieber ein Taxi.","zh":"我还是打车吧。"},{"en":"Gibt es hier in der Nähe eine Apotheke?","zh":"这附近有药店吗？"},{"en":"Können Sie mir das auf der Karte zeigen?","zh":"您能在地图上指给我看吗？"},{"en":"Ich bin gerade angekommen.","zh":"我刚到。"}]},{"group":"工作沟通","items":[{"en":"Können Sie mich gut hören?","zh":"您能听清我说话吗？"},{"en":"Ich teile kurz meinen Bildschirm.","zh":"我共享一下屏幕。"},{"en":"Können Sie das bitte wiederholen?","zh":"您能再说一遍吗？"},{"en":"Ich schicke Ihnen die Datei per E-Mail.","zh":"我把文件用邮件发给您。"},{"en":"Ich bin heute bis fünf im Büro.","zh":"我今天在办公室待到五点。"},{"en":"Das Meeting beginnt um zehn Uhr.","zh":"会议十点开始。"},{"en":"Ich bin damit fast fertig.","zh":"这个我快做完了。"},{"en":"Haben Sie kurz Zeit für eine Frage?","zh":"您有空回答一个问题吗？"},{"en":"Ich kümmere mich darum.","zh":"这件事我来处理。"},{"en":"Das klingt gut, machen wir es so.","zh":"听起来不错，就这么办。"},{"en":"Können wir den Termin verschieben?","zh":"我们能改一下时间吗？"},{"en":"Das habe ich leider nicht verstanden.","zh":"不好意思，这个我没听懂。"},{"en":"Bis wann brauchen Sie das?","zh":"您什么时候之前需要？"},{"en":"Ich melde mich morgen bei Ihnen.","zh":"我明天联系您。"},{"en":"Der Code läuft jetzt ohne Fehler.","zh":"代码现在运行没有报错了。"},{"en":"Ich bin gleich wieder da.","zh":"我马上回来。"},{"en":"Meine Internetverbindung ist gerade schlecht.","zh":"我的网络现在不太好。"},{"en":"Wer übernimmt diese Aufgabe?","zh":"这个任务谁来负责？"},{"en":"Lassen Sie uns eine kurze Pause machen.","zh":"我们休息一下吧。"},{"en":"Danke, das hilft mir sehr.","zh":"谢谢，这对我帮助很大。"}]},{"group":"社交闲聊","items":[{"en":"Hallo, wie geht es dir?","zh":"你好，你最近怎么样？"},{"en":"Woher kommst du eigentlich?","zh":"你是哪里人？"},{"en":"Ich komme aus China und wohne in Kuala Lumpur.","zh":"我来自中国，住在吉隆坡。"},{"en":"Was machst du beruflich?","zh":"你是做什么工作的？"},{"en":"Ich arbeite als Softwareentwickler.","zh":"我是做软件开发的。"},{"en":"Was machst du am Wochenende?","zh":"你周末干什么？"},{"en":"Hast du Lust auf einen Kaffee?","zh":"想不想去喝杯咖啡？"},{"en":"Ich lerne seit drei Monaten Deutsch.","zh":"我学德语三个月了。"},{"en":"Das freut mich sehr!","zh":"我很高兴！"},{"en":"Wie war dein Urlaub?","zh":"你的假期过得怎么样？"},{"en":"Kennst du hier ein gutes Restaurant?","zh":"你知道这儿有什么好餐厅吗？"},{"en":"Wollen wir am Samstag zusammen essen?","zh":"周六一起吃饭吧？"},{"en":"Schön, dich kennenzulernen, ich bin Ray.","zh":"很高兴认识你，我是 Ray。"},{"en":"Was ist dein Lieblingsessen?","zh":"你最喜欢吃什么？"},{"en":"In Malaysia ist es das ganze Jahr warm.","zh":"马来西亚一年四季都很暖和。"},{"en":"Das klingt echt spannend.","zh":"听起来真有意思。"},{"en":"Bis bald, mach's gut!","zh":"回头见，保重！"},{"en":"Wie war dein Tag?","zh":"你今天过得怎么样？"},{"en":"Hast du eigentlich Geschwister?","zh":"你有兄弟姐妹吗？"},{"en":"Wir sollten uns bald wieder treffen.","zh":"我们应该很快再聚一次。"}]},{"group":"表达感受","items":[{"en":"Ich freue mich sehr darauf.","zh":"我非常期待。"},{"en":"Ich bin ein bisschen nervös.","zh":"我有点紧张。"},{"en":"Das ärgert mich wirklich.","zh":"这真让我生气。"},{"en":"Mir ist gerade total langweilig.","zh":"我现在无聊透了。"},{"en":"Ich bin heute total müde.","zh":"我今天特别累。"},{"en":"Das finde ich super!","zh":"我觉得这太棒了！"},{"en":"Ich habe keine Lust.","zh":"我没心情（不想做）。"},{"en":"Mir geht es heute nicht so gut.","zh":"我今天不太舒服。"},{"en":"Ich bin sehr froh, dass du hier bist.","zh":"你在这儿我很高兴。"},{"en":"Das macht mir Angst.","zh":"这让我害怕。"},{"en":"Ich vermisse meine Familie.","zh":"我想念我的家人。"},{"en":"Ich bin stolz auf dich.","zh":"我为你骄傲。"},{"en":"Das ist mir echt peinlich.","zh":"这让我真尴尬。"},{"en":"Ich mache mir Sorgen um dich.","zh":"我担心你。"},{"en":"Was für eine Überraschung!","zh":"真是个惊喜！"},{"en":"Ich bin im Moment total gestresst.","zh":"我最近压力特别大。"},{"en":"Das tut mir wirklich leid.","zh":"我真的很抱歉。"},{"en":"Ich fühle mich hier sehr wohl.","zh":"我在这儿感觉很自在。"},{"en":"Ehrlich gesagt bin ich etwas enttäuscht.","zh":"说实话，我有点失望。"},{"en":"Zum Glück hat alles geklappt!","zh":"幸好一切都顺利！"}]}]},"stress":[{"en":"Ich habe nicht gesagt, dass er das Geld gestohlen hat.","variants":[{"stress":"Ich","meaning_zh":"不是我说的（是别人说的）"},{"stress":"gesagt","meaning_zh":"我没说出口（但可能暗示过）"},{"stress":"er","meaning_zh":"我没说是他偷的（是别人）"},{"stress":"Geld","meaning_zh":"我没说他偷的是钱（偷的是别的）"},{"stress":"gestohlen","meaning_zh":"我没说他偷（可能是借的）"}],"tip_zh":"德语和英语一样，重读哪个词，哪个词就是对比焦点。重读词要更响、更长、音调更高，其余词放轻。"},{"en":"Ich fahre morgen mit dem Zug nach Berlin.","variants":[{"stress":"Ich","meaning_zh":"是我去（不是你）"},{"stress":"morgen","meaning_zh":"是明天去（不是今天）"},{"stress":"Zug","meaning_zh":"坐火车去（不是开车）"},{"stress":"Berlin","meaning_zh":"去柏林（不是汉堡）"}],"tip_zh":"中性读法重音落在句末的新信息 Berlin 上。把重音挪到前面的词，就是在纠正对方。"},{"en":"Hast du das Auto gekauft?","variants":[{"stress":"du","meaning_zh":"是你买的吗？（不是你妻子？）"},{"stress":"Auto","meaning_zh":"你买的是车吗？（不是摩托？）"},{"stress":"gekauft","meaning_zh":"你是买的吗？（还是租的？）"}],"tip_zh":"一般疑问句结尾语调上扬，但重读词上要先有一个明显的音高峰。"},{"en":"Das ist mein Fahrrad.","variants":[{"stress":"Das","meaning_zh":"这辆才是我的车（不是那辆）"},{"stress":"ist","meaning_zh":"这就是我的车（你别不信）"},{"stress":"mein","meaning_zh":"这是我的车（不是你的）"},{"stress":"Fahrrad","meaning_zh":"这是我的自行车（不是摩托车）"}],"tip_zh":"重读 ist 表示“确实如此”的反驳语气，德国人吵架时很常用。"},{"en":"Ich trinke keinen Kaffee.","variants":[{"stress":"Ich","meaning_zh":"我不喝咖啡（别人可能喝）"},{"stress":"keinen","meaning_zh":"我一点咖啡都不喝"},{"stress":"Kaffee","meaning_zh":"我不喝咖啡（但喝茶）"}],"tip_zh":"kein 重读时语气很强，表示“完全不”。注意 keinen 是阳性第四格（der Kaffee）。"},{"en":"Wir treffen uns um acht im Café.","variants":[{"stress":"Wir","meaning_zh":"是我们见面（不是他们）"},{"stress":"acht","meaning_zh":"八点见（不是七点）"},{"stress":"Café","meaning_zh":"在咖啡馆见（不是在餐厅）"}],"tip_zh":"约时间地点时，对方说错了什么，你就重读哪个词来纠正。Café 重音在 é 上。"},{"en":"Der rote Pullover gefällt mir.","variants":[{"stress":"rote","meaning_zh":"我喜欢红色那件（不是蓝的）"},{"stress":"Pullover","meaning_zh":"我喜欢的是红毛衣（不是红外套）"},{"stress":"mir","meaning_zh":"我喜欢（别人怎么想我不管）"}],"tip_zh":"gefallen 的主语是物、喜欢的人用第三格 mir。Pullover 重音在 o：Pul-LO-ver。"},{"en":"Ich habe dir das Buch geschenkt.","variants":[{"stress":"Ich","meaning_zh":"是我送你的（不是别人）"},{"stress":"dir","meaning_zh":"我送给的是你（不是你哥哥）"},{"stress":"Buch","meaning_zh":"我送你的是书（不是杂志）"},{"stress":"geschenkt","meaning_zh":"是送你的（不是借你的，不用还）"}],"tip_zh":"完成时的过去分词放句末，重读 geschenkt 时句尾要扬起再落下，别读得太弱。"},{"en":"Kommst du heute Abend mit?","variants":[{"stress":"du","meaning_zh":"你也一起去吗？（其他人都去）"},{"stress":"heute","meaning_zh":"今天晚上去吗？（不是明晚）"},{"stress":"mit","meaning_zh":"你到底来不来？（催对方决定）"}],"tip_zh":"可分动词 mitkommen 的 mit 在句尾，本身就带重音；特别加重时就是在追问“去不去”。"},{"en":"Sie hat ihn gestern angerufen.","variants":[{"stress":"Sie","meaning_zh":"是她打的电话（不是他打给她）"},{"stress":"ihn","meaning_zh":"她打给的是他（不是别人）"},{"stress":"gestern","meaning_zh":"是昨天打的（不是今天）"},{"stress":"angerufen","meaning_zh":"她是打电话（不是去看他）"}],"tip_zh":"angerufen 的重音在 an 上：AN-ge-ru-fen。重读整个词时也是把 an 加重。"},{"en":"Meine Schwester wohnt jetzt in Penang.","variants":[{"stress":"Meine","meaning_zh":"是我的姐妹（不是你的）"},{"stress":"Schwester","meaning_zh":"是我姐妹（不是我兄弟）"},{"stress":"jetzt","meaning_zh":"她现在住槟城（以前不是）"},{"stress":"Penang","meaning_zh":"她住在槟城（不是吉隆坡）"}],"tip_zh":"Schwester 不分姐姐妹妹，需要时说 ältere / jüngere Schwester。重读 jetzt 表示情况变了。"},{"en":"Der Chef hat das Meeting abgesagt.","variants":[{"stress":"Chef","meaning_zh":"是老板取消的（不是客户）"},{"stress":"Meeting","meaning_zh":"取消的是会议（不是午饭）"},{"stress":"abgesagt","meaning_zh":"会议是取消了（不是推迟）"}],"tip_zh":"abgesagt 重音在 ab：AB-ge-sagt。和 verschoben（推迟）对比时尤其要读清楚。"},{"en":"Gib mir bitte das blaue Glas.","variants":[{"stress":"mir","meaning_zh":"给我（不是给他）"},{"stress":"blaue","meaning_zh":"要蓝色的那个杯子（不是绿的）"},{"stress":"Glas","meaning_zh":"要蓝色的杯子（不是蓝盘子）"}],"tip_zh":"德语形容词也能单独重读来做对比。注意 das blaue Glas：定冠词后形容词弱变化，中性第四格词尾是 -e。"},{"en":"Ich habe das nicht gewusst.","variants":[{"stress":"Ich","meaning_zh":"我不知道（别人可能知道）"},{"stress":"das","meaning_zh":"这件事我不知道（别的我知道）"},{"stress":"nicht","meaning_zh":"我真的不知道（别怪我）"},{"stress":"gewusst","meaning_zh":"我并不确定知道（只是猜到过）"}],"tip_zh":"重读 nicht 是在为自己辩解，语气要坚定；平常道歉时重音放在 gewusst 上即可。"},{"en":"Paul spricht sehr gut Deutsch.","variants":[{"stress":"Paul","meaning_zh":"是保罗德语说得好（不是他同事）"},{"stress":"spricht","meaning_zh":"他口语很好（写可能不太行）"},{"stress":"gut","meaning_zh":"他说得真的很好（不只是还行）"},{"stress":"Deutsch","meaning_zh":"他德语好（英语就一般）"}],"tip_zh":"Deutsch 的 eu 读“奥伊”，sch 撅嘴。重读 spricht 时 sp 要读成 schp。"}],"twisters":[{"en":"Fischers Fritz fischt frische Fische, frische Fische fischt Fischers Fritz.","focus":"f/fr/sch","zh":"渔夫家的弗里茨钓新鲜的鱼，新鲜的鱼被渔夫家的弗里茨钓。","tip_zh":"f 是上齿咬下唇送气，sch 嘴唇撅圆。fr 的 r 是小舌音，不要在 f 和 r 之间加“呃”。先慢读 Fisch – frisch 对比，再加速。"},{"en":"Blaukraut bleibt Blaukraut und Brautkleid bleibt Brautkleid.","focus":"bl/br","zh":"紫甘蓝还是紫甘蓝，婚纱还是婚纱。","tip_zh":"bl 舌尖上抬，br 舌尖放下用小舌。Blau 和 Braut 交替出现，最容易串音，先每个词慢读三遍。"},{"en":"Zwischen zwei Zwetschgenzweigen sitzen zwei zwitschernde Schwalben.","focus":"zw/tsch","zh":"两根李子树枝之间坐着两只叽叽喳喳的燕子。","tip_zh":"zw 读 [tsv]：先发拼音 c 再上齿碰唇发 v。tsch 像汉语“吃”但嘴唇撅圆。Zwetschgen 一口气：tsvɛtʃɡn̩。"},{"en":"Zehn zahme Ziegen zogen zehn Zentner Zucker zum Zoo.","focus":"z [ts]","zh":"十只温顺的山羊把十担糖拉到动物园。","tip_zh":"每个 z 都是送气的 [ts]（拼音 c），别读成拼音 z。zogen 是 ziehen 的过去式，o 要长。"},{"en":"Hinter Hermann Hansens Haus hängen hundert Hemden raus.","focus":"h","zh":"赫尔曼·汉森家房子后面挂出一百件衬衫。","tip_zh":"德语 h 只是轻轻呼气，喉咙放松，不要像汉语“喝”那样舌根摩擦。raus = heraus，口语常用。"},{"en":"Acht alte Ameisen aßen am Abend Ananas.","focus":"喉塞音 a","zh":"八只老蚂蚁晚上吃菠萝。","tip_zh":"每个 a 开头的词前都要喉咙轻轻一卡（Knacklaut），不要连成 Achtalteameisen。Acht 的 ch 是喉咙深处的 [x]。"},{"en":"Wenn Fliegen hinter Fliegen fliegen, fliegen Fliegen Fliegen nach.","focus":"fl/ie","zh":"当苍蝇跟在苍蝇后面飞，苍蝇就追着苍蝇飞。","tip_zh":"ie 是长“衣”，要拉长。注意名词 Fliegen（苍蝇）和动词 fliegen（飞）读音一样，靠语调区分节奏。"},{"en":"Esel essen Nesseln nicht, Nesseln essen Esel nicht.","focus":"s/z, e","zh":"驴子不吃荨麻，荨麻也不吃驴子。","tip_zh":"Esel 的 s 在元音间读浊音 [z]，essen 和 Nesseln 的 ss 是清音 [s]。Esel 的 E 是长音，essen 的 e 是短音。"},{"en":"Bierbrauer Bauer braut braunes Bier.","focus":"b/br/au","zh":"酿酒师鲍尔酿黑啤酒。","tip_zh":"Bier 的 ie 长、r 弱化为 [ɐ]；braut / braun 的 au 从“啊”滑到“乌”。b 不送气，别读成 p。"},{"en":"Kleine Kinder können keine kleinen Kirschkerne knacken.","focus":"k/kn/kl","zh":"小孩子嗑不开小樱桃核。","tip_zh":"德语 kn 两个音都要读：k 和 n 都发出来，不像英语 knee 不读 k。können 的 ö 嘴唇要圆。"},{"en":"Der Cottbuser Postkutscher putzt den Cottbuser Postkutschkasten.","focus":"p/t/k, tsch","zh":"科特布斯的邮车车夫擦洗科特布斯的邮车车厢。","tip_zh":"p t k 在德语里送气很强，像拼音 p t k；tsch 像“吃”但撅嘴。Cottbuser 重音在第一音节。"},{"en":"Es klapperten die Klapperschlangen, bis ihre Klappern schlapper klangen.","focus":"kl/schl","zh":"响尾蛇一直咔嗒作响，直到它们的响声变得有气无力。","tip_zh":"kl 和 schl 交替出现：kl 舌根先堵再放，schl 撅嘴后舌尖上抬。-er 结尾读 [ɐ]：Klapper ≈ Klappa。"},{"en":"Wir Wiener Waschweiber würden weiße Wäsche waschen, wenn wir wüssten, wo warmes Wasser wär.","focus":"w [v]","zh":"要是我们知道哪里有热水，我们维也纳洗衣妇就会洗白衣服。","tip_zh":"所有 w 都读 [v]：上齿轻咬下唇、声带振动，绝不撅嘴。wär = wäre 的口语。注意 würden / wüssten 的 ü。"},{"en":"Max wachst Wachsmasken. Was wachst Max? Max wachst Wachsmasken.","focus":"chs [ks]","zh":"马克斯给蜡面具上蜡。马克斯在给什么上蜡？马克斯给蜡面具上蜡。","tip_zh":"chs 读 [ks]，和 x 一样：wachst [vakst]、Wachs [vaks]，这里不是 ach 的摩擦音。Max 和 wachst 押韵。"},{"en":"Schnecken erschrecken, wenn Schnecken an Schnecken schlecken, weil zum Schrecken vieler Schnecken Schnecken nicht schmecken.","focus":"sch/ck","zh":"蜗牛舔蜗牛时蜗牛会被吓到，因为让许多蜗牛害怕的是，蜗牛并不好吃。","tip_zh":"sch 撅嘴，ck 是短促的 k，前面的 e 短而开。最难的是 schm / schl / schr 三种组合，先分开练再连起来。"}],"topics":[{"id":"morning_routine","cat":"日常","level":"基础","q":"Wie sieht dein typischer Morgen aus?","qzh":"你平时早上是怎么过的？","points":["Wann du aufstehst","Was du als Erstes machst","Was du frühstückst","Werktag oder Wochenende"],"phrases":[["um sieben Uhr aufstehen","七点起床"],["als Erstes …","第一件事是……"],["den Wecker ausschalten","关掉闹钟"],["schnell duschen","快速冲个澡"],["sich für die Arbeit fertig machen","准备去上班"],["am Wochenende ist das anders","周末就不一样了"]],"sample":"Also, ich stehe meistens um sieben Uhr auf. Ehrlich gesagt schalte ich den Wecker oft zweimal aus. Als Erstes trinke ich ein Glas Wasser, und dann schaue ich auf mein Handy. Ich weiß, das ist keine gute Angewohnheit. Danach dusche ich schnell und frühstücke. Meistens esse ich Toast und trinke einen Kaffee. Manchmal gehe ich auch nach unten und esse Roti Canai. Wenn ich Zeit habe, mache ich zehn Minuten Stretching, denn ich sitze den ganzen Tag am Schreibtisch. Gegen halb neun mache ich mich für die Arbeit fertig. Am Wochenende ist das ganz anders: Da schlafe ich bis neun und mache alles langsam.","samplezh":"嗯，我一般七点起床。说实话，我经常要关两次闹钟。第一件事是喝一杯水，然后看手机。我知道这不是好习惯。之后我快速冲个澡，吃早饭。通常是吐司配咖啡。有时候我也会下楼吃个印度煎饼。有时间的话，我会拉伸十分钟，因为我整天都坐在桌前。八点半左右我准备去上班。周末就完全不一样了：我会睡到九点，什么都慢慢来。"},{"id":"weekend_plans","cat":"日常","level":"基础","q":"Was machst du normalerweise am Wochenende?","qzh":"你周末通常做什么？","points":["Wie du dich nach der Woche erholst","Was du erledigen musst","Was du mit Freunden machst","Dein ideales Wochenende"],"phrases":[["ausschlafen","睡懒觉"],["die Einkäufe erledigen","去买东西、办杂事"],["sich mit Freunden treffen","和朋友见面"],["zu Hause bleiben","待在家里"],["Das kommt darauf an.","那要看情况。"],["neue Energie tanken","充电、恢复精力"]],"sample":"Das kommt darauf an. Wenn die Woche sehr stressig war, bleibe ich gern zu Hause, schlafe aus und schaue eine Serie. Am Samstagvormittag erledige ich meistens die Einkäufe und wasche meine Wäsche. Das ist langweilig, aber es muss sein. Am Nachmittag oder am Abend treffe ich mich oft mit Freunden. Wir gehen in ein Einkaufszentrum oder sitzen stundenlang in einem Mamak-Restaurant und reden. Der Sonntag ist ruhiger. Ich koche etwas Einfaches und plane die nächste Woche. Mein ideales Wochenende wäre aber ein kurzer Ausflug, zum Beispiel ans Meer oder in die Cameron Highlands. So kann ich am besten neue Energie tanken.","samplezh":"这要看情况。如果那一周压力很大，我就喜欢待在家里，睡个懒觉，看看剧。周六上午我一般去买东西、洗衣服。很无聊，但不得不做。下午或晚上我常和朋友见面。我们去商场，或者在嘛嘛档坐上好几个小时聊天。周日比较安静。我会做点简单的饭，计划一下下周。不过我理想的周末是来一次短途旅行，比如去海边或者金马仑高原。这样我最能给自己充电。"},{"id":"favorite_food","cat":"日常","level":"基础","q":"Was isst du am liebsten und warum?","qzh":"你最喜欢吃什么？为什么？","points":["Dein Lieblingsessen","Wie es schmeckt","Wo oder wann du es isst","Ein Essen, das du nicht magst"],"phrases":[["Am liebsten esse ich …","我最喜欢吃……"],["Das schmeckt mir sehr gut.","我觉得很好吃。"],["ein bisschen scharf","有点辣"],["Das erinnert mich an …","这让我想起……"],["in der Nähe meines Büros","在我办公室附近"],["Ich bin kein Fan von …","我不太喜欢……"]],"sample":"Am liebsten esse ich Nudelsuppe, vor allem die Rindfleischnudeln aus meiner Heimat. Die Suppe ist ein bisschen scharf und sehr aromatisch. Das Essen erinnert mich an meine Familie, weil meine Mutter es oft am Wochenende gekocht hat. Hier in Kuala Lumpur gibt es auch gute Nudeln, aber sie schmecken anders. Ich esse sie meistens mittags in einem kleinen Restaurant in der Nähe meines Büros. Manchmal versuche ich, sie selbst zu kochen, aber das klappt nicht immer. Was ich nicht mag? Ehrlich gesagt bin ich kein Fan von sehr süßem Essen. Ein Stück Kuchen ist okay, aber mehr nicht.","samplezh":"我最喜欢吃汤面，尤其是我老家的牛肉面。汤有点辣，香味很浓。这道菜让我想起家人，因为我妈妈以前周末常做。吉隆坡也有好吃的面，但味道不一样。我一般中午在办公室附近的一家小餐馆吃。有时候我试着自己做，但不一定成功。我不喜欢吃什么？说实话，我不太喜欢很甜的东西。一块蛋糕还行，再多就不要了。"},{"id":"hometown","cat":"日常","level":"基础","q":"Erzähl mal von deiner Heimatstadt.","qzh":"说说你的家乡吧。","points":["Wo sie liegt und wie groß sie ist","Wofür sie bekannt ist","Was du vermisst","Wie oft du dorthin fliegst"],"phrases":[["Ich komme ursprünglich aus …","我老家是……"],["im Süden von China","在中国南方"],["eine mittelgroße Stadt","一座中等大小的城市"],["bekannt für …","以……出名"],["Am meisten vermisse ich …","我最想念的是……"],["einmal im Jahr","一年一次"]],"sample":"Ich komme ursprünglich aus einer mittelgroßen Stadt im Süden von China. Im Vergleich zu Shanghai oder Peking ist sie ziemlich klein, aber sie hat trotzdem ein paar Millionen Einwohner. Die Stadt ist vor allem für ihr Essen bekannt. Es gibt viele kleine Restaurants und Straßenstände, und das Frühstück dort ist einfach fantastisch. Im Sommer ist es sehr heiß und feucht, ein bisschen wie in Kuala Lumpur. Am meisten vermisse ich meine Eltern und meine alten Freunde. Und natürlich das Essen! Leider fliege ich nur einmal im Jahr nach Hause, meistens zum Frühlingsfest. Dann bleibe ich ungefähr zwei Wochen.","samplezh":"我老家是中国南方的一座中等城市。和上海、北京比起来它挺小的，不过也有几百万人口。这座城市最出名的是美食。有很多小饭馆和街边摊，那里的早餐简直太棒了。夏天很热很潮湿，有点像吉隆坡。我最想念的是我父母和老朋友。当然还有吃的！可惜我一年只飞回家一次，通常是过春节的时候。然后待两个星期左右。"},{"id":"sleep_habits","cat":"日常","level":"基础","q":"Schläfst du genug? Wie sind deine Schlafgewohnheiten?","qzh":"你睡得够吗？说说你的睡眠习惯。","points":["Wann du ins Bett gehst","Wie viele Stunden du schläfst","Was dich vom Schlafen abhält","Was dir beim Einschlafen hilft"],"phrases":[["ins Bett gehen","上床睡觉"],["einschlafen","入睡"],["Ich bin eine Nachteule.","我是个夜猫子。"],["bis spät in die Nacht","直到深夜"],["müde sein","累、困"],["das Handy weglegen","把手机放下"]],"sample":"Ehrlich gesagt schlafe ich nicht genug. Unter der Woche gehe ich meistens erst um Mitternacht ins Bett, manchmal sogar später. Ich bin eine Nachteule. Abends habe ich die besten Ideen, und dann programmiere ich oft bis spät in die Nacht. Außerdem schaue ich im Bett noch Videos auf dem Handy, und dann kann ich nicht einschlafen. Am nächsten Morgen bin ich natürlich müde und brauche zwei Tassen Kaffee. Am Wochenende schlafe ich dafür neun oder zehn Stunden. Seit ein paar Wochen versuche ich, das Handy um elf Uhr wegzulegen und ein Buch zu lesen. Das hilft wirklich, aber es ist nicht leicht.","samplezh":"说实话，我睡得不够。工作日我一般到半夜才上床，有时候更晚。我是个夜猫子。晚上我的点子最多，所以经常写代码写到深夜。另外我躺在床上还会用手机看视频，然后就睡不着。第二天早上当然很困，得喝两杯咖啡。不过周末我会睡九到十个小时。这几周我在尝试十一点放下手机，看一会儿书。这真的有用，但并不容易。"},{"id":"shopping_habits","cat":"日常","level":"基础","q":"Kaufst du lieber online oder im Geschäft ein?","qzh":"你更喜欢网购还是去实体店买？","points":["Was du online kaufst","Was du lieber im Laden kaufst","Vorteile und Nachteile","Ein Fehlkauf"],"phrases":[["online bestellen","网上下单"],["Das ist viel bequemer.","这方便多了。"],["etwas anprobieren","试穿某物"],["geliefert werden","被送货上门"],["günstiger sein","更便宜"],["etwas zurückschicken","把东西寄回去（退货）"]],"sample":"Meistens kaufe ich online ein, weil es viel bequemer ist. Ich bestelle fast alles über Apps wie Shopee oder Lazada: Elektronik, Haushaltssachen und sogar Lebensmittel. Die Sachen werden oft schon am nächsten Tag geliefert, und die Preise sind meistens günstiger. Kleidung und Schuhe kaufe ich aber lieber im Geschäft, weil ich sie anprobieren möchte. Einmal habe ich online eine Jacke bestellt, und sie war viel zu klein. Ich musste sie zurückschicken, und das war total kompliziert. Am Wochenende gehe ich trotzdem gern in ein Einkaufszentrum, nicht unbedingt zum Shoppen, sondern weil es dort eine Klimaanlage gibt!","samplezh":"我大多在网上买东西，因为方便多了。我几乎什么都在 Shopee 或 Lazada 这类应用上买：电子产品、家居用品，甚至食品。东西经常第二天就送到，价格一般也更便宜。不过衣服和鞋子我更喜欢去店里买，因为我想试穿。有一次我在网上买了一件外套，结果小太多了。我只好寄回去，过程超级麻烦。不过周末我还是喜欢去商场，不一定是为了购物，而是因为那里有空调！"},{"id":"phone_use","cat":"日常","level":"进阶","q":"Wie viel Zeit verbringst du am Handy, und wofür benutzt du es?","qzh":"你每天花多少时间在手机上？都用来做什么？","points":["Deine tägliche Bildschirmzeit","Die Apps, die du am meisten nutzt","Ob das ein Problem ist","Was du ändern möchtest"],"phrases":[["die Bildschirmzeit","屏幕使用时间"],["durch Social Media scrollen","刷社交媒体"],["Das ist mir ein bisschen peinlich.","这让我有点不好意思。"],["Plötzlich ist eine Stunde vorbei.","一个小时一下子就过去了。"],["die Benachrichtigungen ausschalten","关掉通知"],["Ich habe mir vorgenommen, …","我下定决心要……"]],"sample":"Wenn ich ehrlich bin, verbringe ich viel zu viel Zeit am Handy. Laut meiner Bildschirmzeit sind es ungefähr fünf Stunden pro Tag, und das ist mir ein bisschen peinlich. Natürlich brauche ich das Handy auch für wichtige Dinge: Ich bezahle damit, bestelle Essen über Grab und schreibe mit meiner Familie auf WeChat. Seit ein paar Monaten lerne ich auch Deutsch mit einer App. Das Problem ist das Scrollen durch Social Media, vor allem abends. Man will nur kurz etwas checken, und plötzlich ist eine Stunde vorbei. Deshalb habe ich mir vorgenommen, die Benachrichtigungen auszuschalten. Außerdem möchte ich am Wochenende öfter ohne Handy aus dem Haus gehen.","samplezh":"老实说，我花在手机上的时间太多了。屏幕使用时间显示大概每天五个小时，这让我有点不好意思。当然手机也有重要用途：我用它付钱、在 Grab 上点外卖、用微信和家人聊天。这几个月我还用一个应用学德语。问题是刷社交媒体，尤其是晚上。本来只想看一眼，结果一个小时一下子就过去了。所以我下定决心要把通知关掉。另外我想周末多一些不带手机出门。"},{"id":"your_job","cat":"工作","level":"基础","q":"Was machst du beruflich? Beschreib einen typischen Arbeitstag.","qzh":"你是做什么工作的？描述一下典型的一天。","points":["Dein Beruf und deine Firma","Wann du anfängst und aufhörst","Was du den ganzen Tag machst","Was dir gefällt"],"phrases":[["Ich arbeite als Softwareentwickler.","我是软件开发工程师。"],["bei einer kleinen Firma","在一家小公司"],["das Daily Meeting","每日站会"],["Fehler beheben","修复错误（修 bug）"],["Feierabend machen","下班"],["Die Arbeit macht mir Spaß.","我喜欢这份工作。"]],"sample":"Ich arbeite als Softwareentwickler bei einer kleinen IT-Firma in der Nähe des KLCC. Wir entwickeln Webseiten und Apps für unsere Kunden. Mein Arbeitstag beginnt meistens um halb zehn. Zuerst lese ich meine E-Mails und die Nachrichten im Team-Chat. Um zehn Uhr haben wir ein kurzes Daily Meeting, und jeder erzählt, woran er gerade arbeitet. Danach schreibe ich Code, teste neue Funktionen oder behebe Fehler. Mittags esse ich mit meinen Kollegen in einem Food Court. Am Nachmittag gibt es manchmal noch ein Meeting mit einem Kunden. Gegen sechs oder sieben mache ich Feierabend. Die Arbeit macht mir Spaß, weil ich jeden Tag etwas Neues lerne.","samplezh":"我在 KLCC 附近的一家小 IT 公司做软件开发。我们给客户做网站和应用。我的工作日一般九点半开始。先看邮件和团队群里的消息。十点我们开一个简短的站会，每个人说说自己正在做什么。之后我写代码、测试新功能或者修 bug。中午和同事在美食广场吃饭。下午有时还有一个客户会议。六七点左右下班。我喜欢这份工作，因为每天都能学到新东西。"},{"id":"working_from_home","cat":"工作","level":"基础","q":"Arbeitest du im Homeoffice? Wie ist das für dich?","qzh":"你在家办公吗？感觉怎么样？","points":["Wie oft du zu Hause arbeitest","Dein Arbeitsplatz zu Hause","Was dir gefällt","Was schwierig ist"],"phrases":[["im Homeoffice arbeiten","在家办公"],["zweimal pro Woche","每周两次"],["sich besser konzentrieren","更能集中注意力"],["den Arbeitsweg sparen","省下通勤时间"],["Mir fehlt der Kontakt zu …","我缺少和……的接触"],["Arbeit und Freizeit trennen","把工作和休息分开"]],"sample":"Ja, ich arbeite zweimal pro Woche im Homeoffice, meistens am Montag und am Freitag. In meiner Wohnung habe ich einen kleinen Schreibtisch am Fenster mit einem zweiten Bildschirm. Das Beste am Homeoffice ist, dass ich den Arbeitsweg spare. Ich muss nicht im Stau stehen und kann ein bisschen länger schlafen. Zu Hause kann ich mich auch besser konzentrieren, weil es ruhiger ist. Aber es gibt auch Nachteile. Mir fehlt manchmal der Kontakt zu meinen Kollegen, und es ist schwer, Arbeit und Freizeit zu trennen. Oft arbeite ich abends einfach weiter. Deshalb finde ich eine Mischung aus Büro und Homeoffice ideal.","samplezh":"是的，我每周在家办公两天，一般是周一和周五。我家里靠窗有一张小书桌，还配了第二块屏幕。在家办公最好的是省下了通勤时间。我不用堵在路上，还能多睡一会儿。在家我也更能集中注意力，因为比较安静。但也有缺点。我有时缺少和同事的接触，而且很难把工作和休息分开。我经常晚上还接着干活。所以我觉得办公室和在家结合最理想。"},{"id":"german_colleagues","cat":"工作","level":"基础","q":"Arbeitest du mit Leuten aus anderen Ländern zusammen? Wie läuft das?","qzh":"你和其他国家的人一起工作吗？合作得怎么样？","points":["Woher die Kollegen oder Kunden kommen","Wie ihr kommuniziert","Kulturelle Unterschiede","Warum Deutsch dir dabei hilft"],"phrases":[["ein Videocall","视频会议"],["die Zeitverschiebung","时差"],["Sie sind sehr pünktlich.","他们非常守时。"],["direkt sagen, was man denkt","直接说出自己的想法"],["Small Talk machen","闲聊几句"],["Am Anfang hat mich überrascht, …","一开始让我惊讶的是……"]],"sample":"Ja, wir haben seit letztem Jahr einen großen Kunden aus Deutschland, eine Firma in München. Wir haben fast jede Woche einen Videocall mit ihrem Team. Die Zeitverschiebung ist manchmal ein Problem: Wenn es bei uns vier Uhr nachmittags ist, ist es in Deutschland erst neun oder zehn Uhr morgens. Wir sprechen meistens Englisch, aber vor und nach dem Meeting reden die Kollegen untereinander Deutsch. Am Anfang hat mich überrascht, wie direkt sie sind. Sie sagen einfach, was sie denken, auch wenn etwas nicht gut ist. Und sie sind immer sehr pünktlich. Ich lerne Deutsch auch, weil ich sie besser verstehen und ein bisschen Small Talk machen möchte.","samplezh":"是的，从去年开始我们有一个德国的大客户，是慕尼黑的一家公司。我们几乎每周都和他们团队开视频会议。时差有时是个问题：我们这边下午四点，德国才早上九点或十点。我们一般说英语，但会议前后那边的同事之间会说德语。一开始让我惊讶的是他们有多直接。他们会直接说出自己的想法，哪怕是不好的地方。而且他们总是非常守时。我学德语也是因为想更好地听懂他们，能和他们闲聊几句。"},{"id":"proud_project","cat":"工作","level":"进阶","q":"Beschreib ein Projekt, auf das du stolz bist.","qzh":"说一个让你感到自豪的项目。","points":["Worum es in dem Projekt ging","Deine Rolle im Team","Ein Problem und wie ihr es gelöst habt","Was du dabei gelernt hast"],"phrases":[["Ich bin stolz auf …","我为……感到自豪"],["Es ging darum, dass …","这个项目是为了……"],["Ich war für … verantwortlich.","我负责……"],["unter Zeitdruck stehen","面临时间压力"],["Am Ende hat es geklappt.","最后成功了。"],["Dabei habe ich gelernt, dass …","在这个过程中我学到了……"]],"sample":"Ich bin besonders stolz auf eine Buchungs-App, die wir letztes Jahr für eine Kette von Fitnessstudios entwickelt haben. Es ging darum, dass die Mitglieder ihre Kurse online buchen können. Ich war für das Frontend verantwortlich, also für alles, was die Nutzer auf dem Bildschirm sehen. Das Projekt war nicht einfach, weil wir unter großem Zeitdruck standen. Zwei Wochen vor dem Start war die App plötzlich sehr langsam, und niemand wusste, warum. Wir haben dann drei Tage lang fast nur nach dem Fehler gesucht. Am Ende hat es geklappt, und heute benutzen Tausende Menschen die App. Dabei habe ich gelernt, dass man früh testen sollte und dass ein gutes Team wichtiger ist als perfekter Code.","samplezh":"我特别自豪的是去年我们给一家连锁健身房开发的预约应用。目的是让会员可以在线预约课程。我负责前端，也就是用户在屏幕上看到的所有东西。这个项目不容易，因为我们的时间压力很大。上线前两周，应用突然变得很慢，谁也不知道为什么。接下来三天我们几乎只在找这个问题。最后成功了，现在有好几千人在用这个应用。在这个过程中我学到了：要尽早测试，而且一个好团队比完美的代码更重要。"},{"id":"difficult_bug","cat":"工作","level":"进阶","q":"Erzähl von einem schwierigen Fehler oder Problem, das du lösen musstest.","qzh":"讲一个你不得不解决的棘手 bug 或问题。","points":["Was nicht funktioniert hat","Wie du nach der Ursache gesucht hast","Wie du es gelöst hast","Was du daraus gelernt hast"],"phrases":[["einen Fehler reproduzieren","复现一个错误"],["nur manchmal","只是偶尔"],["die Ursache","原因"],["Ich hatte keine Ahnung, was los war.","我完全不知道怎么回事。"],["Endlich habe ich gemerkt, dass …","最后我终于发现……"],["Das passiert mir nicht noch einmal.","这种事我不会再犯了。"]],"sample":"Vor ein paar Monaten hatten wir einen sehr seltsamen Fehler. Bei manchen Kunden wurden Bestellungen doppelt gespeichert, aber nur manchmal. Auf meinem Laptop hat alles perfekt funktioniert, deshalb hatte ich zuerst keine Ahnung, was los war. Ich habe zwei Tage lang die Logs gelesen und versucht, den Fehler zu reproduzieren. Endlich habe ich gemerkt, dass manche Nutzer bei schlechtem Internet zweimal auf den Button geklickt haben. Die Ursache war also ganz einfach, aber schwer zu finden. Wir haben den Button nach dem ersten Klick deaktiviert, und das Problem war gelöst. Seitdem teste ich meine Apps auch mit langsamem Internet. Das passiert mir nicht noch einmal!","samplezh":"几个月前我们遇到一个很奇怪的 bug。有些客户的订单被保存了两次，但只是偶尔。在我的笔记本上一切都完全正常，所以一开始我完全不知道怎么回事。我花了两天看日志，试着复现这个错误。最后我终于发现，有些用户在网络不好的时候点了两次按钮。所以原因其实很简单，只是很难找。我们让按钮在第一次点击后失效，问题就解决了。从那以后我也会在慢网速下测试我的应用。这种事我不会再犯了！"},{"id":"teamwork","cat":"工作","level":"进阶","q":"Arbeitest du lieber allein oder im Team? Warum?","qzh":"你更喜欢独自工作还是团队合作？为什么？","points":["Wann du lieber allein arbeitest","Vorteile von Teamarbeit","Ein Beispiel aus deinem Job","Was ein gutes Team ausmacht"],"phrases":[["Es hängt von der Aufgabe ab.","这取决于任务。"],["in Ruhe arbeiten","安安静静地工作"],["Vier Augen sehen mehr als zwei.","四只眼睛比两只看得多（两个人检查更保险）。"],["sich gegenseitig helfen","互相帮助"],["Meinungsverschiedenheiten","意见分歧"],["offen darüber sprechen","坦率地谈这件事"]],"sample":"Ich glaube, es hängt von der Aufgabe ab. Wenn ich programmiere, arbeite ich lieber allein und in Ruhe. Dann setze ich Kopfhörer auf und konzentriere mich ein paar Stunden. Aber für die Planung und für schwierige Probleme ist ein Team viel besser. Vier Augen sehen mehr als zwei, wie man auf Deutsch sagt. Zum Beispiel lesen meine Kollegen meinen Code, bevor wir ihn veröffentlichen, und sie finden oft Fehler, die ich übersehen habe. In unserem Team helfen wir uns gegenseitig, und das gefällt mir. Natürlich gibt es auch Meinungsverschiedenheiten, aber das ist normal. Wichtig ist, dass man offen darüber spricht und danach nicht beleidigt ist.","samplezh":"我觉得这取决于任务。写代码的时候，我更喜欢一个人安安静静地做。我会戴上耳机，专注几个小时。但做规划或者遇到难题时，团队就好多了。德语里有句话叫“四只眼睛比两只看得多”。比如同事会在发布前看我的代码，他们经常能发现我漏掉的错误。我们团队里大家互相帮助，我很喜欢这一点。当然也会有意见分歧，但这很正常。重要的是坦率地说出来，之后不要闹别扭。"},{"id":"career_plans","cat":"工作","level":"进阶","q":"Wo siehst du dich in fünf Jahren?","qzh":"你觉得五年后的自己会是什么样？","points":["Welche Position du dir wünschst","Was du noch lernen willst","Wo du leben möchtest","Welche Rolle Deutsch dabei spielt"],"phrases":[["in fünf Jahren","五年后"],["Ich könnte mir vorstellen, …","我可以考虑……"],["Erfahrung sammeln","积累经验"],["ein Team leiten","带领一个团队"],["im Ausland arbeiten","在国外工作"],["Mal sehen!","走着瞧吧！"]],"sample":"Das ist eine gute Frage. In fünf Jahren möchte ich auf jeden Fall noch in der IT arbeiten, aber vielleicht nicht mehr nur als Entwickler. Ich könnte mir vorstellen, ein kleines Team zu leiten. Dafür muss ich aber noch viel lernen, vor allem über Kommunikation und Projektmanagement. Im Moment sammle ich so viel Erfahrung wie möglich. Ein großer Traum von mir ist es, ein oder zwei Jahre in Deutschland zu arbeiten, zum Beispiel in Berlin oder München. Deshalb lerne ich ja Deutsch. Ich weiß, dass das nicht einfach wird, aber ich finde die Idee sehr spannend. Vielleicht bleibe ich aber auch in Kuala Lumpur. Mal sehen!","samplezh":"这是个好问题。五年后我肯定还想在 IT 行业，但也许不再只是做开发。我可以考虑带一个小团队。不过为此我还得学很多，特别是沟通和项目管理。现在我在尽可能多地积累经验。我的一个大梦想是在德国工作一两年，比如在柏林或者慕尼黑。这也是我学德语的原因。我知道这不容易，但我觉得这个想法很让人兴奋。当然，也可能我会留在吉隆坡。走着瞧吧！"},{"id":"why_kl","cat":"生活在马来西亚","level":"基础","q":"Warum bist du nach Kuala Lumpur gezogen?","qzh":"你为什么搬到吉隆坡？","points":["Wann du umgezogen bist","Der wichtigste Grund","Dein erster Eindruck","Ob du hier bleiben möchtest"],"phrases":[["nach Kuala Lumpur ziehen","搬到吉隆坡"],["vor ungefähr zwei Jahren","大约两年前"],["ein Jobangebot bekommen","得到一个工作机会"],["Mein erster Eindruck war …","我的第一印象是……"],["sich schnell eingewöhnen","很快适应"],["Ich fühle mich hier wohl.","我在这里感觉很自在。"]],"sample":"Ich bin vor ungefähr zwei Jahren nach Kuala Lumpur gezogen. Der wichtigste Grund war ein Jobangebot von meiner jetzigen Firma. Außerdem wollte ich gern einmal im Ausland leben und mein Englisch verbessern. Mein erster Eindruck war: Es ist heiß, sehr heiß! Aber die Stadt hat mir sofort gefallen. Sie ist modern und international, und das Essen ist fantastisch. Viele Leute sprechen Chinesisch, deshalb habe ich mich schnell eingewöhnt. Natürlich vermisse ich manchmal meine Familie, aber mit einem Videocall ist das kein großes Problem. Im Moment fühle ich mich hier sehr wohl und möchte noch ein paar Jahre bleiben.","samplezh":"我大约两年前搬到了吉隆坡。最主要的原因是现在这家公司给了我一个工作机会。另外我也想在国外生活一次，提高我的英语。我的第一印象是：热，太热了！不过我马上就喜欢上了这座城市。它很现代、很国际化，吃的也特别棒。很多人会说中文，所以我很快就适应了。当然有时候我会想家，但打个视频电话也就不是大问题了。现在我在这里感觉很自在，还想再待几年。"},{"id":"malaysian_food","cat":"生活在马来西亚","level":"基础","q":"Welches malaysische Essen magst du? Gibt es etwas, das du nicht magst?","qzh":"你喜欢哪些马来西亚食物？有没有不喜欢的？","points":["Dein Lieblingsgericht","Wo und wann du es isst","Etwas, das du nicht magst","Was Besucher probieren sollten"],"phrases":[["mein Lieblingsgericht","我最喜欢的菜"],["zu scharf für mich","对我来说太辣"],["Ich habe mich daran gewöhnt.","我已经习惯了。"],["ein Mamak-Restaurant","嘛嘛档（印度穆斯林餐馆）"],["Der Geruch ist zu stark.","气味太冲了。"],["Das muss man probiert haben.","这个一定得尝尝。"]],"sample":"Ich liebe malaysisches Essen! Mein Lieblingsgericht ist Nasi Lemak, also Reis mit Kokosmilch, dazu Sambal, Erdnüsse, ein Ei und manchmal Hähnchen. Am Anfang war das Sambal zu scharf für mich, aber inzwischen habe ich mich daran gewöhnt. Ich esse Nasi Lemak oft zum Frühstück in einem Mamak-Restaurant. Dort trinke ich auch einen Teh Tarik, das ist ein süßer Tee mit Milch. Was ich nicht so mag, ist Durian. Der Geruch ist einfach zu stark für mich, obwohl viele meiner Freunde total verrückt danach sind. Wenn Freunde aus Deutschland zu Besuch kommen, sage ich immer: Roti Canai und Char Kway Teow muss man probiert haben.","samplezh":"我超爱马来西亚菜！我最喜欢的是椰浆饭，就是用椰奶煮的米饭，配参巴辣酱、花生、鸡蛋，有时还有鸡肉。一开始参巴对我来说太辣了，不过现在已经习惯了。我常在嘛嘛档吃椰浆饭当早餐。在那里我还会喝一杯拉茶，就是加奶的甜茶。我不太喜欢的是榴莲。那个味道对我来说太冲了，虽然我很多朋友都爱得不得了。德国朋友来玩的时候，我总会说：印度煎饼和炒粿条一定得尝尝。"},{"id":"weather","cat":"生活在马来西亚","level":"基础","q":"Wie ist das Wetter in Kuala Lumpur? Gefällt es dir?","qzh":"吉隆坡的天气怎么样？你喜欢吗？","points":["Temperatur und Luftfeuchtigkeit","Regen und Gewitter","Was du bei dem Wetter machst","Vergleich mit deiner Heimat oder Deutschland"],"phrases":[["Es ist heiß und feucht.","又热又潮湿。"],["Es regnet in Strömen.","下着倾盆大雨。"],["ein Gewitter","雷阵雨"],["einen Regenschirm dabeihaben","随身带着伞"],["Es gibt keine Jahreszeiten.","没有四季之分。"],["Ich schwitze sofort.","我马上就出汗。"]],"sample":"In Kuala Lumpur ist es das ganze Jahr heiß und feucht, meistens über dreißig Grad. Es gibt eigentlich keine Jahreszeiten wie in China oder in Deutschland. Am Nachmittag gibt es oft ein Gewitter, und dann regnet es in Strömen. Deshalb habe ich immer einen Regenschirm dabei. Nach einer Stunde ist meistens alles vorbei, und die Sonne scheint wieder. Ehrlich gesagt mag ich das Wetter nicht so sehr. Draußen schwitze ich sofort, und drinnen ist die Klimaanlage oft viel zu kalt. Manchmal vermisse ich den Winter und die kühle Luft. Aber ich freue mich jeden Tag, dass ich keine dicke Jacke brauche!","samplezh":"吉隆坡一年到头都又热又潮湿，一般在三十度以上。其实没有像中国或德国那样的四季。下午经常有雷阵雨，下起来就是倾盆大雨。所以我总是随身带着伞。通常一个小时后就停了，太阳又出来了。说实话，我不太喜欢这种天气。在外面我马上就出汗，室内空调又常常太冷。有时候我会想念冬天和凉爽的空气。不过每天不用穿厚外套，我也挺开心的！"},{"id":"traffic_transport","cat":"生活在马来西亚","level":"进阶","q":"Wie kommst du in der Stadt von A nach B? Wie ist der Verkehr?","qzh":"你在城里怎么出行？交通怎么样？","points":["Welche Verkehrsmittel du benutzt","Wie lange du zur Arbeit brauchst","Der Stau zur Hauptverkehrszeit","Vergleich mit anderen Städten"],"phrases":[["mit der U-Bahn fahren","坐地铁"],["im Stau stehen","堵在路上"],["zur Hauptverkehrszeit","在高峰时段"],["ein Auto über Grab bestellen","用 Grab 叫车"],["Ich brauche ungefähr … Minuten.","我大概需要……分钟。"],["zu Fuß gehen","步行"]],"sample":"Meistens fahre ich mit der U-Bahn, also mit der MRT oder der LRT. Von meiner Wohnung bis zum Büro brauche ich ungefähr dreißig Minuten, und das ist eigentlich ganz okay. Abends oder wenn es regnet, bestelle ich oft ein Auto über Grab. Das ist bequem und nicht teuer, aber zur Hauptverkehrszeit steht man oft lange im Stau. Ich habe kein Auto, und ehrlich gesagt brauche ich auch keins. Ein Problem in Kuala Lumpur ist, dass man nicht so gut zu Fuß gehen kann. Es ist heiß, und manche Gehwege sind schlecht oder hören plötzlich auf. In deutschen Städten fahren viele Leute Fahrrad. Das kann ich mir hier im Moment noch nicht so gut vorstellen.","samplezh":"我大多坐地铁，也就是 MRT 或 LRT。从我家到办公室大概三十分钟，其实还行。晚上或者下雨的时候，我常叫 Grab。很方便也不贵，但高峰时段经常要堵很久。我没有车，说实话也不需要。吉隆坡的一个问题是不太适合步行。天气热，有些人行道很差，或者走着走着突然就没了。在德国的城市，很多人骑自行车。目前我还很难想象在这里这么做。"},{"id":"cost_of_living","cat":"生活在马来西亚","level":"进阶","q":"Ist das Leben in Kuala Lumpur teuer?","qzh":"在吉隆坡生活贵吗？","points":["Die Miete","Essen und Transport","Was teuer und was günstig ist","Vergleich mit China oder Deutschland"],"phrases":[["die Lebenshaltungskosten","生活成本"],["die Miete","房租"],["im Vergleich zu …","和……相比"],["Das ist ziemlich günstig.","这挺便宜的。"],["importierte Sachen","进口商品"],["Man kann gut davon leben.","靠这些能过得不错。"]],"sample":"Im Vergleich zu Städten wie Shanghai oder München sind die Lebenshaltungskosten in Kuala Lumpur ziemlich niedrig. Für meine Wohnung mit einem Schlafzimmer zahle ich ungefähr zweitausend Ringgit Miete im Monat. Dafür gibt es sogar einen Pool und ein Fitnessstudio im Gebäude. Essen ist günstig, wenn man in einem Food Court oder in einem Mamak-Restaurant isst. Ein Teller Nasi Lemak kostet oft nur ein paar Ringgit. Teuer sind aber importierte Sachen, zum Beispiel Käse, Wein oder Elektronik. Auch Autos sind hier relativ teuer. Insgesamt finde ich, dass man mit einem normalen IT-Gehalt in Kuala Lumpur gut leben kann. Man kann sogar etwas sparen.","samplezh":"和上海或慕尼黑这样的城市比，吉隆坡的生活成本挺低的。我住的一居室，每月房租大概两千令吉。而且楼里还有泳池和健身房。如果在美食广场或嘛嘛档吃饭，吃得很便宜。一盘椰浆饭常常只要几令吉。但进口商品很贵，比如奶酪、葡萄酒或者电子产品。车在这里也相对贵。总的来说，我觉得拿一份普通的 IT 工资在吉隆坡能过得不错，甚至还能存点钱。"},{"id":"festivals","cat":"生活在马来西亚","level":"基础","q":"Welche Feste feiert man in Malaysia? Welches gefällt dir am besten?","qzh":"马来西亚有哪些节日？你最喜欢哪一个？","points":["Die wichtigsten Feste","Was man dabei macht","Dein Lieblingsfest","Wie du feierst"],"phrases":[["das chinesische Neujahr","农历新年"],["ein Feiertag","一个公共假日"],["Gäste zu sich nach Hause einladen","邀请客人到家里"],["rote Umschläge","红包"],["Mein Lieblingsfest ist …","我最喜欢的节日是……"],["egal, woher man kommt","不管来自哪里"]],"sample":"In Malaysia gibt es viele Feste, weil hier verschiedene Kulturen zusammenleben. Die wichtigsten sind das chinesische Neujahr, Hari Raya und Deepavali. Zu Hari Raya laden viele Malaien Freunde und Nachbarn zu sich nach Hause ein, und es gibt sehr viel Essen. Deepavali ist das Lichterfest der Hindus. Mein Lieblingsfest ist natürlich das chinesische Neujahr. Dann hängen überall rote Laternen, es gibt Löwentänze, und man bekommt rote Umschläge mit Geld. Meistens fliege ich zu meiner Familie nach China. Wenn ich hierbleibe, feiere ich mit Freunden, und wir essen zusammen Yee Sang. Besonders schön finde ich, dass man hier zusammen feiert, egal, woher man kommt.","samplezh":"马来西亚的节日很多，因为这里有不同的文化共同生活。最重要的是农历新年、开斋节和屠妖节。开斋节时，很多马来人会邀请朋友和邻居到家里，准备很多吃的。屠妖节是印度教徒的灯节。我最喜欢的当然是农历新年。那时到处挂着红灯笼，有舞狮，还能收到装着钱的红包。我一般会飞回中国和家人一起过。如果留在这里，我就和朋友一起过，一起吃捞生。我特别喜欢的是，在这里大家一起过节，不管来自哪里。"},{"id":"language_mix","cat":"生活在马来西亚","level":"进阶","q":"In Malaysia mischen viele Leute mehrere Sprachen. Was denkst du darüber?","qzh":"在马来西亚很多人混着说几种语言。你怎么看？","points":["Welche Sprachen man hört","Ein typisches Beispiel","Vorteile und Nachteile","Wie das bei dir ist"],"phrases":[["Sprachen mischen","混用多种语言"],["mitten im Satz","在一句话中间"],["Am Anfang war das verwirrend.","一开始这很让人困惑。"],["Das Wort passt am besten.","这个词最贴切。"],["ohne es zu merken","不知不觉地"],["Ich mache das inzwischen auch.","我现在也这么做了。"]],"sample":"In Kuala Lumpur hört man den ganzen Tag Englisch, Malaiisch, Mandarin, Kantonesisch und Tamil. Viele Leute mischen diese Sprachen sogar mitten im Satz. Ein Kollege sagt zum Beispiel: „Can or not? Jom makan dulu!“ Das nennt man oft Manglish. Am Anfang war das ziemlich verwirrend für mich. Aber inzwischen finde ich es praktisch und auch ein bisschen lustig. Man nimmt einfach das Wort, das am besten passt. Für Besucher ist es vielleicht schwer zu verstehen, das ist ein Nachteil. Ehrlich gesagt mache ich das inzwischen auch. Ich sage oft „lah“ am Ende eines Satzes, ohne es zu merken. Und jetzt kommt noch Deutsch dazu!","samplezh":"在吉隆坡，一整天都能听到英语、马来语、普通话、粤语和泰米尔语。很多人甚至在一句话中间混着说。比如有个同事会说：“Can or not? Jom makan dulu!”（行不行？先去吃饭吧！）这常被叫作 Manglish。一开始我很困惑。不过现在我觉得这很实用，也有点好玩。哪个词最贴切就用哪个。对外地人来说可能很难听懂，这算是个缺点。说实话，我现在也这样了。我常常不知不觉在句尾加个“lah”。现在还要再加上德语！"},{"id":"best_trip","cat":"旅行","level":"基础","q":"Beschreib die schönste Reise, die du je gemacht hast.","qzh":"描述一下你经历过的最棒的一次旅行。","points":["Wohin und wann","Mit wem du gereist bist","Was ihr gemacht habt","Warum sie so besonders war"],"phrases":[["eine Reise machen","去旅行"],["durch das Land reisen","在这个国家各地旅行"],["Wir haben … besichtigt.","我们参观了……"],["in einem Hotel übernachten","在酒店过夜"],["Das war unvergesslich.","那真是难忘。"],["Ich würde sofort wieder hinfahren.","我会马上再去一次。"]],"sample":"Meine schönste Reise ging vor einem Jahr nach Japan. Ich bin mit zwei Freunden zehn Tage lang durch das Land gereist. Zuerst waren wir in Tokio. Die Stadt ist riesig, aber sehr sauber und ordentlich. Dann sind wir mit dem Schnellzug nach Kyoto gefahren und haben viele alte Tempel besichtigt. Das Essen war überall fantastisch, vor allem die Ramen. Besonders schön war ein Tag in den Bergen. Wir haben in einem traditionellen Hotel übernachtet und in heißen Quellen gebadet. Das war unvergesslich. Am meisten hat mich beeindruckt, wie freundlich und höflich die Menschen sind. Ich würde sofort wieder hinfahren!","samplezh":"我最棒的一次旅行是一年前去日本。我和两个朋友在日本各地玩了十天。我们先去了东京。城市很大，但非常干净、井井有条。然后我们坐新干线去了京都，参观了很多古老的寺庙。到处的东西都超好吃，尤其是拉面。特别美好的是在山里的一天。我们住在一家传统旅馆，还泡了温泉。那真是难忘。最让我印象深刻的是那里的人非常友好、有礼貌。我会马上再去一次！"},{"id":"dream_destination","cat":"旅行","level":"基础","q":"Wenn du überall hinreisen könntest, wohin würdest du fahren?","qzh":"如果你可以去任何地方旅行，你会去哪里？","points":["Dein Traumziel","Warum du dorthin willst","Was du dort machen möchtest","Mit wem du reisen würdest"],"phrases":[["mein Traumziel","我梦想的目的地"],["Ich würde gern …","我很想……"],["mit dem Zug durchs Land fahren","坐火车游遍全国"],["durch die Altstadt spazieren","在老城区散步"],["einen Weihnachtsmarkt besuchen","逛圣诞市集"],["Ich spare schon dafür.","我已经在为此存钱了。"]],"sample":"Mein Traumziel ist im Moment Deutschland, das ist ja klar! Ich würde gern im Herbst fahren, wenn es nicht zu heiß und nicht zu kalt ist. Zuerst würde ich nach Berlin fliegen, weil mich die Geschichte der Stadt sehr interessiert. Danach würde ich mit dem Zug durchs Land fahren, zum Beispiel nach Dresden, Heidelberg und München. Ich möchte durch die Altstädte spazieren, Brezeln essen und natürlich mein Deutsch benutzen. Am liebsten würde ich auch einen Weihnachtsmarkt besuchen, aber dann müsste ich im Dezember fahren. Vielleicht reise ich mit meinem besten Freund, denn er interessiert sich auch für Europa. Ich spare schon dafür!","samplezh":"我现在梦想的目的地当然是德国！我想秋天去，那时候不太热也不太冷。我会先飞到柏林，因为我对这座城市的历史很感兴趣。然后坐火车到各地去，比如德累斯顿、海德堡和慕尼黑。我想在老城区散步，吃椒盐卷饼，当然还要用用我的德语。我也很想逛圣诞市集，不过那样就得十二月去了。也许我会和我最好的朋友一起去，因为他也对欧洲感兴趣。我已经在为此存钱了！"},{"id":"travel_tips","cat":"旅行","level":"进阶","q":"Welche Tipps würdest du jemandem geben, der eine Reise ins Ausland plant?","qzh":"你会给计划出国旅行的人什么建议？","points":["Vorbereitung und Dokumente","Geld und Handy","Sprache und Kultur","Ein Fehler, den man vermeiden sollte"],"phrases":[["rechtzeitig buchen","提早预订"],["Man sollte …","应该……"],["eine Reiseversicherung abschließen","买旅行保险"],["etwas Bargeld dabeihaben","随身带点现金"],["ein paar Wörter in der Landessprache","几句当地语言"],["Es lohnt sich.","值得。"]],"sample":"Mein wichtigster Tipp ist: Man sollte Flüge und Hotels rechtzeitig buchen, dann ist es viel günstiger. Außerdem sollte man prüfen, ob man ein Visum braucht. Das habe ich einmal fast vergessen. Ich würde auch immer eine Reiseversicherung abschließen, falls man krank wird. Für das Handy kaufe ich meistens eine eSIM, dann habe ich sofort Internet. In manchen Ländern, zum Beispiel in Deutschland, sollte man auch etwas Bargeld dabeihaben, weil man nicht überall mit Karte bezahlen kann. Und es lohnt sich wirklich, ein paar Wörter in der Landessprache zu lernen, zum Beispiel „Danke“ und „Entschuldigung“. Die Leute freuen sich darüber, und man fühlt sich nicht so fremd.","samplezh":"我最重要的建议是：机票和酒店要提早订，这样便宜很多。另外要查一下需不需要签证。这个我有一次差点忘了。我也一定会买旅行保险，以防生病。手机方面我一般买一张 eSIM，这样马上就能上网。在有些国家，比如德国，最好随身带点现金，因为不是到处都能刷卡。还有，学几句当地语言真的很值得，比如“谢谢”和“对不起”。当地人会很高兴，自己也不会觉得那么陌生。"},{"id":"travel_problem","cat":"旅行","level":"进阶","q":"Hattest du schon einmal ein Problem auf einer Reise? Was ist passiert?","qzh":"你旅行时遇到过问题吗？发生了什么？","points":["Wo und wann es passiert ist","Was genau schiefgegangen ist","Wie du reagiert hast","Wie die Geschichte ausgegangen ist"],"phrases":[["Es ist etwas Dummes passiert.","发生了一件蠢事。"],["Der Check-in war schon geschlossen.","值机已经关闭了。"],["auf einen späteren Flug umbuchen","改签到晚一点的航班"],["zum Glück","幸好"],["mit fünf Stunden Verspätung","晚了五个小时"],["Im Nachhinein ist das lustig.","事后看挺好笑的。"]],"sample":"Ja, auf meiner Reise nach Bangkok ist etwas Dummes passiert. Ich bin ganz entspannt zum Flughafen gefahren, aber am Schalter hat man mir gesagt, dass der Check-in schon geschlossen war. Ich hatte die Abflugzeit falsch gelesen! Ich war total gestresst, weil meine Freunde schon in Bangkok auf mich gewartet haben. Zum Glück war die Mitarbeiterin sehr nett. Sie hat mich auf einen späteren Flug umgebucht, aber ich musste natürlich extra bezahlen. Am Ende bin ich mit fünf Stunden Verspätung angekommen, und wir hatten trotzdem einen schönen Abend. Im Nachhinein ist das ziemlich lustig, aber seitdem kontrolliere ich alles zweimal.","samplezh":"有过，去曼谷的时候发生了一件蠢事。我悠哉悠哉地去了机场，结果柜台的人告诉我值机已经关闭了。我把起飞时间看错了！我压力超大，因为朋友们已经在曼谷等我了。幸好那位工作人员很好。她帮我改签到晚一点的航班，不过我当然得补钱。最后我晚了五个小时才到，但我们还是度过了一个愉快的晚上。事后看挺好笑的，不过从那以后我什么都要检查两遍。"},{"id":"solo_vs_group","cat":"旅行","level":"进阶","q":"Reist du lieber allein oder mit anderen Leuten?","qzh":"你更喜欢一个人旅行还是和别人一起？","points":["Vorteile vom Alleinreisen","Vorteile vom Reisen mit Freunden","Deine Erfahrungen","Was du beim nächsten Mal machst"],"phrases":[["allein reisen","独自旅行"],["total flexibel sein","非常自由灵活"],["neue Leute kennenlernen","认识新朋友"],["sich die Kosten teilen","分摊费用"],["Kompromisse machen","互相妥协"],["sich einsam fühlen","感到孤单"]],"sample":"Ich habe beides schon ausprobiert, und beides hat Vorteile. Wenn ich allein reise, bin ich total flexibel. Ich kann aufstehen, wann ich will, und den ganzen Tag in Museen verbringen, ohne dass sich jemand langweilt. Außerdem lernt man allein viel leichter neue Leute kennen, zum Beispiel im Hostel. Aber abends beim Essen fühle ich mich manchmal ein bisschen einsam. Mit Freunden zu reisen macht mehr Spaß, und man kann sich die Kosten für Hotel und Taxi teilen. Dafür muss man oft Kompromisse machen. Einer will an den Strand, der andere will shoppen. Für meine Deutschlandreise wünsche ich mir eine Mischung: eine Woche allein und eine Woche mit einem Freund.","samplezh":"两种我都试过，各有好处。一个人旅行时我非常自由。想几点起就几点起，可以整天待在博物馆里，不用担心有人觉得无聊。而且一个人更容易认识新朋友，比如在青旅里。但晚上吃饭的时候，我有时会觉得有点孤单。和朋友一起旅行更好玩，酒店和打车的费用也能分摊。不过就经常要互相妥协。一个想去海边，另一个想去购物。我的德国之行希望两者结合：一周自己玩，一周和一个朋友一起。"},{"id":"beach_vs_city","cat":"旅行","level":"基础","q":"Was magst du im Urlaub lieber: Strand oder Stadt?","qzh":"度假你更喜欢海边还是城市？","points":["Was du am Strand machst","Was du in einer Stadt machst","Dein letzter Urlaub","Deine Wahl und warum"],"phrases":[["am Strand liegen","躺在海滩上"],["im Meer schwimmen","在海里游泳"],["einfach mal abschalten","彻底放空一下"],["Mir wird schnell langweilig.","我很快就觉得无聊。"],["eine Stadt erkunden","探索一座城市"],["die perfekte Mischung","完美的结合"]],"sample":"Ich glaube, ich bin eher ein Stadtmensch. Natürlich ist es schön, am Strand zu liegen und im Meer zu schwimmen, zum Beispiel auf Langkawi. Dort kann ich einfach mal abschalten. Aber nach zwei Tagen wird mir schnell langweilig. In einer Stadt gibt es immer etwas zu tun. Ich erkunde gern neue Viertel, besuche Museen und probiere das Essen auf den Märkten. Mein letzter Urlaub war in Penang, und das war die perfekte Mischung: In George Town gibt es alte Häuser, Street Art und unglaublich gutes Essen, und der Strand ist auch nicht weit. Also, wenn ich wählen muss: lieber Stadt, aber mit einem Strand in der Nähe!","samplezh":"我觉得我更像是个城市型的人。当然，躺在海滩上、在海里游泳很舒服，比如在兰卡威。在那里我可以彻底放空一下。但两天以后我很快就觉得无聊了。城市里总有事情可做。我喜欢探索新的街区，逛博物馆，尝尝市场上的小吃。我上次度假是在槟城，那就是完美的结合：乔治市有老房子、街头艺术和好吃得不得了的东西，海滩也不远。所以如果一定要选：我选城市，但最好附近有海滩！"},{"id":"free_time","cat":"兴趣","level":"基础","q":"Was machst du in deiner Freizeit?","qzh":"你空闲时间做什么？","points":["Deine Hobbys","Wie oft du sie machst","Mit wem","Ein neues Hobby, das du ausprobieren möchtest"],"phrases":[["in meiner Freizeit","在我的空闲时间"],["Ich gehe gern wandern.","我喜欢去徒步。"],["neue Restaurants ausprobieren","尝试新餐厅"],["einmal im Monat","每月一次"],["Ich interessiere mich für …","我对……感兴趣"],["Ich habe vor, …","我打算……"]],"sample":"In meiner Freizeit gehe ich gern wandern. In der Nähe von Kuala Lumpur gibt es viele schöne Wanderwege, zum Beispiel am Broga Hill. Dort sieht man morgens den Sonnenaufgang. Meistens wandere ich einmal im Monat mit ein paar Kollegen. Außerdem probiere ich gern neue Restaurants aus. Ich mache Fotos vom Essen und schreibe kurze Bewertungen. Abends schaue ich viele YouTube-Videos, meistens über Technik und Reisen. Seit ein paar Monaten lerne ich auch Deutsch, und das ist fast ein Hobby geworden. Ich habe vor, im nächsten Jahr Gitarre spielen zu lernen, weil ich mich schon lange für Musik interessiere. Mal sehen, ob ich genug Zeit habe!","samplezh":"空闲时间我喜欢去徒步。吉隆坡附近有很多漂亮的徒步路线，比如武来岸山（Broga Hill）。早上在那里能看日出。我一般每月和几个同事去爬一次。另外我喜欢尝试新餐厅。我会给菜拍照，写写简短的点评。晚上我看很多 YouTube 视频，主要是科技和旅行类的。这几个月我还在学德语，它差不多已经成了一个爱好。我打算明年学弹吉他，因为我一直对音乐很感兴趣。看看我有没有足够的时间吧！"},{"id":"fitness","cat":"兴趣","level":"基础","q":"Was machst du, um fit und gesund zu bleiben?","qzh":"你怎么保持身体健康？","points":["Welchen Sport du machst","Wie oft","Was du isst","Was schwierig ist"],"phrases":[["Sport machen","运动"],["ins Fitnessstudio gehen","去健身房"],["joggen gehen","去慢跑"],["sich gesund ernähren","健康饮食"],["Ich versuche, …","我尽量……"],["Mir fehlt die Motivation.","我缺乏动力。"]],"sample":"Ich versuche, dreimal pro Woche Sport zu machen. In meinem Wohnhaus gibt es ein kleines Fitnessstudio, deshalb gehe ich meistens abends nach der Arbeit dorthin. Am Wochenende gehe ich manchmal im Park joggen, aber nur früh am Morgen, weil es später zu heiß ist. Beim Essen ist es schwieriger. Das Essen in Malaysia ist so lecker, aber oft sehr fettig und süß. Ich versuche, mich gesund zu ernähren, und koche zweimal pro Woche selbst. Und ich trinke weniger Bubble Tea als früher! Ehrlich gesagt fehlt mir manchmal die Motivation, vor allem nach einem langen Arbeitstag. Dann hilft es, wenn ich mit einem Freund trainiere.","samplezh":"我尽量每周运动三次。我住的楼里有个小健身房，所以我一般下班后晚上去那里。周末有时去公园慢跑，但只在清早，因为晚一点就太热了。吃的方面更难。马来西亚的东西太好吃了，但经常又油又甜。我尽量健康饮食，每周自己做两次饭。而且我奶茶喝得比以前少了！说实话，我有时候缺乏动力，尤其是工作了一整天之后。这时候和朋友一起练会有帮助。"},{"id":"movie_show","cat":"兴趣","level":"基础","q":"Erzähl von einem Film oder einer Serie, die dir sehr gut gefallen hat.","qzh":"说说一部你非常喜欢的电影或剧。","points":["Wie der Film oder die Serie heißt","Worum es geht","Was dir besonders gefallen hat","Wem du sie empfehlen würdest"],"phrases":[["Es geht um …","讲的是……"],["unglaublich spannend","特别扣人心弦"],["eine Staffel an einem Wochenende schauen","一个周末看完一季"],["mit Untertiteln","带字幕"],["wissen wollen, wie es weitergeht","想知道接下来怎样"],["Ich kann sie nur empfehlen.","我非常推荐。"]],"sample":"Eine Serie, die mir sehr gut gefallen hat, ist „Dark“. Das ist eine deutsche Serie auf Netflix. Es geht um eine kleine Stadt, in der Kinder verschwinden, und um Zeitreisen. Die Geschichte ist sehr kompliziert, aber unglaublich spannend. Ich habe die erste Staffel an einem Wochenende geschaut, weil ich immer wissen wollte, wie es weitergeht. Am Anfang habe ich sie mit englischen Untertiteln gesehen. Jetzt schaue ich sie noch einmal auf Deutsch mit deutschen Untertiteln, um mein Hörverstehen zu trainieren. Ich verstehe noch nicht alles, aber jedes Mal ein bisschen mehr. Wer Science-Fiction mag, dem kann ich sie nur empfehlen.","samplezh":"我很喜欢的一部剧是《暗黑》。这是 Netflix 上的一部德国剧。讲的是一个有孩子失踪的小镇，还有时间旅行。故事很复杂，但特别扣人心弦。第一季我一个周末就看完了，因为总想知道接下来会怎样。一开始我看的是英文字幕。现在我用德语配音加德语字幕重看一遍，来练听力。我还不能全听懂，但每次都多懂一点。喜欢科幻的人，我非常推荐。"},{"id":"music","cat":"兴趣","level":"基础","q":"Was für Musik hörst du gern?","qzh":"你喜欢听什么音乐？","points":["Deine Lieblingsmusik","Wann du Musik hörst","Eine Sängerin, ein Sänger oder eine Band","Musik auf Deutsch"],"phrases":[["Ich höre gern …","我喜欢听……"],["beim Arbeiten","工作的时候"],["Kopfhörer aufsetzen","戴上耳机"],["eine Playlist","播放列表"],["Das bringt mich in gute Laune.","这让我心情变好。"],["ins Konzert gehen","去听演唱会"]],"sample":"Ich höre eigentlich fast alles, aber am liebsten Pop und ruhige Musik ohne Gesang. Beim Arbeiten setze ich oft Kopfhörer auf und höre Lo-Fi oder Klaviermusik. Dann kann ich mich besser konzentrieren. Beim Sport brauche ich dagegen schnelle Musik, die mich in gute Laune bringt. Auf dem Weg zur Arbeit höre ich oft chinesische Popsongs, weil sie mich an meine Jugend erinnern. Seit ich Deutsch lerne, habe ich auch eine Playlist mit deutschen Liedern. Eine Kollegin aus München hat mir die Band Silbermond empfohlen. Ich verstehe noch nicht alle Texte, aber ich singe manchmal mit. Ins Konzert gehe ich leider selten, weil die Tickets so teuer sind.","samplezh":"其实我几乎什么都听，但最喜欢流行乐和没有人声的轻音乐。工作时我常戴上耳机听 Lo-Fi 或钢琴曲。这样我更能集中注意力。运动时则需要节奏快、让我心情变好的音乐。上班路上我常听中文流行歌，因为它们让我想起青春时代。自从学德语以后，我也建了一个德语歌的播放列表。一位慕尼黑的女同事给我推荐了 Silbermond 乐队。歌词我还没全听懂，但有时会跟着唱。可惜我很少去听演唱会，因为票太贵了。"},{"id":"cooking","cat":"兴趣","level":"基础","q":"Kochst du gern? Was kannst du kochen?","qzh":"你喜欢做饭吗？你会做什么？","points":["Wie oft du kochst","Was du kochen kannst","Ein Gericht, das dir gut gelingt","Etwas, das schiefgegangen ist"],"phrases":[["selbst kochen","自己做饭"],["Essen bestellen","点外卖"],["Tomaten mit Rührei","西红柿炒鸡蛋"],["das Rezept","菜谱"],["Der Kuchen ist angebrannt.","蛋糕烤糊了。"],["Übung macht den Meister.","熟能生巧。"]],"sample":"Ja, ich koche gern, aber leider nicht sehr oft. Unter der Woche habe ich wenig Zeit, deshalb bestelle ich meistens Essen. Am Wochenende koche ich aber gern selbst. Ich kann vor allem einfache chinesische Gerichte kochen, zum Beispiel Tomaten mit Rührei oder gebratenen Reis. Mein bestes Gericht ist Mapo-Tofu. Das Rezept habe ich von meiner Mutter, und meine Freunde sind immer begeistert. Einmal wollte ich für meine Kollegen einen deutschen Apfelkuchen backen. Leider war der Ofen zu heiß, und der Kuchen ist angebrannt. Wir haben trotzdem gelacht und dann Pizza bestellt. Aber ich gebe nicht auf. Übung macht den Meister!","samplezh":"喜欢，我喜欢做饭，可惜做得不多。工作日时间少，所以我大多点外卖。不过周末我喜欢自己做。我主要会做简单的中国菜，比如西红柿炒鸡蛋或者炒饭。我的拿手菜是麻婆豆腐。菜谱是我妈妈教的，朋友们每次都赞不绝口。有一次我想给同事烤一个德国苹果蛋糕。可惜烤箱太热，蛋糕烤糊了。我们还是笑了一场，然后点了披萨。但我不会放弃。熟能生巧嘛！"},{"id":"book_youtube","cat":"兴趣","level":"进阶","q":"Erzähl von einem Buch oder einem YouTube-Kanal, der dich beeinflusst hat.","qzh":"说说一本影响过你的书或一个 YouTube 频道。","points":["Was für ein Buch oder Kanal es ist","Worum es geht","Was du davon gelernt hast","Was sich in deinem Leben geändert hat"],"phrases":[["Es hat mich sehr beeinflusst.","它对我影响很大。"],["die Hauptidee","核心观点"],["jeden Tag ein bisschen besser werden","每天进步一点点"],["Das hat mir die Augen geöffnet.","这让我茅塞顿开。"],["etwas in die Praxis umsetzen","把某事付诸实践"],["seitdem","从那以后"]],"sample":"Ein Buch, das mich sehr beeinflusst hat, ist „Atomic Habits“ von James Clear. Ich habe es vor zwei Jahren gelesen, als ich gerade nach Kuala Lumpur gezogen war. Es geht darum, wie kleine Gewohnheiten unser Leben verändern. Die Hauptidee ist: Man muss nicht sofort alles perfekt machen, sondern jeden Tag nur ein bisschen besser werden. Das hat mir wirklich die Augen geöffnet. Früher wollte ich große Ziele immer sehr schnell erreichen und habe dann oft aufgegeben. Seitdem versuche ich, die Ideen aus dem Buch in die Praxis umzusetzen. Zum Beispiel lerne ich jeden Tag nur fünfzehn Minuten Deutsch, aber dafür wirklich jeden Tag. Und es funktioniert!","samplezh":"对我影响很大的一本书是詹姆斯·克利尔的《掌控习惯》（Atomic Habits）。我是两年前刚搬到吉隆坡的时候读的。书里讲的是小习惯怎样改变我们的生活。核心观点是：不用一下子把所有事都做到完美，只要每天进步一点点。这真的让我茅塞顿开。以前我总想很快实现大目标，结果经常半途而废。从那以后，我试着把书里的方法付诸实践。比如我每天只学十五分钟德语，但真的是每天都学。而且很有效！"},{"id":"learning_german","cat":"兴趣","level":"进阶","q":"Wie lernst du Deutsch, und was ist für dich am schwierigsten?","qzh":"你是怎么学德语的？对你来说最难的是什么？","points":["Warum du Deutsch lernst","Wie und wie oft du lernst","Was am schwierigsten ist","Was dir hilft"],"phrases":[["die Artikel der, die, das","冠词 der、die、das"],["auswendig lernen","死记硬背"],["Das Verb steht am Ende.","动词放在句末。"],["Ich verwechsle oft …","我经常搞混……"],["kaum Gelegenheiten haben","几乎没有机会"],["Ich bleibe dran!","我会坚持下去！"]],"sample":"Ich lerne seit ungefähr drei Monaten Deutsch, vor allem wegen unserer Kunden aus Deutschland und weil ich irgendwann dort arbeiten möchte. Ich lerne jeden Tag mit einer App und mit einem Online-Kurs. Abends übe ich auch das Sprechen, weil ich in Kuala Lumpur kaum Gelegenheiten habe, Deutsch zu sprechen. Am schwierigsten sind für mich die Artikel. Warum heißt es der Tisch, aber die Tür und das Fenster? Das muss man einfach auswendig lernen. Auch die Wortstellung ist nicht leicht, denn in Nebensätzen steht das Verb am Ende. Und ich verwechsle oft „ü“ und „u“. Aber Fehler gehören dazu, denn so lerne ich. Ich bleibe dran!","samplezh":"我学德语大概三个月了，主要是因为我们有德国客户，而且我以后想去那里工作。我每天用一个应用和一门网课学习。晚上我还会练口语，因为在吉隆坡几乎没有机会说德语。对我来说最难的是冠词。为什么是 der Tisch（桌子），却是 die Tür（门）和 das Fenster（窗户）？这只能死记硬背。语序也不容易，因为在从句里动词要放在句末。我还经常搞混 ü 和 u。不过犯错是学习的一部分，我就是这样学的。我会坚持下去！"},{"id":"ai_and_jobs","cat":"观点","level":"进阶","q":"Glaubst du, dass künstliche Intelligenz den Menschen die Arbeit wegnimmt?","qzh":"你觉得人工智能会抢走人们的工作吗？","points":["Welche Jobs sich verändern","Wie du KI bei der Arbeit nutzt","Chancen und Risiken","Deine Meinung"],"phrases":[["künstliche Intelligenz (KI)","人工智能"],["Meiner Meinung nach …","在我看来……"],["Einerseits …, andererseits …","一方面……另一方面……"],["Das macht mir ein bisschen Angst.","这让我有点害怕。"],["sich anpassen","适应"],["immer weiterlernen","不断学习"]],"sample":"Das ist eine schwierige Frage. Meiner Meinung nach wird KI viele Jobs verändern, aber nicht alle ersetzen. Ich benutze KI-Tools schon jeden Tag bei der Arbeit. Sie schreiben einfachen Code, erklären Fehler und sparen mir viel Zeit. Einerseits ist das toll, weil ich mich auf die interessanten Aufgaben konzentrieren kann. Andererseits macht es mir ein bisschen Angst, denn die Tools werden jedes Jahr besser. Vielleicht braucht eine Firma in Zukunft weniger Entwickler. Ich glaube aber, dass Menschen immer noch wichtig sind, zum Beispiel für Kommunikation, Kreativität und Verantwortung. Man muss sich anpassen und immer weiterlernen. Wer das macht, hat auch in Zukunft gute Chancen.","samplezh":"这是个很难的问题。在我看来，人工智能会改变很多工作，但不会全部取代。我现在每天工作都用 AI 工具。它们能写简单的代码、解释错误，帮我省下很多时间。一方面这很棒，因为我可以专注于有意思的任务。另一方面这又让我有点害怕，因为这些工具每年都在变强。也许将来一家公司需要的开发人员会更少。不过我相信人还是很重要的，比如在沟通、创造力和承担责任方面。人要适应，要不断学习。这样做的人，将来也会有好机会。"},{"id":"social_media","cat":"观点","level":"进阶","q":"Schaden soziale Medien mehr, als sie nützen?","qzh":"社交媒体弊大于利吗？","points":["Wie du soziale Medien nutzt","Vorteile","Nachteile","Deine Meinung"],"phrases":[["Es kommt darauf an, wie …","这取决于如何……"],["in Kontakt bleiben","保持联系"],["süchtig machen","让人上瘾"],["Fake News verbreiten sich schnell.","假新闻传播得很快。"],["sich mit anderen vergleichen","和别人比较"],["Ich bin der Meinung, dass …","我认为……"]],"sample":"Ich bin der Meinung, dass es darauf ankommt, wie man soziale Medien benutzt. Für mich sind sie sehr praktisch. Ich lebe weit weg von meiner Familie, und über WeChat bleiben wir jeden Tag in Kontakt. Ich sehe Fotos von meinen Freunden und lerne sogar Deutsch mit kurzen Videos. Aber es gibt auch große Nachteile. Viele Apps machen süchtig, und man verliert viel Zeit. Außerdem verbreiten sich Fake News sehr schnell. Für junge Leute ist es besonders gefährlich, weil sie sich ständig mit anderen vergleichen. Alle zeigen nur ihr perfektes Leben. Insgesamt glaube ich, dass soziale Medien nicht nur schlecht sind. Man muss aber lernen, sie bewusst zu nutzen.","samplezh":"我认为这取决于怎么使用社交媒体。对我来说它们很实用。我离家人很远，通过微信我们每天都保持联系。我能看到朋友的照片，甚至还用短视频学德语。但它也有很大的缺点。很多应用让人上瘾，浪费很多时间。另外假新闻传播得很快。对年轻人来说尤其危险，因为他们总在和别人比较。每个人都只展示自己完美的生活。总的来说，我觉得社交媒体并不全是坏的，但我们得学会有意识地使用它。"},{"id":"remote_vs_office","cat":"观点","level":"进阶","q":"Ist Homeoffice besser als die Arbeit im Büro?","qzh":"在家办公比在办公室上班更好吗？","points":["Vorteile vom Homeoffice","Vorteile vom Büro","Für wen was besser ist","Deine Meinung"],"phrases":[["Beides hat Vor- und Nachteile.","两者各有利弊。"],["pendeln","通勤"],["der persönliche Kontakt","面对面的接触"],["spontan Fragen stellen","随时提问"],["Im Großen und Ganzen …","总的来说……"],["das Beste aus beiden Welten","两全其美"]],"sample":"Ich finde, beides hat Vor- und Nachteile. Im Homeoffice spart man Zeit und Geld, weil man nicht pendeln muss. Man hat flexiblere Arbeitszeiten und kann sich oft besser konzentrieren. Im Büro ist dagegen der persönliche Kontakt viel besser. Man kann spontan Fragen stellen, und nach der Arbeit geht man vielleicht zusammen essen. Besonders für Berufsanfänger ist das Büro wichtig, weil sie viel von den Kollegen lernen. Als ich angefangen habe, hat mir das sehr geholfen. Für erfahrene Leute ist Homeoffice dagegen oft effizienter. Im Großen und Ganzen finde ich ein Hybridmodell am besten, also zwei oder drei Tage im Büro und den Rest zu Hause. Das ist das Beste aus beiden Welten.","samplezh":"我觉得两者各有利弊。在家办公省时间也省钱，因为不用通勤。工作时间更灵活，往往也更能集中注意力。而在办公室，面对面的接触要好得多。可以随时提问，下班后说不定还能一起去吃饭。尤其对职场新人来说，办公室很重要，因为他们能从同事那里学到很多。我刚入行的时候，这对我帮助很大。而对有经验的人来说，在家办公往往效率更高。总的来说，我觉得混合模式最好，就是两三天在办公室，其余时间在家。这样两全其美。"},{"id":"city_vs_countryside","cat":"观点","level":"基础","q":"Lebt man besser in einer Großstadt oder auf dem Land?","qzh":"住在大城市好还是住在乡下好？","points":["Vorteile der Großstadt","Vorteile vom Land","Deine eigenen Erfahrungen","Wo du in Zukunft leben möchtest"],"phrases":[["in einer Großstadt","在大城市"],["auf dem Land","在乡下"],["Es ist immer viel los.","总是很热闹。"],["Man hat mehr Möglichkeiten.","机会更多。"],["frische Luft und viel Natur","新鲜空气和大自然"],["Für mich persönlich …","对我个人来说……"]],"sample":"Für mich persönlich ist die Großstadt im Moment besser. In Kuala Lumpur ist immer viel los. Es gibt viele Jobs, Restaurants, Einkaufszentren und Leute aus der ganzen Welt. Als junger Mensch hat man in der Stadt einfach mehr Möglichkeiten. Aber die Stadt hat auch Nachteile: Es gibt viel Verkehr, es ist laut, und die Mieten sind hoch. Auf dem Land ist das Leben ruhiger und billiger. Man hat frische Luft und viel Natur, und man kennt seine Nachbarn. Meine Großeltern leben auf dem Land, und ich besuche sie gern. Wenn ich älter bin, möchte ich vielleicht auch in einem kleinen Ort wohnen, aber nicht zu weit weg von einer Stadt.","samplezh":"对我个人来说，现在还是大城市更好。吉隆坡总是很热闹。有很多工作机会、餐厅、商场，还有来自世界各地的人。年轻人在城市里就是机会更多。但城市也有缺点：车多、吵闹、房租贵。乡下的生活更安静，也更便宜。有新鲜空气和大自然，还认识自己的邻居。我的爷爷奶奶住在乡下，我很喜欢去看他们。等我老一点，也许我也想住在一个小地方，但不要离城市太远。"},{"id":"money_vs_happiness","cat":"观点","level":"进阶","q":"Kann man mit Geld Glück kaufen?","qzh":"金钱能买到幸福吗？","points":["Was Geld möglich macht","Was man nicht kaufen kann","Ein Beispiel aus deinem Leben","Deine Meinung"],"phrases":[["Ich würde sagen, …","我会说……"],["bis zu einem gewissen Punkt","在一定程度上"],["sich Sorgen um … machen","为……担心"],["finanzielle Sicherheit","经济上的安全感"],["Geld allein macht nicht glücklich.","光有钱不能让人幸福。"],["Zeit mit der Familie verbringen","和家人共度时光"]],"sample":"Ich würde sagen: bis zu einem gewissen Punkt schon. Wenn man genug Geld hat, muss man sich keine Sorgen um die Miete oder um Rechnungen machen. Finanzielle Sicherheit ist sehr wichtig. Außerdem kann man reisen, gut essen und seiner Familie helfen. Aber Geld allein macht nicht glücklich. Ich kenne Leute, die sehr viel verdienen, aber immer gestresst sind und keine Zeit für ihre Familie haben. Für mich sind Gesundheit, Freunde und Zeit mit der Familie viel wichtiger. Ein Beispiel: Mein schönster Moment im letzten Jahr war kein teures Geschenk, sondern ein einfaches Abendessen mit meinen Eltern zum Frühlingsfest. Das kann man mit keinem Geld der Welt kaufen.","samplezh":"我会说：在一定程度上可以。钱够用的话，就不用为房租或账单发愁。经济上的安全感非常重要。另外还可以旅行、吃好的、帮助家人。但光有钱不能让人幸福。我认识一些人，赚得很多，却总是压力很大，没时间陪家人。对我来说，健康、朋友和陪家人的时间重要得多。举个例子：我去年最美好的时刻不是一件昂贵的礼物，而是春节和父母一起吃的一顿简单的晚饭。这是用世界上多少钱都买不到的。"},{"id":"why_learn_languages","cat":"观点","level":"基础","q":"Warum lohnt es sich, Fremdsprachen zu lernen?","qzh":"为什么学外语是值得的？","points":["Vorteile für den Beruf","Vorteile beim Reisen","Andere Kulturen verstehen","Deine eigenen Erfahrungen"],"phrases":[["Es lohnt sich auf jeden Fall.","这绝对值得。"],["Erstens …, zweitens …, drittens …","第一……第二……第三……"],["bessere Chancen im Beruf","更好的职业机会"],["mit Einheimischen sprechen","和当地人交谈"],["eine andere Kultur besser verstehen","更好地了解另一种文化"],["Geduld brauchen","需要耐心"]],"sample":"Ich finde, es lohnt sich auf jeden Fall, Fremdsprachen zu lernen. Erstens hat man bessere Chancen im Beruf. Ohne Englisch hätte ich zum Beispiel meinen Job in Kuala Lumpur nicht bekommen. Zweitens macht Reisen viel mehr Spaß, wenn man mit Einheimischen sprechen kann. Man kann nach dem Weg fragen, im Restaurant bestellen und versteht einfach mehr. Drittens versteht man durch eine Sprache auch eine andere Kultur besser. Seit ich Deutsch lerne, interessiere ich mich zum Beispiel viel mehr für deutsche Geschichte und deutsche Filme. Natürlich braucht man Zeit und Geduld. Aber ich habe das Gefühl, dass sich mit jeder neuen Sprache eine neue Welt öffnet.","samplezh":"我觉得学外语绝对值得。第一，职业机会更好。比如说，如果不会英语，我就得不到吉隆坡这份工作。第二，能和当地人交流的话，旅行会有意思得多。可以问路、在餐厅点菜，而且就是能懂得更多。第三，通过一门语言，也能更好地了解另一种文化。比如自从学德语以后，我对德国历史和德国电影感兴趣多了。当然这需要时间和耐心。但我感觉，每多学一门语言，就打开了一个新世界。"}],"quick":[{"q":"Wie heißt du?","qzh":"你叫什么名字？","level":"入门","a":"Ich heiße Ray. Freut mich!","azh":"我叫 Rui，很高兴认识你！"},{"q":"Woher kommen Sie?","qzh":"您是哪里人？","level":"入门","a":"Ich komme aus China, aber ich wohne jetzt in Kuala Lumpur.","azh":"我来自中国，不过现在住在吉隆坡。"},{"q":"Wie geht's dir?","qzh":"你好吗？最近怎么样？","level":"入门","a":"Gut, danke! Ein bisschen müde, aber gut. Und dir?","azh":"挺好的，谢谢！有点累，但还不错。你呢？"},{"q":"Wo wohnst du?","qzh":"你住在哪里？","level":"入门","a":"In Kuala Lumpur. Ich habe eine kleine Wohnung in der Nähe vom Zentrum.","azh":"在吉隆坡。我在市中心附近有一套小公寓。"},{"q":"Was sind Sie von Beruf?","qzh":"您是做什么工作的？","level":"入门","a":"Ich bin Softwareentwickler.","azh":"我是软件开发工程师。"},{"q":"Sprechen Sie Deutsch?","qzh":"您会说德语吗？","level":"入门","a":"Ja, ein bisschen. Ich lerne noch.","azh":"会一点。我还在学。"},{"q":"Welche Sprachen sprichst du?","qzh":"你会说哪些语言？","level":"入门","a":"Chinesisch, Englisch und ein bisschen Deutsch.","azh":"中文、英语，还有一点德语。"},{"q":"Was hast du heute Mittag gegessen?","qzh":"你今天午饭吃了什么？","level":"入门","a":"Nasi Lemak, wie fast jeden Tag!","azh":"椰浆饭，几乎每天都吃！"},{"q":"Wie ist das Wetter heute?","qzh":"今天天气怎么样？","level":"入门","a":"Heiß und sonnig. Aber am Nachmittag regnet es bestimmt.","azh":"又热又晴。不过下午肯定会下雨。"},{"q":"Trinkst du lieber Kaffee oder Tee?","qzh":"你更喜欢喝咖啡还是茶？","level":"入门","a":"Lieber Kaffee. Ohne Kaffee kann ich morgens nicht arbeiten.","azh":"咖啡。早上不喝咖啡我没法工作。"},{"q":"Wie spät ist es?","qzh":"现在几点了？","level":"入门","a":"Es ist halb drei.","azh":"两点半。"},{"q":"Hast du gut geschlafen?","qzh":"你睡得好吗？","level":"入门","a":"Nicht so gut. Ich bin zu spät ins Bett gegangen.","azh":"不太好。我睡得太晚了。"},{"q":"Was ist dein Lieblingsessen?","qzh":"你最喜欢吃什么？","level":"入门","a":"Nudelsuppe! Und malaysisches Essen mag ich auch sehr.","azh":"汤面！马来西亚菜我也很喜欢。"},{"q":"Hast du Haustiere?","qzh":"你养宠物吗？","level":"入门","a":"Nein, leider nicht. Aber ich hätte gern eine Katze.","azh":"没有，可惜。不过我很想养只猫。"},{"q":"Wie kommst du zur Arbeit?","qzh":"你怎么去上班？","level":"入门","a":"Meistens mit der U-Bahn. Das dauert ungefähr dreißig Minuten.","azh":"一般坐地铁，大概要三十分钟。"},{"q":"Hast du heute Abend Zeit?","qzh":"你今晚有空吗？","level":"入门","a":"Ja, ich habe Zeit. Was wollen wir machen?","azh":"有空。我们做点什么？"},{"q":"Was machst du am Wochenende?","qzh":"你周末做什么？","level":"入门","a":"Ich treffe mich mit Freunden. Vielleicht gehen wir essen.","azh":"我和朋友见面。可能一起去吃饭。"},{"q":"Sind Sie zum ersten Mal in Deutschland?","qzh":"您是第一次来德国吗？","level":"入门","a":"Ja, ich bin zum ersten Mal hier. Es gefällt mir sehr gut!","azh":"是的，这是我第一次来。我很喜欢这里！"},{"q":"Wie war dein Tag?","qzh":"你今天过得怎么样？","level":"入门","a":"Ganz gut, aber sehr lang. Ich hatte drei Meetings.","azh":"还不错，但很漫长。我开了三个会。"},{"q":"Kochst du zu Hause?","qzh":"你在家做饭吗？","level":"入门","a":"Manchmal, am Wochenende. Unter der Woche bestelle ich meistens.","azh":"有时候，周末做。工作日大多点外卖。"},{"q":"Wie ist Ihre Telefonnummer?","qzh":"您的电话号码是多少？","level":"入门","a":"Null eins zwei, drei vier fünf, sechs sieben acht neun.","azh":"012-345-6789。"},{"q":"Haben Sie Geschwister?","qzh":"您有兄弟姐妹吗？","level":"入门","a":"Ja, ich habe eine ältere Schwester. Sie wohnt in China.","azh":"有，我有一个姐姐。她住在中国。"},{"q":"Wie schreibt man Ihren Namen?","qzh":"您的名字怎么拼写？","level":"入门","a":"R – A – Y. Ray.","azh":"R、A、Y，Ray。（德语字母读作 Er – A – Ypsilon）"},{"q":"Was möchten Sie trinken?","qzh":"您想喝点什么？","level":"入门","a":"Ein Wasser, bitte. Ohne Kohlensäure.","azh":"一杯水，谢谢。不要气泡的。"},{"q":"Wie alt bist du?","qzh":"你多大了？","level":"入门","a":"Ich bin achtundzwanzig.","azh":"我二十八岁。"},{"q":"Seit wann lernst du Deutsch?","qzh":"你学德语多久了？","level":"基础","a":"Seit ungefähr drei Monaten. Ich lerne jeden Tag ein bisschen.","azh":"大概三个月了。我每天学一点。"},{"q":"Wie lange wohnen Sie schon in Kuala Lumpur?","qzh":"您在吉隆坡住多久了？","level":"基础","a":"Seit ungefähr zwei Jahren.","azh":"大概两年了。"},{"q":"Warum lernst du Deutsch?","qzh":"你为什么学德语？","level":"基础","a":"Weil wir Kunden aus Deutschland haben. Und ich möchte irgendwann dort arbeiten.","azh":"因为我们有德国客户。而且我以后想去那里工作。"},{"q":"Was hast du letztes Wochenende gemacht?","qzh":"你上周末做了什么？","level":"基础","a":"Ich war mit Freunden wandern, und abends haben wir zusammen gegessen.","azh":"我和朋友去徒步了，晚上一起吃了饭。"},{"q":"Was machst du nach der Arbeit?","qzh":"你下班后做什么？","level":"基础","a":"Meistens gehe ich ins Fitnessstudio, und danach lerne ich ein bisschen Deutsch.","azh":"一般去健身房，然后学一会儿德语。"},{"q":"Was machst du in deiner Freizeit?","qzh":"你空闲时间做什么？","level":"基础","a":"Ich gehe gern wandern und probiere neue Restaurants aus.","azh":"我喜欢徒步，也喜欢尝试新餐厅。"},{"q":"Was hast du im Urlaub vor?","qzh":"你假期有什么打算？","level":"基础","a":"Ich fliege nach Hause zu meiner Familie. Darauf freue ich mich schon.","azh":"我要飞回家看家人。我已经很期待了。"},{"q":"Was für Musik hörst du gern?","qzh":"你喜欢听什么音乐？","level":"基础","a":"Pop, und beim Arbeiten ruhige Musik ohne Gesang.","azh":"流行乐，工作时听没有人声的轻音乐。"},{"q":"Hast du in letzter Zeit einen guten Film gesehen?","qzh":"你最近看过什么好电影吗？","level":"基础","a":"Keinen Film, aber eine Serie: „Dark“. Sehr spannend!","azh":"电影没有，但看了一部剧：《暗黑》。特别精彩！"},{"q":"Was gefällt dir am besten an Kuala Lumpur?","qzh":"你最喜欢吉隆坡的什么？","level":"基础","a":"Das Essen! Und dass die Stadt so international ist.","azh":"吃的！还有这座城市很国际化。"},{"q":"Wie lange brauchst du zur Arbeit?","qzh":"你上班路上要多久？","level":"基础","a":"Ungefähr eine halbe Stunde mit der U-Bahn.","azh":"坐地铁大概半小时。"},{"q":"Woran arbeitest du gerade?","qzh":"你现在在做什么项目？","level":"基础","a":"An einer App für einen Kunden in Deutschland. Wir sind fast fertig.","azh":"在给一个德国客户做应用。我们快完成了。"},{"q":"Wo haben Sie Programmieren gelernt?","qzh":"您在哪里学的编程？","level":"基础","a":"An der Uni in China, aber das meiste habe ich mir selbst beigebracht.","azh":"在中国上大学时学的，不过大部分是自学的。"},{"q":"Arbeiten Sie auch im Homeoffice?","qzh":"您也在家办公吗？","level":"基础","a":"Ja, zweimal pro Woche. An den anderen Tagen bin ich im Büro.","azh":"是的，每周两天。其他几天在办公室。"},{"q":"Was möchtest du dieses Jahr noch lernen?","qzh":"你今年还想学点什么？","level":"基础","a":"Natürlich Deutsch! Und vielleicht ein bisschen Gitarre.","azh":"当然是德语！也许再学点吉他。"},{"q":"Wie war das Meeting?","qzh":"会开得怎么样？","level":"基础","a":"Ganz gut, aber ein bisschen zu lang. Wir haben viel diskutiert.","azh":"还行，就是有点太长了。我们讨论了很多。"},{"q":"Hast du schon mal Durian probiert?","qzh":"你吃过榴莲吗？","level":"基础","a":"Ja, einmal. Ehrlich gesagt war das nichts für mich.","azh":"吃过一次。说实话，我不太能接受。"},{"q":"Wann stehst du normalerweise auf?","qzh":"你一般几点起床？","level":"基础","a":"Um sieben, aber am Wochenende schlafe ich aus.","azh":"七点，不过周末我会睡懒觉。"},{"q":"Kommst du am Freitag zum Teamessen?","qzh":"你周五来参加团队聚餐吗？","level":"基础","a":"Ja, klar! Wo treffen wir uns?","azh":"当然！我们在哪儿见？"},{"q":"Wie entspannst du dich am liebsten?","qzh":"你最喜欢怎么放松？","level":"基础","a":"Ich schaue eine Serie oder gehe spazieren, wenn es nicht zu heiß ist.","azh":"看剧，或者不太热的时候出去散散步。"},{"q":"Wie ist deine Wohnung?","qzh":"你的公寓怎么样？","level":"基础","a":"Klein, aber gemütlich. Sie hat ein Schlafzimmer und einen schönen Blick auf die Stadt.","azh":"不大，但很舒适。有一个卧室，能看到很美的城市景色。"},{"q":"Hattest du in letzter Zeit viel zu tun?","qzh":"你最近很忙吗？","level":"基础","a":"Ja, sehr viel. Wir haben nächste Woche eine Deadline.","azh":"是的，特别忙。我们下周有个截止日期。"},{"q":"Können Sie mir ein Restaurant hier in der Nähe empfehlen?","qzh":"您能推荐一家附近的餐厅吗？","level":"基础","a":"Ja, um die Ecke gibt es ein gutes Mamak-Restaurant. Es ist günstig und lange geöffnet.","azh":"可以，拐角处有一家不错的嘛嘛档。便宜，而且营业到很晚。"},{"q":"Warst du schon mal in Deutschland?","qzh":"你去过德国吗？","level":"基础","a":"Nein, noch nicht. Aber ich möchte nächstes Jahr hinfliegen.","azh":"还没有。不过我想明年飞过去。"},{"q":"Was hast du gestern Abend gemacht?","qzh":"你昨晚做了什么？","level":"基础","a":"Ich habe Deutsch gelernt und dann ein bisschen ferngesehen.","azh":"我学了德语，然后看了一会儿电视。"},{"q":"Was gefällt Ihnen an Ihrer Arbeit am besten?","qzh":"您最喜欢自己工作的哪一点？","level":"进阶","a":"Dass ich jeden Tag Probleme löse und etwas Neues lerne. Das wird nie langweilig.","azh":"每天都能解决问题、学到新东西。永远不会无聊。"},{"q":"Was ist das Schwierigste an deinem Job?","qzh":"你工作中最难的是什么？","level":"进阶","a":"Die Kommunikation mit Kunden. Manchmal wissen sie selbst nicht genau, was sie wollen.","azh":"和客户沟通。有时候他们自己都不清楚想要什么。"},{"q":"Glaubst du, dass KI Entwickler ersetzen wird?","qzh":"你觉得 AI 会取代开发人员吗？","level":"进阶","a":"Nicht ganz. Aber Entwickler, die KI gut nutzen, werden die anderen ersetzen.","azh":"不会完全取代。但会用 AI 的开发者会取代不会用的。"},{"q":"Würdest du lieber zu Hause oder im Büro arbeiten?","qzh":"你更愿意在家还是在办公室工作？","level":"进阶","a":"Am liebsten beides: zwei Tage zu Hause und drei Tage im Büro.","azh":"最好两者都有：两天在家，三天在办公室。"},{"q":"Wo sehen Sie sich in fünf Jahren?","qzh":"您觉得五年后的自己会在哪里？","level":"进阶","a":"Ich möchte gern ein kleines Team leiten, vielleicht sogar in Deutschland.","azh":"我想带一个小团队，说不定是在德国。"},{"q":"Was ist der größte Unterschied zwischen China und Malaysia?","qzh":"中国和马来西亚最大的不同是什么？","level":"进阶","a":"Malaysia ist viel multikultureller. Hier hört man jeden Tag vier oder fünf Sprachen.","azh":"马来西亚更多元文化。在这里每天能听到四五种语言。"},{"q":"Was machen Sie, wenn Sie eine Deadline nicht schaffen?","qzh":"如果赶不上截止日期，您会怎么做？","level":"进阶","a":"Ich sage früh genug Bescheid und erkläre, warum. Dann suchen wir zusammen eine Lösung.","azh":"我会提前告知并解释原因。然后我们一起想办法。"},{"q":"Wie gehst du mit Stress bei der Arbeit um?","qzh":"你怎么应对工作压力？","level":"进阶","a":"Ich mache eine kurze Pause, gehe ein paar Minuten spazieren und schreibe mir dann eine Liste.","azh":"我会短暂休息一下，散几分钟步，然后列一张清单。"},{"q":"Wenn du überall leben könntest, wo wäre das?","qzh":"如果可以住在任何地方，你会选哪里？","level":"进阶","a":"Vielleicht in München. Die Stadt ist schön, und die Berge sind nicht weit.","azh":"也许是慕尼黑。城市很美，离山也不远。"},{"q":"Was würden Sie an Ihrer Stadt ändern?","qzh":"您想改变自己城市的什么？","level":"进阶","a":"Ich würde mehr Gehwege bauen, damit man nicht für jede kurze Strecke ein Auto braucht.","azh":"我会修更多人行道，这样短距离出行就不用每次都开车或叫车。"}],"starter":{"rescue":[{"en":"Wie bitte?","zh":"什么？请再说一遍？","when":"没听清时"},{"en":"Können Sie das bitte wiederholen?","zh":"您能再说一遍吗？","when":"请对方重复"},{"en":"Können Sie bitte etwas langsamer sprechen?","zh":"您能说慢一点吗？","when":"对方说太快"},{"en":"Langsamer, bitte.","zh":"请慢一点。","when":"简短地请对方放慢"},{"en":"Das habe ich nicht ganz verstanden.","zh":"我没完全听懂。","when":"听懂一半"},{"en":"Was bedeutet „…“?","zh":"“……”是什么意思？","when":"听到生词"},{"en":"Was meinen Sie damit?","zh":"您这是什么意思？","when":"不懂对方意思"},{"en":"Können Sie das bitte aufschreiben?","zh":"您能写下来吗？","when":"听不清名字、数字"},{"en":"Können Sie das bitte buchstabieren?","zh":"您能拼一下吗？","when":"需要拼写"},{"en":"Können Sie das anders erklären?","zh":"您能换种方式解释吗？","when":"解释了还是不懂"},{"en":"Wie sagt man das auf Deutsch?","zh":"这个用德语怎么说？","when":"不会某个词"},{"en":"Wie heißt das noch mal?","zh":"那个叫什么来着？","when":"话到嘴边说不出"},{"en":"Es liegt mir auf der Zunge.","zh":"话就在嘴边。","when":"一时想不起"},{"en":"Ich weiß nicht, wie man das sagt.","zh":"我不知道这个怎么说。","when":"表达卡住"},{"en":"Das ist so ähnlich wie …","zh":"这有点像……","when":"用近义描述"},{"en":"Das braucht man zum …","zh":"这是……的时候用的东西。","when":"描述物品"},{"en":"Ich spreche nur ein bisschen Deutsch.","zh":"我只会说一点德语。","when":"先说明水平"},{"en":"Sprechen Sie Englisch?","zh":"您会说英语吗？","when":"实在不行换英语"},{"en":"Ich sage es mal anders.","zh":"我换个说法。","when":"换种方式表达"},{"en":"Ich meine …","zh":"我的意思是……","when":"修正自己的话"},{"en":"Was ich sagen will, ist: …","zh":"我想说的是：……","when":"重新组织"},{"en":"Moment, ich muss kurz überlegen.","zh":"等一下，我得想一想。","when":"需要思考"},{"en":"Einen Moment, bitte.","zh":"请稍等。","when":"需要几秒钟"},{"en":"Gute Frage!","zh":"好问题！","when":"边夸边想"},{"en":"Hm, wie soll ich sagen …","zh":"嗯，该怎么说呢……","when":"组织语言"},{"en":"Mal sehen …","zh":"我看看……","when":"回想或查找"},{"en":"Das ist schwer zu sagen.","zh":"这很难说。","when":"问题难答"},{"en":"Meinen Sie …?","zh":"您是说……吗？","when":"确认对方意思"},{"en":"Sie meinen also, dass …?","zh":"所以您的意思是……？","when":"复述确认"},{"en":"Habe ich das richtig gesagt?","zh":"我这样说对吗？","when":"确认发音或用法"},{"en":"Bitte korrigieren Sie mich, wenn ich Fehler mache.","zh":"我说错的话请纠正我。","when":"请对方纠错"},{"en":"Verstehen Sie, was ich meine?","zh":"您明白我的意思吗？","when":"确认对方听懂"},{"en":"Ist das richtig?","zh":"这样对吗？","when":"核对信息"},{"en":"Entschuldigung, darf ich Sie etwas fragen?","zh":"打扰一下，我能问您个问题吗？","when":"开口提问"},{"en":"Ach, nicht so wichtig.","zh":"哎，不重要。","when":"说不清就放弃"},{"en":"Entschuldigung, mein Deutsch ist noch nicht so gut.","zh":"不好意思，我的德语还不太好。","when":"先打预防针"},{"en":"Danke für Ihre Geduld!","zh":"谢谢您的耐心！","when":"感谢对方"},{"en":"Es war schön, mit Ihnen zu sprechen.","zh":"和您聊天很愉快。","when":"结束聊天"},{"en":"Ich muss jetzt leider los. Tschüss!","zh":"我得走了。再见！","when":"离开"},{"en":"Danke, das hilft mir sehr.","zh":"谢谢，这对我帮助很大。","when":"得到帮助后"}],"intro":[{"en":"Hallo, ich bin Ray. Freut mich!","zh":"你好，我叫 Rui，很高兴认识你！"},{"en":"Ich komme aus China, aber ich wohne jetzt in Malaysia.","zh":"我来自中国，不过现在住在马来西亚。"},{"en":"Ich wohne seit ungefähr zwei Jahren in Kuala Lumpur.","zh":"我在吉隆坡住了大概两年。"},{"en":"Ich bin Softwareentwickler.","zh":"我是软件开发工程师。"},{"en":"Ich entwickle vor allem Webseiten und Apps.","zh":"我主要做网站和应用。"},{"en":"Ich arbeite bei einer kleinen IT-Firma in der Nähe des KLCC.","zh":"我在 KLCC 附近的一家小 IT 公司上班。"},{"en":"In meiner Freizeit gehe ich gern wandern und probiere neues Essen aus.","zh":"空闲时间我喜欢徒步和尝试新美食。"},{"en":"Ich schaue auch viele YouTube-Videos, vor allem über Technik und Reisen.","zh":"我也看很多 YouTube，主要是科技和旅行视频。"},{"en":"Ich lerne seit drei Monaten Deutsch, weil wir Kunden in Deutschland haben.","zh":"我学德语三个月了，因为我们有德国客户。"},{"en":"Mein Deutsch ist noch nicht perfekt, aber ich übe jeden Tag.","zh":"我的德语还不够好，不过我每天都在练。"},{"en":"Am Anfang bin ich ein bisschen schüchtern, aber ich lerne gern neue Leute kennen.","zh":"我一开始有点害羞，但很喜欢认识新朋友。"},{"en":"Und du? Was machst du beruflich?","zh":"你呢？你是做什么工作的？"}],"week":[{"day":1,"title":"敢开口：Wie bitte? 和变音","goal_zh":"先学会听不懂时怎么办，再把 ä ö ü 读准","steps":[{"do_zh":"听一遍救命句里「没听清」到「解释了还是不懂」那几句，每句跟读 3 遍","sec":"rescue"},{"do_zh":"在发音页练 ä ö ü 那几组：ü 是嘴型像 u、舌头像 i，跟着示范读 5 分钟","sec":"pron"},{"do_zh":"挑 5 句你最可能用到的救命句（比如 Wie bitte?），大声说给自己听","sec":"rescue"}]},{"day":2,"title":"介绍自己","goal_zh":"能用 6 句话流利地介绍自己","steps":[{"do_zh":"复习昨天的 5 句救命句，再学「想不起词」那几句（Wie sagt man das auf Deutsch?）","sec":"rescue"},{"do_zh":"逐句跟读自我介绍，把名字、工作换成自己的；注意 Ich bin Softwareentwickler 职业前不加冠词","sec":"intro"},{"do_zh":"不看稿，录音说一遍自我介绍，回听一次","sec":"intro"}]},{"day":3,"title":"跟读找感觉","goal_zh":"模仿德语的语调和节奏，嘴巴先动起来","steps":[{"do_zh":"先看跟读页顶部的「怎么练」，再用「连续跟读」跟 5 句；德语本土词的重音大多在第一个音节（be-、ge-、ver- 等前缀和很多外来词除外）","sec":"shadow"},{"do_zh":"选一段简单的跟读材料，听一句停一句跟读","sec":"shadow"},{"do_zh":"挑 3 个难读的词（比如带 ch 或 r 的），在发音页重点练","sec":"pron"}]},{"day":4,"title":"第一段对话","goal_zh":"完整说出一段日常小对话","steps":[{"do_zh":"选一段面包店或咖啡馆点餐的对话，听两遍","sec":"dialog"},{"do_zh":"扮演其中一个角色，跟着对话一句一句说；和店员说话要用 Sie","sec":"dialog"},{"do_zh":"学 3 个常用功能句，比如 Ich hätte gern …（我想要……）和 Vielen Dank!","sec":"func"},{"do_zh":"复习「确认」那几句救命句（Meinen Sie …? / Ist das richtig?）","sec":"rescue"}]},{"day":5,"title":"3 秒快答","goal_zh":"听到问题 3 秒内用一句话回答","steps":[{"do_zh":"做 10 道入门快答题（Wie heißt du? Woher kommst du? …），先答再看参考答案","sec":"quick"},{"do_zh":"把答不出的题，跟读参考答案 2 遍","sec":"quick"},{"do_zh":"和 AI 进行第一次 3 分钟聊天，就聊你今天吃了什么","sec":"chat"}]},{"day":6,"title":"和 AI 聊天","goal_zh":"不怕说错，和 AI 连续聊 5 分钟","steps":[{"do_zh":"复习自我介绍，说给 AI 听","sec":"intro"},{"do_zh":"和 AI 聊你的工作和周末，卡住就用救命句","sec":"chat"},{"do_zh":"聊完点「结束并总结」，把 AI 改过的句子加进生词本；名词连同 der/die/das 一起记","sec":"chat"}]},{"day":7,"title":"第一个话题","goal_zh":"围绕一个话题说满 1 分钟","steps":[{"do_zh":"再做 10 道快答题，这次试试基础难度（Seit wann lernst du Deutsch? …）","sec":"quick"},{"do_zh":"选一个简单话题（比如「周末做什么」），先看提示词和例句","sec":"topic"},{"do_zh":"计时 1 分钟围绕话题说话，录音回听；注意动词放在第二位","sec":"topic"},{"do_zh":"回顾这一周，挑一句最有用的救命句读 5 遍","sec":"rescue"}]}]}};
